  "Systemd" \
  binary_app.summary.show_status \
  "show service status" \
  "查看服务状态" \
  binary_app.summary.live_logs \
  "tail live logs" \
  "实时查看日志" \
  binary_app.summary.restart \
  "restart service" \
  "重启服务"\
  binary_app.success.ufw_port \
  "ufw allows port %s." \
  "ufw 已放行端口 %s。" \
  binary_app.warn.firewall_config_failed \
  "Automatic firewall configuration failed for port %s. Open it manually or retry after fixing the firewall service." \
  "端口 %s 的防火墙自动配置失败。请在修复防火墙服务后重试，或手动放行该端口。" \
  binary_app.success.iptables_saved \
  "iptables rules persisted with netfilter-persistent." \
  "iptables 规则已持久化（netfilter-persistent）。" \
  binary_app.info.iptables_rules_written \
  "iptables rules written to /etc/iptables/rules.v4." \
  "iptables 规则已写入 /etc/iptables/rules.v4。" \
  binary_app.warn.iptables_write_failed \
  "Failed to write iptables rules; rules may be lost after reboot." \
  "iptables 规则写入失败，重启后规则可能丢失。" \
  binary_app.warn.iptables_not_persisted \
  "iptables rules are not persisted and may be lost after reboot. Recommended: apt-get install -y iptables-persistent && netfilter-persistent save" \
  "iptables 规则未持久化（重启后失效）。建议：apt-get install -y iptables-persistent && netfilter-persistent save。" \
  binary_app.success.iptables_port \
  "iptables allows port %s." \
  "iptables 已放行端口 %s。" \
  binary_app.warn.no_firewall \
  "No active firewall detected. If you use a cloud security group, allow port %s manually." \
  "未检测到活跃防火墙，如有云安全组（如 AWS/阿里云/腾讯云）请手动放行端口 %s。" \
  binary_app.success.logrotate \
  "Log rotation configured (daily rotation, 14 days retained, compressed automatically)." \
  "日志轮转已配置（每日轮转，保留 14 天，自动压缩）。" \
  binary_app.error.logrotate \
  "Logrotate config write failed: /etc/logrotate.d/%s" \
  "日志轮转配置写入失败：/etc/logrotate.d/%s。"

# Derive standard paths from the app configuration.  Apps may override
# APP_CONFIG_DERIVE_HOOK before load; this default matches the binary-app
# layout (binary under INSTALL_DIR, data and logs separated).
_binary_app_derive_paths() {
  BIN_PATH="${INSTALL_DIR}/${BA_BIN_NAME}"
  LOG_FILE="${LOG_DIR}/${BA_BIN_NAME}.log"
  ENV_FILE="/etc/${SERVICE_NAME}.env"
  # Default to loopback: a plain-HTTP service on 0.0.0.0 is directly exposed
  # to the network.  Publish through a reverse proxy, or set BA_BIND_ADDR
  # explicitly when the app is designed to listen publicly (e.g. frps).
  BA_BIND_ADDR="${BA_BIND_ADDR:-127.0.0.1}"
  # Backup archive prefix; defaults to APP_ID. Apps migrating from a
  # hand-written lifecycle may pin the historical prefix to keep existing
  # backup archives discoverable (e.g. BA_ARCHIVE_PREFIX=new-api).
  BA_ARCHIVE_PREFIX="${BA_ARCHIVE_PREFIX:-${APP_ID}}"
}
# systemd unit directives (ExecStart, ReadWritePaths) cannot contain
# whitespace; reject any custom path early so it cannot silently break the
# generated unit file.
bapp_validate_no_whitespace() {
  local name="$1" value="$2"
  if [[ "$value" =~ [[:space:]] ]]; then
    error "$(t binary_app.error.path_whitespace "$name" "$value")"
  fi
}

# Shared validators run for every binary app; apps add checks through
# ba_validate_extra when they need more.
bapp_validate_cfg() {
  local attr rw_path
  app_validate_port "$PORT" "PORT"
  app_validate_domain "DOMAIN" "$DOMAIN"
  app_validate_systemd_name "SERVICE_NAME" "$SERVICE_NAME"
  app_validate_system_name "SERVICE_USER" "$SERVICE_USER"
  app_validate_github_repo "GITHUB_REPO" "$GITHUB_REPO"
  require_safe_path "INSTALL_DIR" "$INSTALL_DIR"
  require_safe_path "BIN_PATH" "$BIN_PATH"
  require_safe_path "DATA_DIR" "$DATA_DIR"
  require_safe_path "LOG_DIR" "$LOG_DIR"
  require_safe_path "BACKUP_DIR" "${BACKUP_DIR:-}"
  for attr in INSTALL_DIR BIN_PATH DATA_DIR LOG_DIR BACKUP_DIR; do
    bapp_validate_no_whitespace "$attr" "${!attr}"
  done
  if [[ -n "${BA_READWRITE_PATHS:-}" ]]; then
    for rw_path in ${BA_READWRITE_PATHS}; do
      require_safe_path "BA_READWRITE_PATHS" "$rw_path"
      bapp_validate_no_whitespace "BA_READWRITE_PATHS" "$rw_path"
    done
  fi
  # Retention must be a non-negative integer so pruning never removes the
  # whole backup directory via a malformed `-mtime` argument.
  if ! [[ "${BACKUP_KEEP_DAYS:-0}" =~ ^[0-9]+$ ]]; then
    error "$(t binary_app.error.backup_keep_days "${BACKUP_KEEP_DAYS:-unset}")"
  fi
  # The bind address must be a concrete IP (loopback or wildcard); anything
  # else would silently break the generated service/config.
  case "${BA_BIND_ADDR:-127.0.0.1}" in
    127.0.0.1|0.0.0.0|::1|::) : ;;
    *) error "$(t binary_app.error.bind_addr "${BA_BIND_ADDR:-unset}")" ;;
  esac
  # A pinned version must look like a GitHub release tag (vX.Y.Z); anything
  # else would produce a broken download URL.
  if [[ -n "${BA_VERSION:-}" ]] && ! [[ "$BA_VERSION" =~ ^v[0-9]+\.[0-9]+\.[0-9]+([.-][0-9A-Za-z.-]+)?$ ]]; then
    error "$(t binary_app.error.pinned_version_invalid "$BA_VERSION")"
  fi
  app_validate_bool "BA_ENABLE_HTTPS" "${BA_ENABLE_HTTPS:-0}"
  app_enforce_secure_public_bind "${BA_BIND_ADDR:-127.0.0.1}" "${BA_ENABLE_HTTPS:-0}" "${APP_NAME:-app}"
  if declare -f ba_validate_extra >/dev/null 2>&1; then
    ba_validate_extra
  fi
}

# Wire app_conf_file/app_lock_file once APP_ID is known (called from the
# impl after configuration defaults and hooks are declared).
binary_app_bootstrap() {
  APP_CONFIG_DERIVE_HOOK=_binary_app_derive_paths
  APP_STATUS_BACKUP_FN=bapp_status_backup_json
  CONF_FILE="$(app_conf_file)"
  LOCK_FILE="$(app_lock_file)"
  _binary_app_derive_paths
  bapp_validate_cfg
}

# Status adapters used by the central status and check-update commands. These
# deliberately share only the GitHub-release binary lifecycle: applications
# with custom update logic must opt in with their own adapter instead.
bapp_status_backup_json() {
  app_status_backup_json "BACKUP_DIR" "${BACKUP_DIR:-}" \
    "backup directory is unsafe or missing" "${BA_ARCHIVE_PREFIX:-${APP_ID}}_*.tar.gz"
}
bapp_status_version_json() {
  local conf_file installed
  conf_file="$(app_conf_file)"
  installed="$(app_config_installed_version "$conf_file" 2>/dev/null || true)"
  version_check_cached_binary_release_json "$APP_ID" "$installed"
}

bapp_check_update_json() {
  local installed="$1" refresh="${2:-0}" no_network="${3:-0}"
  version_check_binary_release_json "$APP_ID" "${GITHUB_REPO:-}" "$installed" "$refresh" "$no_network"
}

# Root/apt/arch preflight shared by install, update, backup, and uninstall.
bapp_preflight() {
  local action="${1:-}"
  if [[ "$action" != "status" && ${EUID:-$(id -u)} -ne 0 ]]; then
    error "$(t error.root_required "$0" "$action")"
  fi
  command -v apt-get >/dev/null 2>&1 \
    || error "$(t binary_app.error.apt_only)"
  case "$(uname -m)" in
    x86_64) BA_ARCH="amd64" ;;
    aarch64) BA_ARCH="arm64" ;;
    *) error "$(t binary_app.error.arch "$(uname -m)")" ;;
  esac
  if declare -f ba_preflight_extra >/dev/null 2>&1; then
    ba_preflight_extra "$action"
  fi
}

# Verify network reachability to the release host(s).
bapp_check_net() {
  app_check_connectivity binary_app.error.github_unreachable \
    "https://api.github.com" \
    "https://github.com" \
    "https://objects.githubusercontent.com"
}

# Echo the release tag to install: BA_VERSION pins a specific release (e.g.
# "v1.2.3"), otherwise the latest release tag is used. Pinned installs make
# deployments reproducible; update() upgrades to BA_VERSION when it is set
# (explicit upgrade) instead of silently drifting to the newest release.
ba_resolve_version() {
  if [[ -n "${BA_VERSION:-}" ]]; then
    printf '%s\n' "$BA_VERSION"
    return 0
  fi
  ba_latest_version
}

# Echo the latest release tag for GITHUB_REPO, or the empty string.
ba_latest_version() {
  local tag
  tag="$(github_latest_release_tag "$GITHUB_REPO" "binary_app.warn.github_api")"
  printf '%s\n' "$tag"
}

# Default release download URL: one asset from the version tag.  Apps whose
# asset naming differs override ba_asset_name (and optionally ba_download_urls).
ba_asset_name() {
  local version="$1"
  printf '%s\n' "${BA_ASSET_TEMPLATE//ARCH/${BA_ARCH}}"
}

ba_download_urls() {
  local version="$1" asset
  asset="$(ba_asset_name "$version")"
  printf 'https://github.com/%s/releases/download/%s/%s\n' "$GITHUB_REPO" "$version" "$asset"
}

# Download the first reachable URL for the given version into $1.
ba_download_release() {
  local version="$1" target="$2" url
  while IFS= read -r url; do
    [[ -n "$url" ]] || continue
    if curl -fL --progress-bar -o "$target" "$url"; then
      return 0
    fi
    rm -f "$target" 2>/dev/null || true
  done < <(ba_download_urls "$version")
  return 1
}

# Extract/copy the downloaded release into a staging directory and print the
# path of the binary inside it.  Handles raw binaries, tar.gz, and zip.
ba_prepare_binary() {
  local downloaded="$1" stage="$2" found
  case "${BA_ARCHIVE_TYPE:-none}" in
    tar.gz)
      tar -xzf "$downloaded" -C "$stage" || return 1
      ;;
    zip)
      command -v unzip >/dev/null 2>&1 || return 1
      unzip -q "$downloaded" -d "$stage" || return 1
      ;;
    none)
      cp "$downloaded" "${stage}/${BA_BIN_NAME}" || return 1
      ;;
    *)
      return 1
      ;;
  esac
  found="$(find "$stage" -type f -name "${BA_BIN_NAME}" -print -quit 2>/dev/null)"
  [[ -n "$found" && -f "$found" ]] || return 1
  printf '%s\n' "$found"
}

# Sanity-check a candidate binary: non-empty, large enough, ELF magic.
bapp_inspect_binary() {
  local bin="$1"
  local min_size="${BA_MIN_SIZE:-1048576}"
  local size magic
  [[ -s "$bin" ]] || error "$(t binary_app.error.binary_empty)"
  size="$(wc -c < "$bin")"
  if [[ "$size" -lt "$min_size" ]]; then
    rm -f "$bin"
    error "$(t binary_app.error.binary_too_small "$size")"
  fi
  magic="$(dd if="$bin" bs=1 count=4 2>/dev/null | od -An -tx1 | tr -d ' \n')"
  if [[ "$magic" != "7f454c46" ]]; then
    rm -f "$bin"
    error "$(t binary_app.error.binary_not_elf "${magic:-read failed}")"
  fi
  local size_mb=$(( size / 1024 / 1024 ))
  success "$(t binary_app.success.binary_verified "$size_mb")"
}
# Set up the service user, directories, and ownership for a fresh install.
ba_setup_user_dirs() {
  local dirs=("$INSTALL_DIR" "$DATA_DIR" "$LOG_DIR" "$BACKUP_DIR")
  local d
  if ! id "$SERVICE_USER" >/dev/null 2>&1; then
    if ! useradd -r -s /usr/sbin/nologin -d "$INSTALL_DIR" "$SERVICE_USER"; then
      error "$(t binary_app.error.user_create "$SERVICE_USER")"
    fi
    success "$(t binary_app.success.user_created "$SERVICE_USER")"
  else
    info "$(t binary_app.info.user_exists "$SERVICE_USER")"
  fi
  local -a new_dirs=() existing_dirs=()
  local existed=false
  for d in "${dirs[@]}"; do
    require_safe_path "$(basename "$d")" "$d"
    existed=false
    [[ -e "$d" || -L "$d" ]] && existed=true
    if ! mkdir -p "$d"; then
      error "$(t binary_app.error.dir_create "$d")"
    fi
    if $existed; then
      existing_dirs+=("$d")
    else
      new_dirs+=("$d")
    fi
  done
  # Recursively own only directories created by this deployment; pre-existing
  # directories get non-recursive ownership so unrelated files are untouched.
  if [[ ${#new_dirs[@]} -gt 0 ]]; then
    if ! chown -R "${SERVICE_USER}:${SERVICE_USER}" "${new_dirs[@]}"; then
      error "$(t binary_app.error.dir_owner "${SERVICE_USER}:${SERVICE_USER}" "${new_dirs[*]}")"
    fi
  fi
  if [[ ${#existing_dirs[@]} -gt 0 ]]; then
    if ! chown "${SERVICE_USER}:${SERVICE_USER}" "${existing_dirs[@]}"; then
      error "$(t binary_app.error.dir_owner "${SERVICE_USER}:${SERVICE_USER}" "${existing_dirs[*]}")"
    fi
  fi
  success "$(t binary_app.success.dirs "$INSTALL_DIR $DATA_DIR $LOG_DIR")"
}

# Install the downloaded candidate at BIN_PATH, preserving the previous
# binary (when present) as a rollback backup.
ba_install_binary() {
  local tmp_bin="$1"
  local backup_path="${2:-}"
  if ! app_binary_install_candidate "$tmp_bin" "$backup_path"; then
    error "$(t binary_app.error.binary_install "$BIN_PATH")"
  fi
}

ba_remove_file_or_error() {
  local path="$1" name="$2"
  require_safe_path "$name" "$path"
  if ! rm -f "$path"; then
    error "$(t binary_app.error.remove_file "$path")"
  fi
}

ba_remove_dir_or_error() {
  local path="$1" name="$2"
  if ! safe_rm_dir "$path" "$name"; then
    error "$(t binary_app.error.remove_dir "$path")"
  fi
}

# Default systemd unit; apps override ba_systemd_unit for service-specific
# ExecStart flags, environment, or hardening needs.
ba_systemd_unit() {
  local unit_path="/etc/systemd/system/${SERVICE_NAME}.service"
  local env_line=""
  if [[ "${BA_USE_ENV_FILE:-0}" == "1" ]]; then
    env_line="EnvironmentFile=${ENV_FILE}"
  fi
  local extra=""
  if declare -f ba_systemd_extra >/dev/null 2>&1; then
    extra="$(ba_systemd_extra)"
  fi
  if ! systemd_write_unit "$unit_path" <<EOF
[Unit]
Description=${BA_SERVICE_DESCRIPTION:-${APP_NAME} service}
Documentation=https://github.com/${GITHUB_REPO}
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=${SERVICE_USER}
Group=${SERVICE_USER}
WorkingDirectory=${DATA_DIR}
ExecStart="${BIN_PATH}"${BA_SERVICE_ARGS:+ ${BA_SERVICE_ARGS}}
Restart=always
RestartSec=5
StartLimitInterval=60
StartLimitBurst=5
${env_line}
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ReadWritePaths=${DATA_DIR} ${LOG_DIR}${BA_READWRITE_PATHS:+ ${BA_READWRITE_PATHS}}
StandardOutput=journal
StandardError=journal
SyslogIdentifier=${SERVICE_NAME}
${extra}
[Install]
WantedBy=multi-user.target
EOF
  then
    error "$(t binary_app.error.systemd_unit "$SERVICE_NAME")"
  fi
}

# Run after the unit is written: daemon-reload, enable, start, wait.
ba_start_service() {
  app_check_port_conflict "$PORT"
  if ! command systemctl daemon-reload; then
    error "$(t binary_app.error.systemd_reload "$SERVICE_NAME")"
  fi
  if ! systemctl enable "$SERVICE_NAME" --quiet; then
    warn "$(t binary_app.warn.enable_failed "$SERVICE_NAME" "$SERVICE_NAME")"
  fi
  if systemctl restart "$SERVICE_NAME" && wait_for_service "$SERVICE_NAME" 20; then
    success "$(t binary_app.success.started "$SERVICE_NAME")"
    systemctl status "$SERVICE_NAME" --no-pager -l 2>/dev/null | head -12 | sed 's/^/  /' >&2 || true
    return 0
  fi
  return 1
}

# Default HTTP health check; apps override bapp_health_probe when the service
# exposes a different endpoint or requires other status codes.
bapp_health_probe() {
  local url="${BA_HEALTH_URL:-http://127.0.0.1:${PORT}/}"
  local codes="${BA_HEALTH_CODES:-^(200|301|302)$}"
  local elapsed=0 code
  until code="$(app_http_status_code "$url" 5)" \
      && [[ "$code" =~ $codes ]]; do
    sleep 1
    elapsed=$((elapsed + 1))
    [[ $elapsed -ge 15 ]] && break
  done
  if [[ "$code" =~ $codes ]]; then
    success "$(t binary_app.success.health "$code")"
    return 0
  fi
  warn "$(t binary_app.warn.health "$code")"
  warn "$(t binary_app.warn.debug_command "$SERVICE_NAME")"
  return 1
}

# Firewall + logrotate for the service port and log directory.
# BA_FIREWALL defaults to 0: opening a firewall port for a plain-HTTP
# service bound to 0.0.0.0 exposes it to the public internet.  Apps that
# genuinely need a public port (e.g. frps) opt in explicitly.
ba_configure_ops() {
  if [[ "${BA_FIREWALL:-0}" == "1" ]]; then
    app_configure_firewall "$PORT" "binary_app" "$APP_NAME"
  fi
  app_write_logrotate "/etc/logrotate.d/${SERVICE_NAME}" "$LOG_DIR" \
    "binary_app.error.logrotate" "binary_app.success.logrotate"
}

# One-shot HTTPS: when BA_ENABLE_HTTPS=1 and DOMAIN is set, install nginx and
# certbot, obtain a Let's Encrypt certificate, and publish the loopback-bound
# service on 443 through an nginx reverse proxy. The service itself keeps
# binding BA_BIND_ADDR (loopback by default). Requires CERTBOT_EMAIL for the
# ACME registration. Failures are fatal (the user explicitly asked for TLS).
ba_configure_tls() {
  [[ "${BA_ENABLE_HTTPS:-0}" == "1" ]] || return 0
  [[ -n "${DOMAIN:-}" ]] || error "$(t binary_app.error.tls_requires_domain "$APP_NAME")"
  app_validate_email "CERTBOT_EMAIL" "${CERTBOT_EMAIL:-}"
  step "$(t binary_app.step.tls_deps)"
  if ! apt-get install -y -qq nginx certbot python3-certbot-nginx; then
    error "$(t binary_app.error.tls_deps)"
  fi
  success "$(t binary_app.success.tls_deps)"
  local nginx_conf="/etc/nginx/sites-available/${SERVICE_NAME}"
  if ! mkdir -p /etc/nginx/sites-available /etc/nginx/sites-enabled /var/www/certbot; then
    error "$(t binary_app.error.tls_nginx_dirs "$nginx_conf")"
  fi
  # HTTP bootstrap site with the ACME challenge root.
  app_write_nginx_config_file "$nginx_conf" "binary_app.error.tls_nginx" <<EOF
server {
    listen 80;
    listen [::]:80;
    server_name ${DOMAIN};
    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }
    location / {
        return 301 https://\$host\$request_uri;
    }
}
EOF
  app_write_nginx_site_link "$nginx_conf" "/etc/nginx/sites-enabled/${SERVICE_NAME}" "binary_app.error.tls_nginx"
  app_nginx_default_site_backup
  nginx -t || error "$(t binary_app.error.tls_nginx_test)"
  if ! systemctl enable --now nginx 2>/dev/null; then
    warn "$(t binary_app.warn.tls_nginx_enable)"
  fi
  if ! systemctl restart nginx 2>/dev/null; then
    error "$(t binary_app.error.tls_nginx_restart)"
  fi
  step "$(t binary_app.step.tls_certbot)"
  info "$(t binary_app.info.tls_certbot "$DOMAIN")"
  if ! certbot certonly --webroot -w /var/www/certbot -d "$DOMAIN" \
      --email "$CERTBOT_EMAIL" --agree-tos --non-interactive >&2; then
    error "$(t binary_app.error.tls_certbot "$DOMAIN")"
  fi
  success "$(t binary_app.success.tls_certbot)"
  # Full HTTPS site.
  app_write_nginx_config_file "$nginx_conf" "binary_app.error.tls_nginx" <<EOF
server {
    listen 80;
    listen [::]:80;
    server_name ${DOMAIN};
    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }
    location / {
        return 301 https://\$host\$request_uri;
    }
}
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    server_name ${DOMAIN};
    ssl_certificate     /etc/letsencrypt/live/${DOMAIN}/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/${DOMAIN}/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_timeout 1d;
    ssl_session_cache shared:MozTLS:10m;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    location / {
        proxy_pass         http://127.0.0.1:${PORT};
        proxy_http_version 1.1;
        proxy_set_header   Host \$host;
        proxy_set_header   X-Real-IP \$remote_addr;
        proxy_set_header   X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header   X-Forwarded-Proto \$scheme;
        proxy_read_timeout 90s;
    }
}
EOF
  if ! nginx -t || ! systemctl reload nginx; then
    error "$(t binary_app.error.tls_nginx_test)"
  fi
  success "$(t binary_app.success.tls_live "https://${DOMAIN}")"
  # Renewal via /etc/cron.d (atomic), matching the vaultwarden approach.
  local cron_file="/etc/cron.d/certbot-renew" cron_tmp
  if ! cron_tmp=$(mktemp "${cron_file}.XXXXXX"); then
    error "$(t binary_app.error.tls_renewal)"
  fi
  if ! printf '%s\n' "30 2 * * * root certbot renew --quiet --post-hook 'systemctl reload nginx'" > "$cron_tmp" \
      || ! chmod 644 "$cron_tmp" \
      || ! chown root:root "$cron_tmp" \
      || ! mv -f "$cron_tmp" "$cron_file"; then
    rm -f "$cron_tmp"
    error "$(t binary_app.error.tls_renewal)"
  fi
  success "$(t binary_app.success.tls_renewal)"
}

# Print the install summary box (localized, generic fields). The second
# argument is the health state: "ready" (default) or "pending" when the
# service did not pass its HTTP health probe within the wait window.
bapp_summary() {
  local version="$1"
  local summary_state="${2:-ready}"
  local internal_ip
  local hostname_scan
  hostname_scan="$(hostname -I 2>/dev/null | awk '{print $1}' || true)"
  internal_ip="${hostname_scan:-YOUR_SERVER_IP}"
  echo ""
  echo -e "${BOLD}${GREEN}"
  echo "  =========================================================="
  if [[ "$summary_state" == "pending" ]]; then
    echo -e "  ${BOLD}$(t binary_app.summary.title_pending)${GREEN}"
  else
    echo -e "  ${BOLD}$(t binary_app.summary.title_ready)${GREEN}"
  fi
  echo "  =========================================================="
  if [[ -n "$DOMAIN" ]]; then
    echo -e "  $(t binary_app.summary.public)  ${CYAN}http://${DOMAIN}${GREEN}"
  fi
  echo -e "  $(t binary_app.summary.internal)  ${CYAN}http://${internal_ip}:${PORT}${GREEN}"
  echo -e "  $(t binary_app.summary.version)  ${YELLOW}${version}${GREEN}"
  echo -e "  $(t binary_app.summary.data_dir)  ${YELLOW}${DATA_DIR}${GREEN}"
  echo -e "  $(t binary_app.summary.log_dir)  ${YELLOW}${LOG_DIR}${GREEN}"
  echo -e "  $(t binary_app.summary.backup_dir)  ${YELLOW}${BACKUP_DIR}${GREEN}"
  if declare -f ba_summary_extra >/dev/null 2>&1; then
    ba_summary_extra
  fi
  echo "  =========================================================="
  if app_public_bind_is_wildcard "${BA_BIND_ADDR:-127.0.0.1}" && ! deploy_value_truthy "${BA_ENABLE_HTTPS:-0}"; then
    echo -e "  ${RED}${BOLD}$(t binary_app.summary.plaintext_warning "${PORT}")${NC}"
    echo -e "  ${YELLOW}$(t binary_app.summary.proxy_hint)${NC}"
  elif app_public_bind_is_wildcard "${BA_BIND_ADDR:-127.0.0.1}"; then
    echo -e "  ${YELLOW}$(t binary_app.summary.public_bind)${NC}"
  else
    echo -e "  $(t binary_app.summary.local_bind "${PORT}")"
  fi
  echo "  =========================================================="
  echo -e "${NC}"
  echo -e "  ${BOLD}$(t binary_app.summary.management)${NC}"
  echo -e "    ${CYAN}bash $0 status${NC}      - $(t binary_app.summary.status_cmd)"
  echo -e "    ${CYAN}bash $0 update${NC}      - $(t binary_app.summary.update_cmd)"
  echo -e "    ${CYAN}bash $0 backup${NC}      - $(t binary_app.summary.backup_cmd)"
  echo -e "    ${CYAN}bash $0 uninstall${NC}   - $(t binary_app.summary.uninstall_cmd)"
  echo ""
  echo -e "  ${BOLD}$(t binary_app.summary.systemd)${NC}"
  echo -e "    ${CYAN}systemctl status ${SERVICE_NAME}${NC}     $(t binary_app.summary.show_status)"
  echo -e "    ${CYAN}journalctl -u ${SERVICE_NAME} -f${NC}     $(t binary_app.summary.live_logs)"
  echo -e "    ${CYAN}systemctl restart ${SERVICE_NAME}${NC}    $(t binary_app.summary.restart)"
  echo ""
}
bapp_install() {
  show_banner
  bapp_preflight "install"

  step "$(t binary_app.step.latest)"
  bapp_check_net
  info "$(t binary_app.info.query_latest)"
  local latest
  latest="$(ba_resolve_version)"
  [[ -n "$latest" ]] || error "$(t binary_app.error.version_failed)"
  if [[ -n "${BA_VERSION:-}" ]]; then
    success "$(t binary_app.success.pinned_version "${BOLD}${latest}${NC}")"
  else
    success "$(t binary_app.success.latest "${BOLD}${latest}${NC}")"
  fi
  step "$(t binary_app.step.deps)"
  if ! apt-get update -qq; then
    error "$(t binary_app.error.apt_update)"
  fi
  local apt_deps="curl ca-certificates"
  if [[ -n "${BA_APT_PACKAGES:-}" ]]; then
    apt_deps="${apt_deps} ${BA_APT_PACKAGES}"
  fi
  # shellcheck disable=SC2086
  if ! apt-get install -y -qq $apt_deps; then
    error "$(t binary_app.error.deps_install)"
  fi
  success "$(t binary_app.success.deps)"
  step "$(t binary_app.step.user_dirs)"
  ba_setup_user_dirs
  step "$(t binary_app.step.download "$BA_ARCH")"
  local tmp_bin old_bin_bak=""
  if ! tmp_bin="$(mktemp "${INSTALL_DIR}/.${BA_BIN_NAME}.tmp.XXXXXX")"; then
    error "$(t binary_app.error.download "$GITHUB_REPO")"
  fi
  local download_url
  download_url="$(ba_download_urls "$latest" | head -1)"
  info "$(t binary_app.info.download_url "$download_url")"
  if ! ba_download_release "$latest" "$tmp_bin"; then
    rm -f "$tmp_bin" 2>/dev/null || true
    error "$(t binary_app.error.download "$download_url")"
  fi
  local stage
  if ! stage="$(mktemp -d "${INSTALL_DIR}/.${BA_BIN_NAME}.stage.XXXXXX")"; then
    rm -f "$tmp_bin" 2>/dev/null || true
    error "$(t binary_app.error.extract)"
  fi
  local candidate
  if ! candidate="$(ba_prepare_binary "$tmp_bin" "$stage")"; then
    rm -f "$tmp_bin" 2>/dev/null || true
    safe_rm_dir "$stage" "binary staging directory" || true
    error "$(t binary_app.error.extract)"
  fi
  bapp_inspect_binary "$candidate"
  if ! mv -f "$candidate" "$tmp_bin"; then
    rm -f "$tmp_bin" 2>/dev/null || true
    safe_rm_dir "$stage" "binary staging directory" || true
    error "$(t binary_app.error.extract)"
  fi
  safe_rm_dir "$stage" "binary staging directory" || true
  if [[ -f "$BIN_PATH" ]]; then
    old_bin_bak="${INSTALL_DIR}/${BA_BIN_NAME}.bak.$(date +%Y%m%d_%H%M%S)"
  fi
  ba_install_binary "$tmp_bin" "$old_bin_bak"
  if [[ -n "$old_bin_bak" ]]; then
    warn "$(t binary_app.warn.old_binary_backup "$(basename "$old_bin_bak")")"
  fi
  if ! chown "${SERVICE_USER}:${SERVICE_USER}" "$BIN_PATH"; then
    error "$(t binary_app.error.dir_owner "${SERVICE_USER}:${SERVICE_USER}" "$BIN_PATH")"
  fi
  success "$(t binary_app.success.binary_verified "$(( $(wc -c < "$BIN_PATH") / 1024 / 1024 ))")"
  if declare -f ba_write_config >/dev/null 2>&1; then
    step "$(t binary_app.step.config)"
    ba_write_config "$latest"
  fi
  step "$(t binary_app.step.systemd)"
  ba_systemd_unit
  success "$(t binary_app.success.systemd "$SERVICE_NAME")"
  if declare -f ba_pre_start >/dev/null 2>&1; then
    ba_pre_start "$latest"
  fi
  step "$(t binary_app.step.firewall)"
  ba_configure_ops
  if [[ "${BA_ENABLE_HTTPS:-0}" == "1" ]]; then
    ba_configure_tls
  fi
  step "$(t binary_app.step.start)"
  if ba_start_service; then
    INSTALLED_VERSION="$latest"
    app_save_config
  else
    warn "$(t binary_app.warn.start_rollback)"
    if ! systemctl stop "$SERVICE_NAME" 2>/dev/null; then
      warn "$(t binary_app.warn.stop_failed "$SERVICE_NAME")"
    fi
    if ! systemctl disable "$SERVICE_NAME" 2>/dev/null; then
      warn "$(t binary_app.warn.disable_failed "$SERVICE_NAME")"
    fi
    ba_remove_file_or_error "/etc/systemd/system/${SERVICE_NAME}.service" "SERVICE_FILE"
    if ! systemctl daemon-reload 2>/dev/null; then
      warn "$(t binary_app.warn.reload_failed)"
    fi
    if [[ -n "$old_bin_bak" && -f "$old_bin_bak" ]]; then
      app_binary_restore_backup "$old_bin_bak" \
        || error "$(t binary_app.error.install_start_failed "$SERVICE_NAME" "$SERVICE_NAME")"
    else
      ba_remove_file_or_error "$BIN_PATH" "BIN_PATH"
    fi
    error "$(t binary_app.error.install_start_failed "$SERVICE_NAME" "$SERVICE_NAME")"
  fi
  step "$(t binary_app.step.health)"
  local _summary_state="ready"
  if ! bapp_health_probe; then
    _summary_state="pending"
  fi
  bapp_summary "$latest" "$_summary_state"
}
# Back up DATA_DIR to BACKUP_DIR as <app>_<label>_<timestamp>.tar.gz with
# retention; logs progress to BACKUP_DIR/backup.log.  Returns 0 on success.
_ba_backup() {
  local label="$1"
  local backup_log="${BACKUP_DIR}/backup.log"
  _ba_backup_log() {
    [[ -d "$BACKUP_DIR" ]] || return 1
    printf '%s  %s\n' "$(date '+%F %T')" "$1" >> "$backup_log"
  }
  if ! mkdir -p "$BACKUP_DIR"; then
    warn "$(t binary_app.error.backup_dir_create "$BACKUP_DIR")"
    return 1
  fi
  if [[ ! -d "$DATA_DIR" ]]; then
    _ba_backup_log "$(t binary_app.error.data_missing "$DATA_DIR")"
    warn "$(t binary_app.error.data_missing "$DATA_DIR")"
    return 1
  fi
  # Apps with data that needs to be quiesced before archiving (for example a
  # SQLite WAL checkpoint) define ba_backup_hook(); the hook is best-effort:
  # a failure is reported but does not abort the backup.
  if declare -f ba_backup_hook >/dev/null 2>&1; then
    if ! ba_backup_hook; then
      warn "$(t binary_app.warn.backup_hook_failed)"
      _ba_backup_log "$(t binary_app.warn.backup_hook_failed)"
    fi
  fi
  local archive
  archive="${BACKUP_DIR}/${BA_ARCHIVE_PREFIX:-${APP_ID}}_${label}_$(date +%Y%m%d_%H%M%S).tar.gz"
  if backup_create_tar_archive "$archive" \
      --exclude="*.log" --exclude="*.log.*" \
      -C "$(dirname "$DATA_DIR")" "$(basename "$DATA_DIR")"; then
    local sz
    sz="$(du -sh "$archive" 2>/dev/null | awk '{print $1}')"
    _ba_backup_log "$(t binary_app.success.backup_done "$archive" "$sz")"
    success "$(t binary_app.success.silent_backup "$archive" "$sz")"
    if ! backup_finalize_archive "$archive" "$APP_ID" "${INSTALLED_VERSION:-}"; then
      warn "$(t binary_app.warn.integrity_failed "$archive")"
      _ba_backup_log "$(t binary_app.warn.integrity_failed "$archive")"
    fi
  else
    _ba_backup_log "$(t binary_app.error.backup_failed)"
    warn "$(t binary_app.warn.silent_backup_failed "$BACKUP_DIR")"
    return 1
  fi
  _ba_prune_backups
}

_ba_prune_backups() {
  local keep_days="${BACKUP_KEEP_DAYS:-0}"
  [[ "$keep_days" =~ ^[0-9]+$ ]] || keep_days=0
  if [[ "$keep_days" -gt 0 ]]; then
    local cleaned=0 f
    while IFS= read -r -d '' f; do
      if rm -f "$f"; then
        cleaned=$((cleaned + 1))
      else
        warn "$(t binary_app.warn.backup_cleanup_failed "$f")"
      fi
    done < <(backup_list_expired_archives "$BACKUP_DIR" "$keep_days" \
      "${BA_ARCHIVE_PREFIX:-${APP_ID}}_*.tar.gz")
    if [[ "$cleaned" -gt 0 ]]; then
      info "$(t binary_app.info.cleaned_backups "$cleaned" "$keep_days")"
    fi
  fi
}

bapp_backup() {
  show_banner
  bapp_preflight "backup"
  app_load_config _binary_app_derive_paths

  step "$(t binary_app.step.manual_backup)"
  if ! _ba_backup "manual"; then
    error "$(t binary_app.error.backup_failed)"
  fi
  echo ""
  info "$(t binary_app.info.backup_list "$BACKUP_DIR")"
  local f
  while IFS= read -r f; do
    [[ -n "$f" ]] || continue
    printf '  %s\n' "$f"
  done < <(find "$BACKUP_DIR" -maxdepth 1 -name "${BA_ARCHIVE_PREFIX:-${APP_ID}}_*.tar.gz" -type f \
           -printf '%T@ %f\n' 2>/dev/null | sort -rn | sed 's/^[0-9.]* //')
  echo ""
}

# Verify the newest backup archive of a shared-lifecycle app: load the saved
# config (trust gate enforced), pick the latest archive by mtime and recompute
# its checksum against the sidecar/manifest. Archives are mode 600 root:root,
# so verification runs as root like backup itself. Read-only: no lock needed.
bapp_verify() {
  show_banner
  require_root "verify"
  app_load_config _binary_app_derive_paths
  step "$(t backup.verify.step)"
  require_safe_path "BACKUP_DIR" "$BACKUP_DIR"
  app_verify_latest_backup "$BACKUP_DIR" "${BA_ARCHIVE_PREFIX:-${APP_ID}}_*.tar.gz"
}

# Shared restore lifecycle for binary-app data directories. Selects the newest
# archive (override with <APP>_RESTORE_ARCHIVE env, path must live inside the
# trusted BACKUP_DIR), verifies its checksum before touching anything, stops
# the service, swaps DATA_DIR atomically with a timestamped aside copy, then
# restarts and rolls the data back if the service cannot come up.
bapp_restore() {
  show_banner
  require_root "restore"
  app_load_config _binary_app_derive_paths
  acquire_lock
  step "$(t backup.restore.step)"
  require_safe_path "BACKUP_DIR" "$BACKUP_DIR"
  require_safe_path "DATA_DIR" "$DATA_DIR"
  [[ -d "$BACKUP_DIR" ]] || error "$(t backup.restore.no_backups "$BACKUP_DIR")"
  local archive restore_env="${APP_ID^^}_RESTORE_ARCHIVE"
  archive="${!restore_env:-}"
  if [[ -n "$archive" ]]; then
    [[ "$archive" == "$BACKUP_DIR"/${BA_ARCHIVE_PREFIX:-${APP_ID}}_*.tar.gz && -f "$archive" ]] \
      || error "$(t backup.restore.invalid_archive "$archive")"
  else
    archive="$(backup_latest_archive "$BACKUP_DIR" "${BA_ARCHIVE_PREFIX:-${APP_ID}}_*.tar.gz" || true)"
    [[ -n "$archive" ]] || error "$(t backup.restore.no_backups "$BACKUP_DIR")"
  fi
  backup_restore_data_dir "$DATA_DIR" "$SERVICE_NAME" "$archive"
  # Data was restored but the service is not restarted by restore; a probe
  # failure here is expected and must not be reported as an app fault.
  bapp_health_probe || true
}
_ba_prune_old_bins() {
  local -a old_bins=()
  local entry
  while IFS= read -r -d '' entry; do
    old_bins+=("${entry#* }")
  done < <(
    find "$INSTALL_DIR" -maxdepth 1 -name "${BA_BIN_NAME}.bak.*" -type f \
      -printf '%T@ %p\0' 2>/dev/null | sort -z -rn | tail -z -n +4
  )
  if [[ ${#old_bins[@]} -gt 0 ]]; then
    local cleaned=0 bin_path
    for bin_path in "${old_bins[@]}"; do
      if rm -f "$bin_path"; then
        cleaned=$((cleaned + 1))
      else
        warn "$(t binary_app.warn.cleanup_old_failed "$bin_path")"
      fi
    done
    if [[ "$cleaned" -gt 0 ]]; then
      info "$(t binary_app.info.cleaned_old "$cleaned")"
    fi
  fi
}

bapp_update() {
  show_banner
  bapp_preflight "update"
  app_load_config _binary_app_derive_paths

  [[ -x "$BIN_PATH" ]] || error "$(t binary_app.error.not_installed "${APP_NAME:-app}" "$BIN_PATH")"
  step "$(t binary_app.step.check_update)"
  bapp_check_net
  info "$(t binary_app.info.query_latest)"
  local latest current
  latest="$(ba_resolve_version)"
  [[ -n "$latest" ]] || error "$(t binary_app.error.version_failed)"
  current="${INSTALLED_VERSION:-unknown}"
  info "$(t binary_app.info.current "${YELLOW}${current}${NC}")"
  if [[ -n "${BA_VERSION:-}" ]]; then
    info "$(t binary_app.info.pinned_target "${YELLOW}${latest}${NC}")"
  else
    info "$(t binary_app.info.github_latest "${YELLOW}${latest}${NC}")"
  fi
  if [[ "$current" == "$latest" ]]; then
    success "$(t binary_app.success.already_latest "$latest")"
    exit 0
  fi
  local pre_state
  pre_state="$(systemctl is-active "$SERVICE_NAME" 2>/dev/null || echo "inactive")"
  if [[ "$pre_state" == "failed" ]]; then
    warn "$(t binary_app.warn.pre_failed_state)"
    warn "$(t binary_app.warn.pre_failed_debug "$SERVICE_NAME")"
  fi
  step "$(t binary_app.step.pre_backup)"
  if ! _ba_backup "pre-update"; then
    warn "$(t binary_app.warn.pre_backup_failed)"
  fi
  step "$(t binary_app.step.download_update "$current" "$latest")"
  local tmp_bin download_url
  download_url="$(ba_download_urls "$latest" | head -1)"
  info "$(t binary_app.info.download_url "$download_url")"
  if ! tmp_bin="$(mktemp "${INSTALL_DIR}/.${BA_BIN_NAME}.tmp.XXXXXX")"; then
    error "$(t binary_app.error.download "$GITHUB_REPO")"
  fi
  if ! ba_download_release "$latest" "$tmp_bin"; then
    rm -f "$tmp_bin" 2>/dev/null || true
    error "$(t binary_app.error.download "$download_url")"
  fi
  local stage candidate
  if ! stage="$(mktemp -d "${INSTALL_DIR}/.${BA_BIN_NAME}.stage.XXXXXX")"; then
    rm -f "$tmp_bin" 2>/dev/null || true
    error "$(t binary_app.error.extract)"
  fi
  if ! candidate="$(ba_prepare_binary "$tmp_bin" "$stage")"; then
    rm -f "$tmp_bin" 2>/dev/null || true
    safe_rm_dir "$stage" "binary staging directory" || true
    error "$(t binary_app.error.extract)"
  fi
  bapp_inspect_binary "$candidate"
  if ! mv -f "$candidate" "$tmp_bin"; then
    rm -f "$tmp_bin" 2>/dev/null || true
    safe_rm_dir "$stage" "binary staging directory" || true
    error "$(t binary_app.error.extract)"
  fi
  safe_rm_dir "$stage" "binary staging directory" || true
  step "$(t binary_app.step.replace_restart)"
  local bak_path
  bak_path="${INSTALL_DIR}/${BA_BIN_NAME}.bak.$(date +%Y%m%d_%H%M%S)"
  if ! app_binary_backup_current "$bak_path"; then
    error "$(t binary_app.error.binary_install "$BIN_PATH")"
  fi
  info "$(t binary_app.info.old_binary "$bak_path")"
  if ! systemctl stop "$SERVICE_NAME" 2>/dev/null; then
    rm -f "$tmp_bin" 2>/dev/null || true
    error "$(t binary_app.error.stop_service_failed "$SERVICE_NAME")"
  fi
  ba_install_binary "$tmp_bin"
  if ! command systemctl daemon-reload; then
    error "$(t binary_app.error.systemd_reload "$SERVICE_NAME")"
  fi
  if systemctl start "$SERVICE_NAME" && wait_for_service "$SERVICE_NAME" 20; then
    success "$(t binary_app.success.update_started)"
    INSTALLED_VERSION="$latest"
    app_save_config
    _ba_prune_old_bins
    # The service started, but an HTTP-level probe failure means the app may
    # not be fully ready yet; surface it explicitly instead of ignoring it.
    if ! bapp_health_probe; then
      warn "$(t binary_app.warn.health_pending)"
    fi
    echo ""
    echo -e "  ${BOLD}${GREEN}$(t binary_app.info.github_latest "$latest")${NC}"
    echo ""
  else
    warn "$(t binary_app.warn.update_start_failed "$current")"
    if ! systemctl stop "$SERVICE_NAME" 2>/dev/null; then
      error "$(t binary_app.error.rollback_stop_failed "$SERVICE_NAME")"
    fi
    if ! app_binary_restore_backup "$bak_path"; then
      warn "$(t binary_app.warn.rollback_start_failed "$SERVICE_NAME")"
      error "$(t binary_app.error.update_failed "$current")"
    fi
    if systemctl start "$SERVICE_NAME"; then
      if wait_for_service "$SERVICE_NAME" 15; then
        success "$(t binary_app.success.rollback "$current")"
      else
        warn "$(t binary_app.warn.rollback_start_failed "$SERVICE_NAME")"
      fi
    else
      warn "$(t binary_app.warn.rollback_start_failed "$SERVICE_NAME")"
    fi
    error "$(t binary_app.error.update_failed "$current")"
  fi
}
bapp_status() {
  show_banner
  bapp_preflight "status"
  app_load_config _binary_app_derive_paths
  if [[ ${EUID:-$(id -u)} -ne 0 ]]; then
    warn "$(t binary_app.warn.non_root_status "$0")"
  fi
  step "$(t status.title)"
  if [[ -f "$CONF_FILE" ]]; then
    printf '%s\n' "$(t binary_app.status.service "$SERVICE_NAME" "$(service_status_label "$SERVICE_NAME")")"
    printf '%s\n' "$(t binary_app.status.version "${INSTALLED_VERSION:-unknown}")"
    printf '%s\n' "$(t binary_app.status.health_url "${BA_HEALTH_URL:-http://127.0.0.1:${PORT}/}")"
    printf '\n%s\n' "$(t binary_app.status.paths)"
    local path
    for path in "$BIN_PATH" "$DATA_DIR" "$LOG_DIR" "$BACKUP_DIR"; do
      if [[ -e "$path" ]]; then
        printf '  [ok] %s\n' "$path"
      else
        printf '  [--] %s\n' "$path"
      fi
    done
    if declare -f ba_status_extra >/dev/null 2>&1; then
      ba_status_extra
    fi
  else
    info "$(t binary_app.status.not_installed)"
  fi
}

bapp_uninstall() {
  show_banner
  bapp_preflight "uninstall"
  app_load_config _binary_app_derive_paths

  local confirm delete_data=false delete_backup=false
  step "$(t binary_app.step.uninstall "$APP_NAME")"
  if deploy_assume_yes; then
    confirm="YES"
  else
    prompt "$(t binary_app.prompt.continue)"
    read -r confirm
  fi
  [[ "$confirm" == "YES" ]] || { info "$(t binary_app.info.cancelled)"; exit 0; }
  if deploy_assume_yes; then
    deploy_env_truthy DEPLOY_DELETE_DATA && delete_data=true
    deploy_env_truthy DEPLOY_DELETE_BACKUP && delete_backup=true
  else
    prompt "$(t binary_app.prompt.delete_data "$DATA_DIR")"
    local answer
    read -r answer
    [[ "${answer,,}" == "y" || "${answer,,}" == "yes" ]] && delete_data=true
    prompt "$(t binary_app.prompt.delete_backup "$BACKUP_DIR")"
    read -r answer
    [[ "${answer,,}" == "y" || "${answer,,}" == "yes" ]] && delete_backup=true
  fi
  info "$(t binary_app.info.stop_disable "$SERVICE_NAME")"
  if ! systemctl stop "$SERVICE_NAME" 2>/dev/null; then
    if systemctl is-active --quiet "$SERVICE_NAME" 2>/dev/null; then
      error "$(t binary_app.error.uninstall_stop_failed "$SERVICE_NAME")"
    fi
    warn "$(t binary_app.warn.uninstall_stop_failed "$SERVICE_NAME")"
  fi
  if ! systemctl disable "$SERVICE_NAME" 2>/dev/null; then
    warn "$(t binary_app.warn.uninstall_disable_failed "$SERVICE_NAME")"
  fi
  ba_remove_file_or_error "/etc/systemd/system/${SERVICE_NAME}.service" "SERVICE_FILE"
  if ! command systemctl daemon-reload; then
    error "$(t binary_app.error.systemd_reload "$SERVICE_NAME")"
  fi
  success "$(t binary_app.success.removed_systemd)"
  ba_remove_file_or_error "$BIN_PATH" "BIN_PATH"
  require_safe_path "INSTALL_DIR" "$INSTALL_DIR"
  local cleanup_path
  while IFS= read -r -d '' cleanup_path; do
    if ! rm -f "$cleanup_path"; then
      warn "$(t binary_app.warn.cleanup_old_failed "$cleanup_path")"
    fi
  done < <(find "$INSTALL_DIR" -maxdepth 1 \( -name "${BA_BIN_NAME}.bak.*" \
           -o -name ".${BA_BIN_NAME}.tmp.*" -o -name ".${BA_BIN_NAME}.stage.*" \) \
           -type f -print0 2>/dev/null)
  success "$(t binary_app.success.removed_binary)"
  ba_remove_file_or_error "/etc/logrotate.d/${SERVICE_NAME}" "LOGROTATE_FILE"
  # Clean up the optional TLS reverse proxy (nginx site + certbot renewal)
  # when it was provisioned by ba_configure_tls.
  if [[ -e "/etc/nginx/sites-available/${SERVICE_NAME}" || -L "/etc/nginx/sites-available/${SERVICE_NAME}" ]]; then
    ba_remove_file_or_error "/etc/nginx/sites-enabled/${SERVICE_NAME}" "TLS_NGINX_LINK"
    ba_remove_file_or_error "/etc/nginx/sites-available/${SERVICE_NAME}" "TLS_NGINX_CONF"
    app_nginx_default_site_restore
    if command -v nginx >/dev/null 2>&1; then
      if nginx -t 2>/dev/null; then
        systemctl reload nginx 2>/dev/null || true
      fi
    fi
  fi
  if [[ -e "/etc/cron.d/certbot-renew" ]]; then
    ba_remove_file_or_error "/etc/cron.d/certbot-renew" "TLS_RENEWAL_CRON"
  fi
  if [[ "${BA_USE_ENV_FILE:-0}" == "1" ]]; then
    ba_remove_file_or_error "$ENV_FILE" "ENV_FILE"
  fi
  if declare -f ba_uninstall_extra >/dev/null 2>&1; then
    ba_uninstall_extra
  fi
  ba_remove_file_or_error "$CONF_FILE" "CONF_FILE"
  success "$(t binary_app.success.removed_config)"
  if [[ -n "${LOG_DIR:-}" && "$LOG_DIR" != "." && "$LOG_DIR" != "/" && -d "$LOG_DIR" ]]; then
    ba_remove_dir_or_error "$LOG_DIR" "LOG_DIR"
  else
    warn "$(t binary_app.warn.log_path "${LOG_DIR:-unset}")"
  fi
  if $delete_data; then
    ba_remove_dir_or_error "$DATA_DIR" "DATA_DIR"
    if [[ -d "$INSTALL_DIR" ]] && [[ -z "$(ls -A "$INSTALL_DIR" 2>/dev/null)" ]]; then
      if ! safe_rm_dir "$INSTALL_DIR" "INSTALL_DIR"; then
        warn "$(t binary_app.warn.cleanup_install_failed "$INSTALL_DIR")"
      else
        success "$(t binary_app.success.cleaned_install "$INSTALL_DIR")"
      fi
    fi
  else
    info "$(t binary_app.info.kept_data "$DATA_DIR")"
  fi
  if $delete_backup; then
    ba_remove_dir_or_error "$BACKUP_DIR" "BACKUP_DIR"
  else
    info "$(t binary_app.info.kept_backup "$BACKUP_DIR")"
  fi
  if $delete_data && id "$SERVICE_USER" >/dev/null 2>&1; then
    if userdel "$SERVICE_USER" 2>/dev/null; then
      success "$(t binary_app.success.deleted_user "$SERVICE_USER")"
    else
      warn "$(t binary_app.warn.delete_user "$SERVICE_USER")"
    fi
  fi
  echo ""
  echo -e "${BOLD}${GREEN}  $(t binary_app.success.uninstalled "$APP_NAME")${NC}"
  if ! $delete_data; then
    echo -e "  ${YELLOW}[hint]${NC} $(t binary_app.hint.data_kept "$DATA_DIR")"
    echo -e "  ${YELLOW}[hint]${NC} $(t binary_app.hint.remove_data "$DATA_DIR")"
  fi
  if ! $delete_backup; then
    echo -e "  ${YELLOW}[hint]${NC} $(t binary_app.hint.backup_kept "$BACKUP_DIR")"
  fi
  echo ""
}



# ----- lib/compose.sh -----

# Shared Docker Compose support layer: resolve the compose command binary,
# validate the runtime, and run compose operations with strict path checks
# on the project file and working directory. Handles both `docker compose`
# (plugin) and the legacy `docker-compose` standalone binary.
#
# Never prints table/color output itself; callers format results.

# Print the compose command as a single string ("docker compose" or
# "docker-compose"), or empty when neither is usable.
compose_command() {
  if docker compose version >/dev/null 2>&1; then
    printf '%s' "docker compose"
  elif command -v docker-compose >/dev/null 2>&1; then
    printf '%s' "docker-compose"
  fi
  # An absent backend is a valid probe result. Callers that require compose
  # use compose_require_runtime(), while status-style callers can treat an
  # empty command as unavailable without triggering errexit.
  return 0
}

# Require a usable compose runtime; errors out when neither backend exists.
compose_require_runtime() {
  command -v docker >/dev/null 2>&1 \
    || error "$(t compose.error.docker_missing)"
  if ! docker compose version >/dev/null 2>&1 && ! command -v docker-compose >/dev/null 2>&1; then
    error "$(t compose.error.runtime_missing)"
  fi
}

# Validate the compose project file and working directory before any run:
# both must be safe, absolute paths, and the project file must exist.
# Returns nonzero (never exits) so probes can treat validation as a check;
# compose_run escalates the failure with a localized error.
compose_validate_project() {
  local work_dir="$1" project_file="$2" work_name project_name
  work_name="$(basename "$work_dir")"
  project_name="$(basename "$project_file")"
  is_safe_path "$work_dir" || return 1
  is_safe_path "$project_file" || return 1
  [[ -d "$work_dir" && -f "$project_file" ]] || return 1
  # Compose may resolve relative paths from --project-directory; keep the
  # project file inside that validated directory rather than accepting an
  # unrelated existing system file such as /etc/passwd.
  while [[ "$work_dir" != "/" && "$work_dir" == */ ]]; do
    work_dir="${work_dir%/}"
  done
  [[ "$project_file" == "$work_dir/"* ]] || return 1
}

# Echo an argv-ready compose invocation prefix given the working directory
# and project file. Example: "docker compose --project-directory /opt/app -f /opt/app/compose.yml"
compose_base_args() {
  local work_dir="$1" project_file="$2"
  printf -- '--project-directory %q -f %q' "$work_dir" "$project_file"
}

# Run one compose operation against the project, streaming output to stderr.
# Arguments: work dir, project file, then the compose subcommand + args.
compose_run() {
  local work_dir="$1" project_file="$2"
  shift 2
  compose_require_runtime
  compose_validate_project "$work_dir" "$project_file" \
    || error "$(t compose.error.project_missing "$project_file")"
  local compose_cmd
  compose_cmd="$(compose_command)"
  [[ -n "$compose_cmd" ]] || error "$(t compose.error.runtime_missing)"
  local -a base_args
  read -r -a base_args <<< "$(compose_base_args "$work_dir" "$project_file")"
  # shellcheck disable=SC2086
  $compose_cmd "${base_args[@]}" "$@" >&2
}

# Run one compose operation capturing only its exit status, with output
# suppressed unless the operation fails. Used by status-style probes.
compose_try() {
  local work_dir="$1" project_file="$2"
  shift 2
  local compose_cmd out
  compose_cmd="$(compose_command)"
  [[ -n "$compose_cmd" ]] || return 1
  compose_validate_project "$work_dir" "$project_file" || return 1
  local -a base_args
  read -r -a base_args <<< "$(compose_base_args "$work_dir" "$project_file")"
  # shellcheck disable=SC2086
  out="$($compose_cmd "${base_args[@]}" "$@" 2>&1)" || {
    printf '%s\n' "$out" >&2
    return 1
  }
  return 0
}

# Lifecycle helpers. Each validates and runs through compose_run, so output
# streams to stderr and no formatting decisions leak into the caller.
compose_up() {
  compose_run "$1" "$2" up -d --build
}

compose_down() {
  compose_run "$1" "$2" down
}

compose_ps() {
  compose_run "$1" "$2" ps
}

# Health check: `compose ps --format json` lists one JSON line per service;
# every service must report running/healthy. Accepts either docker compose
# or docker-compose output shape; returns nonzero when any service is not
# running, without printing anything (the caller renders the verdict).
compose_health() {
  local work_dir="$1" project_file="$2"
  local compose_cmd out
  compose_cmd="$(compose_command)"
  [[ -n "$compose_cmd" ]] || return 1
  compose_validate_project "$work_dir" "$project_file" || return 1
  local -a base_args
  read -r -a base_args <<< "$(compose_base_args "$work_dir" "$project_file")"
  # shellcheck disable=SC2086
  out="$($compose_cmd "${base_args[@]}" ps --format json 2>/dev/null)" || return 1
  # Case-insensitive state scan: running/healthy pass; exited, dead, or
  # restarting services fail the check. docker compose uses lowercase
  # values ("running"), docker-compose uses title case ("Running").
  printf '%s' "$out" | grep -qi '"running"\|"Running"\|"healthy"\|"Healthy"' \
    && ! printf '%s' "$out" | grep -qi '"exited"\|"Exited"\|"dead"\|"Dead"\|"restarting"\|"Restarting"' \
    || return 1
}

# ----- lib/self_update.sh -----

# Framework identity, release-manifest validation, and managed-release activation.
# Checkout and standalone executions remain strictly read-only.

DEPLOY_SELF_UPDATE_URL="${DEPLOY_SELF_UPDATE_URL:-}"
DEPLOY_SELF_UPDATE_CHANNEL="${DEPLOY_SELF_UPDATE_CHANNEL:-stable}"
DEPLOY_SELF_UPDATE_CONFIG_FILE="${DEPLOY_SELF_UPDATE_CONFIG_FILE:-/etc/deploy-scripts/self-update.conf}"
DEPLOY_SELF_UPDATE_ROOT="${DEPLOY_SELF_UPDATE_ROOT:-/opt/deploy-scripts}"
DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS="${DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS:-30}"
DEPLOY_SELF_UPDATE_MAX_MANIFEST_BYTES="${DEPLOY_SELF_UPDATE_MAX_MANIFEST_BYTES:-1048576}"
DEPLOY_SELF_UPDATE_MAX_ARTIFACT_BYTES="${DEPLOY_SELF_UPDATE_MAX_ARTIFACT_BYTES:-536870912}"
DEPLOY_SELF_UPDATE_KEEP_RELEASES="${DEPLOY_SELF_UPDATE_KEEP_RELEASES:-3}"

SELF_UPDATE_MODE="unknown"
SELF_UPDATE_ROOT=""
SELF_UPDATE_VERSION=""
SELF_UPDATE_PREVIOUS_VERSION=""
SELF_UPDATE_CURRENT_PATH=""
SELF_UPDATE_PREVIOUS_PATH=""
SELF_UPDATE_MANAGED_ROOT=""
SELF_UPDATE_MANIFEST_VERSION=""
SELF_UPDATE_MANIFEST_URL=""
SELF_UPDATE_MANIFEST_SHA256=""
SELF_UPDATE_MANIFEST_SIZE_BYTES=""
SELF_UPDATE_MANIFEST_NAME=""
SELF_UPDATE_MANIFEST_ERROR=""
SELF_UPDATE_MANIFEST_VALID=1
SELF_UPDATE_MANAGER_LOCK_ACQUIRED=0

self_update_validate_channel() {
  [[ "${1:-}" =~ ^[a-z][a-z0-9_-]{0,31}$ ]]
}

self_update_validate_https_url() {
  local url="${1:-}"
  [[ "$url" =~ ^https://[A-Za-z0-9.-]+(:[0-9]+)?(/[A-Za-z0-9._~:/%+-]*)?$ ]]
}

self_update_realpath() {
  local path="$1" resolved
  if command -v readlink >/dev/null 2>&1 && resolved="$(readlink -f -- "$path" 2>/dev/null)" && [[ -n "$resolved" ]]; then
    printf '%s\n' "$resolved"
    return 0
  fi
  (cd -- "$(dirname -- "$path")" && printf '%s/%s\n' "$PWD" "$(basename -- "$path")")
}

self_update_release_version_from_root() {
  local root="$1" metadata project version schema
  metadata="${root}/RELEASE.json"
  [[ -f "$metadata" ]] || return 1
  [[ "$(stat -c '%s' "$metadata" 2>/dev/null || printf 0)" -gt 0 ]] || return 1
  project="$(state_json_field "$(cat "$metadata")" project 2>/dev/null || true)"
  version="$(state_json_field "$(cat "$metadata")" version 2>/dev/null || true)"
  schema="$(state_json_field "$(cat "$metadata")" schema_version 2>/dev/null || true)"
  [[ "$schema" == 1 && "$project" == deploy-scripts ]] || return 1
  [[ "$version" =~ ^v([0]|[1-9][0-9]*)\.([0]|[1-9][0-9]*)\.([0]|[1-9][0-9]*)(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$ ]] || return 1
  printf '%s\n' "$version"
}

self_update_managed_root_for() {
  local root="$1" parent grandparent
  parent="$(dirname -- "$root")"
  grandparent="$(dirname -- "$parent")"
  if [[ "$(basename -- "$root")" == current ]]; then
    printf '%s\n' "$parent"
  elif [[ "$(basename -- "$parent")" == releases ]]; then
    printf '%s\n' "$grandparent"
  else
    printf '%s\n' "$root"
  fi
}

self_update_previous_version_for() {
  local managed_root="$1" previous_root version
  previous_root="${managed_root}/previous"
  [[ -e "$previous_root" || -L "$previous_root" ]] || return 0
  version="$(self_update_release_version_from_root "$previous_root" 2>/dev/null || true)"
  [[ -n "$version" ]] && printf '%s\n' "$version"
}

self_update_load_config() {
  local configured_url="${DEPLOY_SELF_UPDATE_URL:-}"
  local configured_channel="${DEPLOY_SELF_UPDATE_CHANNEL:-stable}"
  local configured_timeout="${DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS:-30}"
  local configured_max_manifest="${DEPLOY_SELF_UPDATE_MAX_MANIFEST_BYTES:-1048576}"
  local configured_max_artifact="${DEPLOY_SELF_UPDATE_MAX_ARTIFACT_BYTES:-536870912}"
  local configured_keep_releases="${DEPLOY_SELF_UPDATE_KEEP_RELEASES:-3}"
  local config_file="${DEPLOY_SELF_UPDATE_CONFIG_FILE:-/etc/deploy-scripts/self-update.conf}"

  DEPLOY_SELF_UPDATE_URL=""
  DEPLOY_SELF_UPDATE_CHANNEL="stable"
  DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS="30"
  DEPLOY_SELF_UPDATE_MAX_MANIFEST_BYTES="1048576"
  DEPLOY_SELF_UPDATE_MAX_ARTIFACT_BYTES="536870912"
  DEPLOY_SELF_UPDATE_KEEP_RELEASES="3"
  if [[ -f "$config_file" ]]; then
    load_config_file "$config_file" \
      DEPLOY_SELF_UPDATE_URL DEPLOY_SELF_UPDATE_CHANNEL \
      DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS DEPLOY_SELF_UPDATE_MAX_MANIFEST_BYTES \
      DEPLOY_SELF_UPDATE_MAX_ARTIFACT_BYTES DEPLOY_SELF_UPDATE_KEEP_RELEASES \
      DEPLOY_SELF_UPDATE_REQUIRE_SIGNATURE DEPLOY_SELF_UPDATE_PUBLIC_KEY || return 1
  fi
  [[ -z "$configured_url" ]] || DEPLOY_SELF_UPDATE_URL="$configured_url"
  [[ -z "$configured_channel" ]] || DEPLOY_SELF_UPDATE_CHANNEL="$configured_channel"
  [[ -z "$configured_timeout" ]] || DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS="$configured_timeout"
  [[ -z "$configured_max_manifest" ]] || DEPLOY_SELF_UPDATE_MAX_MANIFEST_BYTES="$configured_max_manifest"
  [[ -z "$configured_max_artifact" ]] || DEPLOY_SELF_UPDATE_MAX_ARTIFACT_BYTES="$configured_max_artifact"
  [[ -z "$configured_keep_releases" ]] || DEPLOY_SELF_UPDATE_KEEP_RELEASES="$configured_keep_releases"
  self_update_validate_channel "$DEPLOY_SELF_UPDATE_CHANNEL" || return 1
  [[ "$DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS" =~ ^[0-9]+$ && "$DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS" -gt 0 ]] || return 1
  [[ "$DEPLOY_SELF_UPDATE_MAX_MANIFEST_BYTES" =~ ^[1-9][0-9]*$ ]] || return 1
  [[ "$DEPLOY_SELF_UPDATE_MAX_ARTIFACT_BYTES" =~ ^[1-9][0-9]*$ ]] || return 1
  [[ "$DEPLOY_SELF_UPDATE_KEEP_RELEASES" =~ ^[3-9][0-9]*$ ]] || return 1
}

self_update_detect_mode() {
  local root="${DEPLOY_ROOT_DIR:-}" metadata_version managed_root
  SELF_UPDATE_MODE=unknown
  SELF_UPDATE_ROOT="$root"
  SELF_UPDATE_VERSION=""
  SELF_UPDATE_PREVIOUS_VERSION=""
  SELF_UPDATE_CURRENT_PATH=""
  SELF_UPDATE_PREVIOUS_PATH=""
  SELF_UPDATE_MANAGED_ROOT=""
  [[ -n "$root" ]] || return 0

  # A checkout takes precedence over metadata so a developer worktree can
  # never be mistaken for a writable managed installation.
  if [[ -e "${root}/.git" ]]; then
    SELF_UPDATE_MODE=checkout
    return 0
  fi
  if metadata_version="$(self_update_release_version_from_root "$root" 2>/dev/null)"; then
    local configured_root root_real configured_real current_real
    configured_root="${DEPLOY_SELF_UPDATE_ROOT:-/opt/deploy-scripts}"
    root_real="$(self_update_realpath "$root")"
    configured_real="$(self_update_realpath "$configured_root")"
    current_real="$(self_update_realpath "${configured_root}/current")"
    if [[ "$root_real" == "$current_real" || "$root_real" == "$configured_real/releases/"* ]]; then
      SELF_UPDATE_MODE=managed_release
      SELF_UPDATE_VERSION="$metadata_version"
      managed_root="$configured_root"
      SELF_UPDATE_MANAGED_ROOT="$managed_root"
      SELF_UPDATE_CURRENT_PATH="${managed_root}/current"
      SELF_UPDATE_PREVIOUS_PATH="${managed_root}/previous"
      SELF_UPDATE_PREVIOUS_VERSION="$(self_update_previous_version_for "$managed_root" || true)"
      return 0
    fi
  fi
  if [[ "${DEPLOY_BUNDLED:-0}" == 1 ]]; then
    SELF_UPDATE_MODE=standalone_dist
    return 0
  fi
}

self_update_nullable_json() {
  if [[ -n "${1:-}" ]]; then app_json_string "$1"; else printf 'null'; fi
}

self_update_version_json() {
  local can_update=false
  self_update_detect_mode
  [[ "$SELF_UPDATE_MODE" == managed_release ]] && can_update=true
  printf '{"schema_version":1,"mode":%s,"version":%s,"previous_version":%s,"channel":%s,"root":%s,"current_path":%s,"previous_path":%s,"can_update":%s}\n' \
    "$(app_json_string "$SELF_UPDATE_MODE")" \
    "$(self_update_nullable_json "$SELF_UPDATE_VERSION")" \
    "$(self_update_nullable_json "$SELF_UPDATE_PREVIOUS_VERSION")" \
    "$(app_json_string "${DEPLOY_SELF_UPDATE_CHANNEL:-stable}")" \
    "$(self_update_nullable_json "$SELF_UPDATE_ROOT")" \
    "$(self_update_nullable_json "$SELF_UPDATE_CURRENT_PATH")" \
    "$(self_update_nullable_json "$SELF_UPDATE_PREVIOUS_PATH")" \
    "$can_update"
}

self_update_print_version() {
  local json="$1"
  if [[ "$json" == 1 ]]; then
    self_update_version_json
    return 0
  fi
  self_update_detect_mode
  printf 'mode: %s\n' "$SELF_UPDATE_MODE"
  printf 'version: %s\n' "${SELF_UPDATE_VERSION:-unknown}"
  printf 'previous_version: %s\n' "${SELF_UPDATE_PREVIOUS_VERSION:-unknown}"
  printf 'channel: %s\n' "${DEPLOY_SELF_UPDATE_CHANNEL:-stable}"
  [[ -n "$SELF_UPDATE_ROOT" ]] && printf 'root: %s\n' "$SELF_UPDATE_ROOT"
}

self_update_manifest_url() {
  local base="${DEPLOY_SELF_UPDATE_URL:-}"
  [[ -n "$base" ]] || return 1
  if [[ "$base" == */manifest.json ]]; then
    printf '%s\n' "$base"
  else
    printf '%s/manifest.json\n' "${base%/}"
  fi
}

self_update_manifest_set_error() {
  [[ -n "${SELF_UPDATE_MANIFEST_ERROR:-}" ]] || SELF_UPDATE_MANIFEST_ERROR="$1"
  SELF_UPDATE_MANIFEST_VALID=0
}

self_update_validate_manifest_file() {
  local manifest_file="$1" object schema project channel version artifact_name artifact_url sha256 size_bytes
  SELF_UPDATE_MANIFEST_ERROR=""
  SELF_UPDATE_MANIFEST_VALID=1
SELF_UPDATE_MANAGER_LOCK_ACQUIRED=0
  [[ -s "$manifest_file" ]] || self_update_manifest_set_error 'manifest is empty'
  object="$(cat "$manifest_file" 2>/dev/null)" || self_update_manifest_set_error 'manifest cannot be read'
  schema="$(state_json_field "$object" schema_version 2>/dev/null || true)"
  project="$(state_json_field "$object" project 2>/dev/null || true)"
  channel="$(state_json_field "$object" channel 2>/dev/null || true)"
  version="$(state_json_field "$object" version 2>/dev/null || true)"
  artifact_name="$(state_json_field "$object" artifacts.source.name 2>/dev/null || true)"
  artifact_url="$(state_json_field "$object" artifacts.source.url 2>/dev/null || true)"
  sha256="$(state_json_field "$object" artifacts.source.sha256 2>/dev/null || true)"
  size_bytes="$(state_json_field "$object" artifacts.source.size_bytes 2>/dev/null || true)"
  [[ "$schema" == 1 ]] || self_update_manifest_set_error 'unsupported manifest schema'
  [[ "$project" == deploy-scripts ]] || self_update_manifest_set_error 'manifest project mismatch'
  [[ "$channel" == "${DEPLOY_SELF_UPDATE_CHANNEL:-stable}" ]] || self_update_manifest_set_error 'manifest channel mismatch'
  [[ "$version" =~ ^v([0]|[1-9][0-9]*)\.([0]|[1-9][0-9]*)\.([0]|[1-9][0-9]*)(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?$ ]] || self_update_manifest_set_error 'manifest version is invalid'
  [[ "$artifact_name" == "deploy-scripts-${version}.tar.gz" ]] || self_update_manifest_set_error 'manifest artifact name is invalid'
  self_update_validate_https_url "$artifact_url" || self_update_manifest_set_error 'manifest artifact URL is not HTTPS'
  [[ "${artifact_url%/}" == */"$artifact_name" ]] || self_update_manifest_set_error 'manifest artifact URL does not match artifact name'
  [[ "$sha256" =~ ^[0-9a-f]{64}$ ]] || self_update_manifest_set_error 'manifest artifact hash is invalid'
  [[ "$size_bytes" =~ ^[1-9][0-9]*$ ]] || self_update_manifest_set_error 'manifest artifact size is invalid'
  (( SELF_UPDATE_MANIFEST_VALID == 1 )) || return 1
  SELF_UPDATE_MANIFEST_VERSION="$version"
  SELF_UPDATE_MANIFEST_NAME="$artifact_name"
  SELF_UPDATE_MANIFEST_URL="$artifact_url"
  SELF_UPDATE_MANIFEST_SHA256="$sha256"
  SELF_UPDATE_MANIFEST_SIZE_BYTES="$size_bytes"
  return 0
}

self_update_check_json() {
  local state="$1" error_message="${2:-}" current_version="${SELF_UPDATE_VERSION:-}"
  printf '{"schema_version":1,"mode":%s,"channel":%s,"state":%s,"current_version":%s,"latest_version":%s,"manifest_url":%s,"artifact":{"name":%s,"url":%s,"sha256":%s,"size_bytes":%s},"error":%s}\n' \
    "$(app_json_string "${SELF_UPDATE_MODE:-unknown}")" \
    "$(app_json_string "${DEPLOY_SELF_UPDATE_CHANNEL:-stable}")" \
    "$(app_json_string "$state")" \
    "$(self_update_nullable_json "$current_version")" \
    "$(self_update_nullable_json "${SELF_UPDATE_MANIFEST_VERSION:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_CHECK_MANIFEST_URL:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_MANIFEST_NAME:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_MANIFEST_URL:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_MANIFEST_SHA256:-}")" \
    "${SELF_UPDATE_MANIFEST_SIZE_BYTES:-null}" \
    "$(self_update_nullable_json "$error_message")"
}

self_update_fetch_file() {
  local url="$1" output="$2" max_bytes="$3"
  self_update_validate_https_url "$url" || return 1
  curl -fsSL --proto '=https' --proto-redir '=https' \
    --max-time "$DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS" \
    --max-filesize "$max_bytes" -o "$output" "$url" 2>/dev/null
  [[ -s "$output" ]] || return 1
}

self_update_validate_archive_layout() {
  local archive_path="$1" extraction_root="$2" expected_version="$3"
  local member member_type top_prefix archive_members archive_listing
  top_prefix="deploy-scripts-${expected_version}/"
  archive_members="$(tar -tzf "$archive_path" 2>/dev/null)" || return 1
  while IFS= read -r member; do
    [[ -n "$member" ]] || continue
    case "$member" in
      /*|../*|*/../*|*/..|*/./*|./*) return 1 ;;
    esac
    [[ "$member" == "$top_prefix"* ]] || return 1
  done <<< "$archive_members"
  archive_listing="$(tar -tvzf "$archive_path" 2>/dev/null)" || return 1
  while IFS= read -r member_type; do
    case "${member_type:0:1}" in
      -|d) ;;
      *) return 1 ;;
    esac
  done < <(printf '%s\n' "$archive_listing" | awk '{ print $1 }')
  mkdir -p "$extraction_root" || return 1
  tar --extract --gzip --file "$archive_path" --directory "$extraction_root" \
    --no-same-owner --no-same-permissions || return 1
  find "$extraction_root" -type l -o -type b -o -type c -o -type p | grep -q . && return 1 || true
  [[ -f "${extraction_root}/${top_prefix}deploy.sh" ]] || return 1
  [[ -f "${extraction_root}/${top_prefix}lib/core.sh" ]] || return 1
  [[ -f "${extraction_root}/${top_prefix}RELEASE.json" ]] || return 1
  local metadata project version schema
  metadata="$(cat "${extraction_root}/${top_prefix}RELEASE.json")" || return 1
  schema="$(state_json_field "$metadata" schema_version 2>/dev/null || true)"
  project="$(state_json_field "$metadata" project 2>/dev/null || true)"
  version="$(state_json_field "$metadata" version 2>/dev/null || true)"
  [[ "$schema" == 1 && "$project" == deploy-scripts && "$version" == "$expected_version" ]] || return 1
  while IFS= read -r -d '' member; do
    bash -n "$member" || return 1
  done < <(find "$extraction_root/${top_prefix%/}" -type f -name '*.sh' -print0)
}

self_update_prepare_candidate() {
  local temp_dir="$1" manifest_file archive_file extraction_root actual_size actual_sha
  manifest_file="${temp_dir}/manifest.json"
  extraction_root="${temp_dir}/extracted"
  self_update_fetch_file "$SELF_UPDATE_CHECK_MANIFEST_URL" "$manifest_file" "$DEPLOY_SELF_UPDATE_MAX_MANIFEST_BYTES" || {
    SELF_UPDATE_MANIFEST_ERROR='manifest download failed'
    return 1
  }
  self_update_validate_manifest_file "$manifest_file" || return 1
  if [[ -n "${SELF_UPDATE_VERSION:-}" ]]; then
    local comparison
    comparison="$(deploy_version_compare "$SELF_UPDATE_MANIFEST_VERSION" "$SELF_UPDATE_VERSION" 2>/dev/null || printf invalid)"
    case "$comparison" in
      1) ;;
      0) SELF_UPDATE_MANIFEST_ERROR='release is already current'; return 1 ;;
      -1) SELF_UPDATE_MANIFEST_ERROR='downgrade is not allowed'; return 1 ;;
      *) SELF_UPDATE_MANIFEST_ERROR='release version comparison failed'; return 1 ;;
    esac
  fi
  archive_file="${temp_dir}/${SELF_UPDATE_MANIFEST_NAME}"
  self_update_fetch_file "$SELF_UPDATE_MANIFEST_URL" "$archive_file" "$DEPLOY_SELF_UPDATE_MAX_ARTIFACT_BYTES" || {
    SELF_UPDATE_MANIFEST_ERROR='artifact download failed'
    return 1
  }
  actual_size="$(wc -c < "$archive_file" | tr -d '[:space:]')"
  [[ "$actual_size" == "$SELF_UPDATE_MANIFEST_SIZE_BYTES" ]] || {
    SELF_UPDATE_MANIFEST_ERROR='artifact size does not match manifest'
    return 1
  }
  actual_sha="$(sha256sum "$archive_file" | awk '{print $1}')"
  [[ "$actual_sha" == "$SELF_UPDATE_MANIFEST_SHA256" ]] || {
    SELF_UPDATE_MANIFEST_ERROR='artifact SHA-256 does not match manifest'
    return 1
  }
  self_update_validate_archive_layout "$archive_file" "$extraction_root" "$SELF_UPDATE_MANIFEST_VERSION" || {
    SELF_UPDATE_MANIFEST_ERROR='artifact failed archive or release validation'
    return 1
  }
  SELF_UPDATE_CANDIDATE_ROOT="${extraction_root}/deploy-scripts-${SELF_UPDATE_MANIFEST_VERSION}"
  SELF_UPDATE_CANDIDATE_ARCHIVE="$archive_file"
  return 0
}

self_update_dry_run_json() {
  local state="$1" error_message="${2:-}"
  printf '{"schema_version":1,"mode":%s,"channel":%s,"state":%s,"current_version":%s,"latest_version":%s,"artifact_name":%s,"artifact_sha256":%s,"artifact_size_bytes":%s,"error":%s}\n' \
    "$(app_json_string "${SELF_UPDATE_MODE:-unknown}")" \
    "$(app_json_string "${DEPLOY_SELF_UPDATE_CHANNEL:-stable}")" \
    "$(app_json_string "$state")" \
    "$(self_update_nullable_json "${SELF_UPDATE_VERSION:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_MANIFEST_VERSION:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_MANIFEST_NAME:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_MANIFEST_SHA256:-}")" \
    "${SELF_UPDATE_MANIFEST_SIZE_BYTES:-null}" \
    "$(self_update_nullable_json "$error_message")"
}

self_update_dry_run_main() {
  local json="$1" temp_dir candidate_error
  self_update_detect_mode
  if [[ "$SELF_UPDATE_MODE" != managed_release ]]; then
    if [[ "$json" == 1 ]]; then self_update_dry_run_json blocked_mode 'dry-run requires managed_release mode'; else printf '%s\n' 'self-update dry-run requires managed_release mode' >&2; fi
    return 2
  fi
  if ! self_update_load_config; then
    if [[ "$json" == 1 ]]; then self_update_dry_run_json check_failed 'self-update configuration is invalid'; else printf '%s\n' 'self-update configuration is invalid' >&2; fi
    return 1
  fi
  SELF_UPDATE_CHECK_MANIFEST_URL="$(self_update_manifest_url 2>/dev/null || true)"
  if ! self_update_validate_https_url "$SELF_UPDATE_CHECK_MANIFEST_URL"; then
    if [[ "$json" == 1 ]]; then self_update_dry_run_json check_failed 'self-update URL must be HTTPS without credentials, queries, or fragments'; else printf '%s\n' 'self-update URL must be HTTPS without credentials, queries, or fragments' >&2; fi
    return 1
  fi
  temp_dir="$(mktemp -d "${TMPDIR:-/tmp}/deploy-scripts-self-dry-run.XXXXXX")" || return 1
  chmod 700 "$temp_dir" || { rm -rf "$temp_dir"; return 1; }
  if ! self_update_prepare_candidate "$temp_dir"; then
    candidate_error="$SELF_UPDATE_MANIFEST_ERROR"
    rm -rf "$temp_dir"
    if [[ "$json" == 1 ]]; then self_update_dry_run_json check_failed "$candidate_error"; else printf 'self-update dry-run failed: %s\n' "$candidate_error" >&2; fi
    return 1
  fi
  rm -rf "$temp_dir"
  if [[ "$json" == 1 ]]; then self_update_dry_run_json validated; else printf 'validated release %s (no files changed)\n' "$SELF_UPDATE_MANIFEST_VERSION"; fi
  return 0
}

self_update_check_main() {
  local json="$1" manifest_url temp_dir manifest_file comparison
  SELF_UPDATE_CHECK_MANIFEST_URL=""
  SELF_UPDATE_CANDIDATE_ROOT=""
  SELF_UPDATE_CANDIDATE_ARCHIVE=""
  SELF_UPDATE_MANIFEST_VERSION=""
  SELF_UPDATE_MANIFEST_URL=""
  SELF_UPDATE_MANIFEST_SHA256=""
  SELF_UPDATE_MANIFEST_SIZE_BYTES=""
  SELF_UPDATE_MANIFEST_NAME=""
  SELF_UPDATE_MANIFEST_ERROR=""
  self_update_detect_mode
  if ! self_update_load_config; then
    if [[ "$json" == 1 ]]; then self_update_check_json check_failed 'self-update configuration is invalid'; else printf '%s\n' 'self-update configuration is invalid' >&2; fi
    return 1
  fi
  if [[ -z "${DEPLOY_SELF_UPDATE_URL:-}" ]]; then
    if [[ "$json" == 1 ]]; then self_update_check_json not_configured; else printf 'self-update URL is not configured\n' >&2; fi
    return 2
  fi
  manifest_url="$(self_update_manifest_url)" || return 1
  self_update_validate_https_url "$manifest_url" || {
    if [[ "$json" == 1 ]]; then self_update_check_json check_failed 'self-update URL must be HTTPS without credentials, queries, or fragments'; else printf '%s\n' 'self-update URL must be HTTPS without credentials, queries, or fragments' >&2; fi
    return 1
  }
  SELF_UPDATE_CHECK_MANIFEST_URL="$manifest_url"
  temp_dir="$(mktemp -d "${TMPDIR:-/tmp}/deploy-scripts-self-check.XXXXXX")" || return 1
  chmod 700 "$temp_dir" || { rm -rf "$temp_dir"; return 1; }
  manifest_file="${temp_dir}/manifest.json"
  if ! curl -fsSL --proto '=https' --proto-redir '=https' --max-time "$DEPLOY_SELF_UPDATE_TIMEOUT_SECONDS" --max-filesize "$DEPLOY_SELF_UPDATE_MAX_MANIFEST_BYTES" -o "$manifest_file" "$manifest_url" 2>/dev/null; then
    rm -rf "$temp_dir"
    if [[ "$json" == 1 ]]; then self_update_check_json check_failed 'manifest download failed'; else printf 'manifest download failed\n' >&2; fi
    return 1
  fi
  if ! self_update_validate_manifest_file "$manifest_file"; then
    local manifest_error="$SELF_UPDATE_MANIFEST_ERROR"
    rm -rf "$temp_dir"
    if [[ "$json" == 1 ]]; then self_update_check_json check_failed "$manifest_error"; else printf 'manifest validation failed: %s\n' "$manifest_error" >&2; fi
    return 1
  fi
  rm -rf "$temp_dir"
  if [[ -n "$SELF_UPDATE_VERSION" ]]; then
    comparison="$(deploy_version_compare "$SELF_UPDATE_MANIFEST_VERSION" "$SELF_UPDATE_VERSION" 2>/dev/null || printf invalid)"
    case "$comparison" in
      -1|0) self_update_check_json up_to_date; return 0 ;;
      1) self_update_check_json update_available; return 0 ;;
    esac
  fi
  self_update_check_json unknown_current; return 0
}


self_update_acquire_lock() {
  local lock_file="${DEPLOY_SELF_UPDATE_LOCK_FILE:-${DEPLOY_OPERATION_ROOT}/locks/self-update.lock}" lock_dir
  lock_dir="$(dirname -- "$lock_file")"
  [[ ! -L "$lock_dir" ]] || return 1
  mkdir -p "$lock_dir" || return 1
  operation_set_owner_and_mode "$lock_dir" 750 || return 1
  command -v flock >/dev/null 2>&1 || return 1
  exec 7>"$lock_file" || return 1
  operation_set_owner_and_mode "$lock_file" 600 || { exec 7>&-; return 1; }
  flock -n 7 || { exec 7>&-; return 9; }
}

self_update_release_lock() {
  flock -u 7 2>/dev/null || true
  exec 7>&- 2>/dev/null || true
}

self_update_acquire_coordination_locks() {
  local status
  SELF_UPDATE_MANAGER_LOCK_ACQUIRED=0
  self_update_acquire_lock
  status=$?
  (( status == 0 )) || return "$status"
  if declare -F manager_update_acquire_lock >/dev/null 2>&1; then
    manager_update_acquire_lock
    status=$?
    if (( status != 0 )); then
      self_update_release_lock
      return "$status"
    fi
    SELF_UPDATE_MANAGER_LOCK_ACQUIRED=1
  fi
}

self_update_release_coordination_locks() {
  if (( SELF_UPDATE_MANAGER_LOCK_ACQUIRED == 1 )); then
    manager_update_release_lock
    SELF_UPDATE_MANAGER_LOCK_ACQUIRED=0
  fi
  self_update_release_lock
}

self_update_current_target_for() {
  local managed_root="$1" current_path resolved release_root
  current_path="${managed_root}/current"
  [[ -L "$current_path" ]] || return 1
  resolved="$(self_update_realpath "$current_path")" || return 1
  release_root="$(self_update_realpath "${managed_root}/releases")" || return 1
  [[ "$resolved" == "$release_root/"* ]] || return 1
  [[ -d "$resolved" ]] || return 1
  self_update_release_version_from_root "$resolved" >/dev/null || return 1
  printf '%s\n' "$resolved"
}

self_update_release_path_is_safe() {
  local managed_root="$1" release_path="$2" releases_root resolved
  releases_root="$(self_update_realpath "${managed_root}/releases")" || return 1
  resolved="$(self_update_realpath "$release_path")" || true
  [[ "$release_path" == "$managed_root/releases/"* ]] || return 1
  [[ ! -L "$release_path" ]] || return 1
  [[ ! -e "$release_path" ]] || return 1
  [[ "$release_path" != "$managed_root/releases" ]] || return 1
  [[ "$release_path" == "$releases_root/"* ]] || return 1
}

self_update_prepare_activation_root() {
  local managed_root="$1" releases_root temp_dir
  [[ -d "$managed_root" && ! -L "$managed_root" ]] || return 1
  releases_root="${managed_root}/releases"
  [[ ! -L "$releases_root" ]] || return 1
  mkdir -p "$releases_root" || return 1
  temp_dir="$(mktemp -d "${managed_root}/.self-update.XXXXXX")" || return 1
  chmod 700 "$temp_dir" || { rm -rf "$temp_dir"; return 1; }
  printf '%s\n' "$temp_dir"
}

self_update_atomic_restore_current() {
  local managed_root="$1" old_target="$2"
  [[ -n "$old_target" ]] || return 1
  atomic_symlink "$old_target" "${managed_root}/current"
}

self_update_restore_previous_target() {
  local managed_root="$1" old_target="${2:-}"
  local previous_path="${managed_root}/previous"
  if [[ -n "$old_target" ]]; then
    atomic_symlink "$old_target" "$previous_path"
    return $?
  fi
  [[ ! -e "$previous_path" && ! -L "$previous_path" ]] && return 0
  [[ ! -d "$previous_path" ]] || return 1
  rm -f -- "$previous_path"
}

self_update_discard_failed_release() {
  local managed_root="$1" release_path="${2:-}" releases_root resolved
  [[ -n "$release_path" && -e "$release_path" ]] || return 0
  releases_root="$(self_update_realpath "${managed_root}/releases")" || return 1
  resolved="$(self_update_realpath "$release_path")" || return 1
  [[ "$release_path" == "$managed_root/releases/"* ]] || return 1
  [[ "$resolved" == "$releases_root/"* ]] || return 1
  [[ -d "$release_path" && ! -L "$release_path" ]] || return 1
  rm -rf -- "$release_path"
}

self_update_activate_candidate() {
  local managed_root="$1" candidate_root="$2" version="$3"
  local releases_root release_path old_target old_previous_target=""
  releases_root="${managed_root}/releases"
  [[ -d "$releases_root" && ! -L "$releases_root" ]] || return 1
  release_path="${releases_root}/${version}"
  self_update_release_path_is_safe "$managed_root" "$release_path" || return 1
  old_target="$(self_update_current_target_for "$managed_root")" || return 1
  if [[ -e "${managed_root}/previous" || -L "${managed_root}/previous" ]]; then
    old_previous_target="$(self_update_previous_target_for "$managed_root")" || return 1
  fi
  [[ -d "$candidate_root" && ! -L "$candidate_root" ]] || return 1
  # Publish the rollback coordinates before the first filesystem mutation so a
  # signal delivered between the atomic pointer operations can still restore
  # the old layout from the EXIT trap.
  SELF_UPDATE_OLD_TARGET="$old_target"
  SELF_UPDATE_OLD_PREVIOUS_TARGET="$old_previous_target"
  SELF_UPDATE_RELEASE_PATH="$release_path"
  SELF_UPDATE_ACTIVATION_STARTED=1
  mv -- "$candidate_root" "$release_path" || { SELF_UPDATE_ACTIVATION_STARTED=0; return 1; }
  if ! atomic_symlink "$old_target" "${managed_root}/previous"; then
    rm -rf -- "$release_path"
    SELF_UPDATE_ACTIVATION_STARTED=0
    SELF_UPDATE_RELEASE_PATH=""
    return 1
  fi
  # Set this before switching current: Bash may dispatch a pending signal
  # before executing the next assignment after atomic_symlink returns.
  SELF_UPDATE_CURRENT_CHANGED=1
  if ! atomic_symlink "$release_path" "${managed_root}/current"; then
    self_update_atomic_restore_current "$managed_root" "$old_target" || true
    self_update_restore_previous_target "$managed_root" "$old_previous_target" || true
    rm -rf -- "$release_path"
    SELF_UPDATE_CURRENT_CHANGED=0
    SELF_UPDATE_ACTIVATION_STARTED=0
    SELF_UPDATE_RELEASE_PATH=""
    return 1
  fi
  printf '%s\n' "$release_path"
}

self_update_interrupted_cleanup() {
  local status="${1:-1}" restored=1 release_path="${SELF_UPDATE_RELEASE_PATH:-}"
  [[ "${SELF_UPDATE_ACTIVATION_STARTED:-0}" == 1 ]] || return 0
  if [[ "${SELF_UPDATE_CURRENT_CHANGED:-0}" == 1 ]]; then
    self_update_atomic_restore_current "$SELF_UPDATE_MANAGED_ROOT" "${SELF_UPDATE_OLD_TARGET:-}" || restored=0
  fi
  self_update_restore_previous_target "$SELF_UPDATE_MANAGED_ROOT" "${SELF_UPDATE_OLD_PREVIOUS_TARGET:-}" || restored=0
  if [[ -n "$release_path" ]]; then
    self_update_discard_failed_release "$SELF_UPDATE_MANAGED_ROOT" "$release_path" || restored=0
  fi
  if (( restored )); then
    SELF_UPDATE_CURRENT_CHANGED=0
    SELF_UPDATE_ACTIVATION_STARTED=0
    SELF_UPDATE_RELEASE_PATH=""
    OPERATION_INTERRUPTION_SUMMARY="self-update interrupted by SIG${OPERATION_INTERRUPTED_SIGNAL:-TERM}; current was restored"
  else
    OPERATION_INTERRUPTION_SUMMARY="self-update interrupted by SIG${OPERATION_INTERRUPTED_SIGNAL:-TERM}; current may require manual recovery"
  fi
  return 0
}

self_update_smoke_check() {
  local release_root="$1" output_dir status command_output
  output_dir="$(mktemp -d "${TMPDIR:-/tmp}/deploy-scripts-smoke.XXXXXX")" || return 1
  chmod 700 "$output_dir" || { rm -rf "$output_dir"; return 1; }
  command_output="${output_dir}/list.out"
  if ! DEPLOY_SELF_UPDATE_ROOT="$SELF_UPDATE_MANAGED_ROOT" bash "${release_root}/deploy.sh" list >"$command_output" 2>"${output_dir}/list.err"; then
    rm -rf "$output_dir"
    return 1
  fi
  if ! DEPLOY_SELF_UPDATE_ROOT="$SELF_UPDATE_MANAGED_ROOT" bash "${release_root}/deploy.sh" self-version --json >"${output_dir}/version.out" 2>"${output_dir}/version.err"; then
    rm -rf "$output_dir"
    return 1
  fi
  if ! python - "${output_dir}/version.out" <<'PY'
import json
import sys
with open(sys.argv[1], encoding="utf-8") as handle:
    payload = json.load(handle)
assert payload.get("schema_version") == 1
assert payload.get("mode") == "managed_release"
PY
  then
    rm -rf "$output_dir"
    return 1
  fi
  if ! DEPLOY_SELF_UPDATE_ROOT="$SELF_UPDATE_MANAGED_ROOT" bash "${release_root}/deploy.sh" status-all --json --no-network >"${output_dir}/status.out" 2>"${output_dir}/status.err"; then
    rm -rf "$output_dir"
    return 1
  fi
  python - "${output_dir}/status.out" <<'PY'
import json
import sys
with open(sys.argv[1], encoding="utf-8") as handle:
    payload = json.load(handle)
assert payload.get("schema_version") == 1
PY
  status=$?
  rm -rf "$output_dir"
  return "$status"
}

self_update_operation_begin() {
  local previous_trap previous_int_trap previous_term_trap previous_hup_trap
  operation_start self_update "" self-update || return 1
  operation_step_start prepare || { operation_reset; return 1; }
  if (( BASH_SUBSHELL == 0 )); then
    previous_trap="$(trap -p EXIT)"
    previous_int_trap="$(trap -p INT)"
    previous_term_trap="$(trap -p TERM)"
    previous_hup_trap="$(trap -p HUP)"
  else
    # EXIT traps from a command substitution belong to the parent shell. Do
    # not reinstall them in this subshell or they would run during normal
    # command-substitution teardown.
    previous_trap=""
    previous_int_trap=""
    previous_term_trap=""
    previous_hup_trap=""
  fi
  OPERATION_PREVIOUS_EXIT_TRAP="$previous_trap"
  OPERATION_PREVIOUS_INT_TRAP="$previous_int_trap"
  OPERATION_PREVIOUS_TERM_TRAP="$previous_term_trap"
  OPERATION_PREVIOUS_HUP_TRAP="$previous_hup_trap"
  OPERATION_INTERRUPTION_CLEANUP_FN=self_update_interrupted_cleanup
  trap 'operation_action_exit_trap' EXIT
  trap 'operation_action_signal_trap INT' INT
  trap 'operation_action_signal_trap TERM' TERM
  trap 'operation_action_signal_trap HUP' HUP
}

self_update_operation_finish() {
  local exit_code="$1" state="$2" summary="${3:-}" previous_trap="${OPERATION_PREVIOUS_EXIT_TRAP:-}"
  if [[ "${OPERATION_ACTIVE:-0}" == 1 ]]; then
    operation_restore_signal_traps || true
    operation_restore_exit_trap "$previous_trap" || true
  fi
  operation_finish "$exit_code" "$state" "$summary" || true
}

self_update_confirm() {
  local yes="$1" version="$2" answer
  [[ "$yes" == 1 || "${DEPLOY_ASSUME_YES:-0}" == 1 ]] && return 0
  if [[ ! -t 0 ]]; then
    printf 'self-update requires --yes or DEPLOY_ASSUME_YES=1 when standard input is not interactive.\n' >&2
    return 2
  fi
  printf 'Activate framework %s? [y/N] ' "$version" >&2
  read -r answer
  [[ "${answer,,}" == y || "${answer,,}" == yes ]]
}

self_update_apply_json() {
  local state="$1" error_message="${2:-}"
  printf '{"schema_version":1,"mode":%s,"state":%s,"current_version":%s,"latest_version":%s,"release_path":%s,"error":%s}\n' \
    "$(app_json_string "${SELF_UPDATE_MODE:-unknown}")" \
    "$(app_json_string "$state")" \
    "$(self_update_nullable_json "${SELF_UPDATE_VERSION:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_MANIFEST_VERSION:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_RELEASE_PATH:-}")" \
    "$(self_update_nullable_json "$error_message")"
}

self_update_apply_main() {
  local json="$1" yes="$2" temp_dir candidate_error candidate_root
  local current_step="prepare" smoke_status lock_status had_errexit=0
  SELF_UPDATE_MANIFEST_VERSION=""
  SELF_UPDATE_MANIFEST_URL=""
  SELF_UPDATE_MANIFEST_SHA256=""
  SELF_UPDATE_MANIFEST_SIZE_BYTES=""
  SELF_UPDATE_MANIFEST_NAME=""
  SELF_UPDATE_MANIFEST_ERROR=""
  SELF_UPDATE_RELEASE_PATH=""
  SELF_UPDATE_OLD_TARGET=""
  SELF_UPDATE_OLD_PREVIOUS_TARGET=""
  SELF_UPDATE_CURRENT_CHANGED=0
  SELF_UPDATE_ACTIVATION_STARTED=0
  self_update_detect_mode
  if [[ "$SELF_UPDATE_MODE" != managed_release ]]; then
    if (( json )); then self_update_apply_json blocked_mode 'self-update requires managed_release mode'; else printf '%s\n' 'self-update requires managed_release mode; use --check in checkout or standalone mode' >&2; fi
    return 2
  fi
  if [[ "${EUID:-$(id -u)}" -ne 0 && "${DEPLOY_SELF_UPDATE_ALLOW_NONROOT_TEST:-0}" != 1 ]]; then
    if (( json )); then self_update_apply_json permission_denied 'self-update requires root'; else printf '%s\n' 'self-update requires root' >&2; fi
    return 1
  fi
  self_update_load_config || {
    if (( json )); then self_update_apply_json check_failed 'self-update configuration is invalid'; else printf '%s\n' 'self-update configuration is invalid' >&2; fi
    return 1
  }
  if self_update_acquire_coordination_locks; then
    :
  else
    lock_status=$?
    if (( lock_status == 9 )); then
      if (( json )); then self_update_apply_json locked 'another managed write is running'; else printf '%s\n' 'another managed write is running' >&2; fi
      return 9
    fi
    if (( json )); then self_update_apply_json failed 'unable to acquire self-update coordination locks'; else printf '%s\n' 'unable to acquire self-update coordination locks' >&2; fi
    return 1
  fi
  if ! self_update_operation_begin; then
    self_update_release_coordination_locks
    if (( json )); then self_update_apply_json failed 'unable to create self-update operation record'; else printf '%s\n' 'unable to create self-update operation record' >&2; fi
    return 1
  fi
  operation_started=1
  temp_dir="$(self_update_prepare_activation_root "$SELF_UPDATE_MANAGED_ROOT")" || {
    self_update_operation_finish 1 failed 'unable to create private activation staging directory'
    self_update_release_coordination_locks
    if (( json )); then self_update_apply_json failed 'unable to create private activation staging directory'; else printf '%s\n' 'unable to create private activation staging directory' >&2; fi
    return 1
  }
  if ! self_update_load_config || ! self_update_manifest_url >/dev/null; then
    candidate_error='self-update configuration is invalid'
    rm -rf "$temp_dir"
    operation_step_finish "$current_step" failed || true
    self_update_operation_finish 1 failed "$candidate_error"
    self_update_release_coordination_locks
    if (( json )); then self_update_apply_json check_failed "$candidate_error"; else printf '%s\n' "$candidate_error" >&2; fi
    return 1
  fi
  SELF_UPDATE_CHECK_MANIFEST_URL="$(self_update_manifest_url)"
  if ! self_update_validate_https_url "$SELF_UPDATE_CHECK_MANIFEST_URL"; then
    candidate_error='self-update URL must be HTTPS without credentials, queries, or fragments'
    rm -rf "$temp_dir"
    operation_step_finish "$current_step" failed || true
    self_update_operation_finish 1 failed "$candidate_error"
    self_update_release_coordination_locks
    if (( json )); then self_update_apply_json check_failed "$candidate_error"; else printf '%s\n' "$candidate_error" >&2; fi
    return 1
  fi
  if ! self_update_prepare_candidate "$temp_dir"; then
    candidate_error="${SELF_UPDATE_MANIFEST_ERROR:-release validation failed}"
    rm -rf "$temp_dir"
    operation_step_finish "$current_step" failed || true
    self_update_operation_finish 1 failed "$candidate_error"
    self_update_release_coordination_locks
    if (( json )); then self_update_apply_json check_failed "$candidate_error"; else printf 'self-update failed: %s\n' "$candidate_error" >&2; fi
    return 1
  fi
  candidate_root="$SELF_UPDATE_CANDIDATE_ROOT"
  operation_step_finish prepare succeeded || true
  current_step=activate
  operation_step_start activate || true
  self_update_confirm "$yes" "$SELF_UPDATE_MANIFEST_VERSION" || {
    candidate_error='self-update was not confirmed'
    rm -rf "$temp_dir"
    operation_step_finish activate skipped || true
    self_update_operation_finish 2 cancelled "$candidate_error"
    self_update_release_coordination_locks
    if (( json )); then self_update_apply_json cancelled "$candidate_error"; else printf '%s\n' "$candidate_error" >&2; fi
    return 2
  }
  if ! self_update_activate_candidate "$SELF_UPDATE_MANAGED_ROOT" "$candidate_root" "$SELF_UPDATE_MANIFEST_VERSION" >/dev/null; then
    candidate_error='atomic release activation failed'
    rm -rf "$temp_dir"
    operation_step_finish activate failed || true
    self_update_operation_finish 1 failed "$candidate_error"
    self_update_release_coordination_locks
    if (( json )); then self_update_apply_json failed "$candidate_error"; else printf '%s\n' "$candidate_error" >&2; fi
    return 1
  fi
  rm -rf "$temp_dir"
  operation_step_finish activate succeeded || true
  current_step=smoke_check
  operation_step_start smoke_check || true
  case "$-" in *e*) had_errexit=1;; esac
  set +e
  self_update_smoke_check "$SELF_UPDATE_RELEASE_PATH"
  smoke_status=$?
  (( had_errexit == 1 )) && set -e || set +e
  if [[ "$smoke_status" -eq 0 ]]; then
    SELF_UPDATE_VERSION="$SELF_UPDATE_MANIFEST_VERSION"
    operation_step_finish smoke_check succeeded || true
    self_update_cleanup_releases "$SELF_UPDATE_MANAGED_ROOT" || printf '%s\n' 'self-update: warning: release retention cleanup failed' >&2
    SELF_UPDATE_CURRENT_CHANGED=0
    SELF_UPDATE_ACTIVATION_STARTED=0
    self_update_operation_finish 0 succeeded
    self_update_release_coordination_locks
    if (( json )); then self_update_apply_json succeeded; else printf 'self-update activated %s\n' "$SELF_UPDATE_MANIFEST_VERSION"; fi
    return 0
  fi
  operation_step_finish smoke_check failed || true
  operation_step_start rollback || true
  if self_update_atomic_restore_current "$SELF_UPDATE_MANAGED_ROOT" "$SELF_UPDATE_OLD_TARGET" \
      && self_update_restore_previous_target "$SELF_UPDATE_MANAGED_ROOT" "${SELF_UPDATE_OLD_PREVIOUS_TARGET:-}"; then
    self_update_discard_failed_release "$SELF_UPDATE_MANAGED_ROOT" "$SELF_UPDATE_RELEASE_PATH" \
      || printf '%s\n' 'self-update: warning: could not remove failed release candidate' >&2
    operation_step_finish rollback succeeded || true
    SELF_UPDATE_CURRENT_CHANGED=0
    SELF_UPDATE_ACTIVATION_STARTED=0
    SELF_UPDATE_RELEASE_PATH=""
    self_update_operation_finish 1 rolled_back 'new release smoke check failed; current was restored'
    self_update_release_coordination_locks
    if (( json )); then self_update_apply_json rolled_back 'new release smoke check failed; current was restored'; else printf '%s\n' 'new release smoke check failed; current was restored' >&2; fi
    return 1
  fi
  operation_step_finish rollback failed || true
  self_update_operation_finish 1 rollback_failed 'new release smoke check failed and current could not be restored'
  self_update_release_coordination_locks
  if (( json )); then self_update_apply_json rollback_failed 'new release smoke check failed and current could not be restored'; else printf '%s\n' 'new release smoke check failed and current could not be restored' >&2; fi
  return 1
}


self_update_previous_target_for() {
  local managed_root="$1" previous_path resolved release_root
  previous_path="${managed_root}/previous"
  [[ -L "$previous_path" ]] || return 1
  resolved="$(self_update_realpath "$previous_path")" || return 1
  release_root="$(self_update_realpath "${managed_root}/releases")" || return 1
  [[ "$resolved" == "$release_root/"* && -d "$resolved" ]] || return 1
  self_update_release_version_from_root "$resolved" >/dev/null || return 1
  printf '%s\n' "$resolved"
}

self_update_sorted_release_paths() {
  local managed_root="$1" release_root path version
  release_root="${managed_root}/releases"
  [[ -d "$release_root" && ! -L "$release_root" ]] || return 1
  while IFS= read -r -d '' path; do
    [[ -d "$path" && ! -L "$path" ]] || continue
    version="$(self_update_release_version_from_root "$path" 2>/dev/null || true)"
    [[ -n "$version" ]] || continue
    printf '%s\t%s\n' "$version" "$path"
  done < <(find "$release_root" -mindepth 1 -maxdepth 1 -type d -print0)
}

self_update_release_is_protected() {
  local path="$1" current_target="${SELF_UPDATE_CURRENT_TARGET:-}" previous_target="${SELF_UPDATE_PREVIOUS_TARGET:-}"
  [[ -n "$current_target" && "$path" == "$current_target" ]] && return 0
  [[ -n "$previous_target" && "$path" == "$previous_target" ]] && return 0
  return 1
}

self_update_cleanup_releases() {
  local managed_root="$1" keep_count="${DEPLOY_SELF_UPDATE_KEEP_RELEASES:-3}" current_target previous_target
  local line version path count=0
  local -a entries=()
  [[ "$keep_count" =~ ^[3-9][0-9]*$ ]] || keep_count=3
  current_target="$(self_update_current_target_for "$managed_root" 2>/dev/null || true)"
  previous_target="$(self_update_previous_target_for "$managed_root" 2>/dev/null || true)"
  SELF_UPDATE_CURRENT_TARGET="$current_target"
  SELF_UPDATE_PREVIOUS_TARGET="$previous_target"
  while IFS= read -r line; do [[ -n "$line" ]] && entries+=("$line"); done < <(self_update_sorted_release_paths "$managed_root" | sort -t $'\t' -k1,1Vr)
  for line in "${entries[@]}"; do
    version="${line%%$'\t'*}"
    path="${line#*$'\t'}"
    if self_update_release_is_protected "$path"; then
      continue
    fi
    if (( count < keep_count )); then
      count=$((count + 1))
      continue
    fi
    [[ "$path" == "$managed_root/releases/"* && ! -L "$path" ]] || continue
    rm -rf -- "$path" || printf 'self-update: warning: could not remove old release %s\n' "$version" >&2
  done
  return 0
}

self_update_list_json() {
  local managed_root="$1" first=1 line version path
  printf '{"schema_version":1,"mode":%s,"releases":[' "$(app_json_string "$SELF_UPDATE_MODE")"
  while IFS= read -r line; do
    [[ -n "$line" ]] || continue
    version="${line%%$'\t'*}"
    path="${line#*$'\t'}"
    (( first )) || printf ','
    first=0
    printf '{"version":%s,"path":%s,"current":%s,"previous":%s}' \
      "$(app_json_string "$version")" "$(app_json_string "$path")" \
      "$(app_json_bool "$(self_update_release_is_protected "$path" && [[ "$path" == "${SELF_UPDATE_CURRENT_TARGET:-}" ]] && printf true || printf false)")" \
      "$(app_json_bool "$(self_update_release_is_protected "$path" && [[ "$path" == "${SELF_UPDATE_PREVIOUS_TARGET:-}" ]] && printf true || printf false)")"
  done < <(self_update_sorted_release_paths "$managed_root" | sort -t $'\t' -k1,1Vr)
  printf ']}\n'
}

self_update_list_main() {
  local json="$1"
  self_update_detect_mode
  if [[ "$SELF_UPDATE_MODE" != managed_release ]]; then
    if (( json )); then printf '{"schema_version":1,"mode":%s,"releases":[],"error":"managed release mode required"}\n' "$(app_json_string "$SELF_UPDATE_MODE")"; else printf '%s\n' 'self-update --list requires managed_release mode' >&2; fi
    return 2
  fi
  self_update_current_target_for "$SELF_UPDATE_MANAGED_ROOT" >/dev/null || true
  SELF_UPDATE_CURRENT_TARGET="$(self_update_current_target_for "$SELF_UPDATE_MANAGED_ROOT" 2>/dev/null || true)"
  SELF_UPDATE_PREVIOUS_TARGET="$(self_update_previous_target_for "$SELF_UPDATE_MANAGED_ROOT" 2>/dev/null || true)"
  if (( json )); then
    self_update_list_json "$SELF_UPDATE_MANAGED_ROOT"
  else
    self_update_sorted_release_paths "$SELF_UPDATE_MANAGED_ROOT" | sort -t $'\t' -k1,1Vr | awk -F '\t' '{ print $1 "\t" $2 }'
  fi
}

self_update_rollback_json() {
  local state="$1" error_message="${2:-}"
  printf '{"schema_version":1,"mode":%s,"state":%s,"current_version":%s,"target_version":%s,"error":%s}\n' \
    "$(app_json_string "${SELF_UPDATE_MODE:-unknown}")" \
    "$(app_json_string "$state")" \
    "$(self_update_nullable_json "${SELF_UPDATE_VERSION:-}")" \
    "$(self_update_nullable_json "${SELF_UPDATE_ROLLBACK_TARGET_VERSION:-}")" \
    "$(self_update_nullable_json "$error_message")"
}

self_update_rollback_main() {
  local json="$1" yes="$2" old_target previous_target old_version target_version
  local lock_status candidate_error smoke_status had_errexit=0
  self_update_detect_mode
  if [[ "$SELF_UPDATE_MODE" != managed_release ]]; then
    if (( json )); then self_update_rollback_json blocked_mode 'rollback requires managed_release mode'; else printf '%s\n' 'self-update rollback requires managed_release mode' >&2; fi
    return 2
  fi
  if [[ "${EUID:-$(id -u)}" -ne 0 && "${DEPLOY_SELF_UPDATE_ALLOW_NONROOT_TEST:-0}" != 1 ]]; then
    if (( json )); then self_update_rollback_json permission_denied 'rollback requires root'; else printf '%s\n' 'self-update rollback requires root' >&2; fi
    return 1
  fi
  self_update_load_config || {
    if (( json )); then self_update_rollback_json failed 'self-update configuration is invalid'; else printf '%s\n' 'self-update configuration is invalid' >&2; fi
    return 1
  }
  if self_update_acquire_coordination_locks; then
    :
  else
    lock_status=$?
    if (( lock_status == 9 )); then
      if (( json )); then self_update_rollback_json locked 'another managed write is running'; else printf '%s\n' 'another managed write is running' >&2; fi
      return 9
    fi
    if (( json )); then self_update_rollback_json failed 'unable to acquire self-update coordination locks'; else printf '%s\n' 'unable to acquire self-update coordination locks' >&2; fi
    return 1
  fi
  if ! self_update_operation_begin; then
    self_update_release_coordination_locks
    if (( json )); then self_update_rollback_json failed 'unable to create self-update operation record'; else printf '%s\n' 'unable to create self-update operation record' >&2; fi
    return 1
  fi
  old_target="$(self_update_current_target_for "$SELF_UPDATE_MANAGED_ROOT" 2>/dev/null || true)"
  previous_target="$(self_update_previous_target_for "$SELF_UPDATE_MANAGED_ROOT" 2>/dev/null || true)"
  old_version="$(self_update_release_version_from_root "$old_target" 2>/dev/null || true)"
  target_version="$(self_update_release_version_from_root "$previous_target" 2>/dev/null || true)"
  SELF_UPDATE_ROLLBACK_TARGET_VERSION="$target_version"
  if [[ -z "$old_target" || -z "$previous_target" || -z "$old_version" || -z "$target_version" || "$old_target" == "$previous_target" ]]; then
    self_update_operation_finish 1 failed 'previous release is missing or invalid'
    self_update_release_coordination_locks
    if (( json )); then self_update_rollback_json failed 'previous release is missing or invalid'; else printf '%s\n' 'previous release is missing or invalid' >&2; fi
    return 1
  fi
  operation_step_finish prepare succeeded || true
  operation_step_start activate || true
  if ! self_update_confirm "$yes" "$target_version"; then
    operation_step_finish activate skipped || true
    self_update_operation_finish 2 cancelled 'rollback was not confirmed'
    self_update_release_coordination_locks
    if (( json )); then self_update_rollback_json cancelled 'rollback was not confirmed'; else printf '%s\n' 'rollback was not confirmed' >&2; fi
    return 2
  fi
  if ! atomic_symlink "$previous_target" "${SELF_UPDATE_MANAGED_ROOT}/current"; then
    operation_step_finish activate failed || true
    self_update_operation_finish 1 failed 'atomic rollback switch failed'
    self_update_release_coordination_locks
    if (( json )); then self_update_rollback_json failed 'atomic rollback switch failed'; else printf '%s\n' 'atomic rollback switch failed' >&2; fi
    return 1
  fi
  if ! atomic_symlink "$old_target" "${SELF_UPDATE_MANAGED_ROOT}/previous"; then
    if self_update_atomic_restore_current "$SELF_UPDATE_MANAGED_ROOT" "$old_target"; then
      operation_step_finish activate failed || true
      self_update_operation_finish 1 failed 'atomic rollback switch failed'
      self_update_release_coordination_locks
      if (( json )); then self_update_rollback_json failed 'atomic rollback switch failed'; else printf '%s\n' 'atomic rollback switch failed' >&2; fi
      return 1
    fi
    operation_step_finish activate failed || true
    self_update_operation_finish 1 rollback_failed 'rollback changed current but could not restore it after the pointer swap failed'
    self_update_release_coordination_locks
    if (( json )); then self_update_rollback_json rollback_failed 'rollback changed current but could not restore it'; else printf '%s\n' 'rollback changed current but could not restore it' >&2; fi
    return 1
  fi
  operation_step_finish activate succeeded || true
  operation_step_start smoke_check || true
  case "$-" in *e*) had_errexit=1;; esac
  set +e
  self_update_smoke_check "$previous_target"
  smoke_status=$?
  (( had_errexit == 1 )) && set -e || set +e
  if [[ "$smoke_status" -eq 0 ]]; then
    SELF_UPDATE_VERSION="$target_version"
    operation_step_finish smoke_check succeeded || true
    self_update_operation_finish 0 succeeded
    self_update_release_coordination_locks
    if (( json )); then self_update_rollback_json succeeded; else printf 'self-update rolled back to %s\n' "$target_version"; fi
    return 0
  fi
  operation_step_finish smoke_check failed || true
  operation_step_start rollback || true
  if self_update_atomic_restore_current "$SELF_UPDATE_MANAGED_ROOT" "$old_target" \
      && atomic_symlink "$previous_target" "${SELF_UPDATE_MANAGED_ROOT}/previous"; then
    SELF_UPDATE_VERSION="$old_version"
    operation_step_finish rollback succeeded || true
    self_update_operation_finish 1 rolled_back 'rollback target smoke check failed; current was restored'
    self_update_release_coordination_locks
    if (( json )); then self_update_rollback_json rolled_back 'rollback target smoke check failed; current was restored'; else printf '%s\n' 'rollback target smoke check failed; current was restored' >&2; fi
    return 1
  fi
  operation_step_finish rollback failed || true
  self_update_operation_finish 1 rollback_failed 'rollback target smoke check failed and current could not be restored'
  self_update_release_coordination_locks
  if (( json )); then self_update_rollback_json rollback_failed 'rollback target smoke check failed and current could not be restored'; else printf '%s\n' 'rollback target smoke check failed and current could not be restored' >&2; fi
  return 1
}

self_update_main() {
  local json=0 check=0 dry_run=0 rollback=0 list=0 yes=0 channel_override="" arg
  while (($#)); do
    arg="$1"
    case "$arg" in
      --json) json=1; shift ;;
      --check) check=1; shift ;;
      --dry-run) dry_run=1; shift ;;
      --rollback) rollback=1; shift ;;
      --list) list=1; shift ;;
      --yes) yes=1; shift ;;
      --channel) (($# >= 2)) || { printf 'self-update: --channel requires a value\n' >&2; return 2; }; channel_override="$2"; shift 2 ;;
      -h|--help) printf '%s\n' 'Usage: deploy.sh self-update [--check|--dry-run|--rollback|--list] [--json] [--yes] [--channel NAME]' >&2; return 0 ;;
      *) printf 'self-update: unknown option: %s\n' "$arg" >&2; return 2 ;;
    esac
  done
  (( check + dry_run + rollback + list <= 1 )) || {
    printf '%s\n' 'self-update: choose only one of --check, --dry-run, --rollback, or --list' >&2
    return 2
  }
  [[ -z "$channel_override" ]] || DEPLOY_SELF_UPDATE_CHANNEL="$channel_override"
  if (( check )); then
    self_update_check_main "$json"
    return $?
  fi
  if (( dry_run )); then
    self_update_dry_run_main "$json"
    return $?
  fi
  if (( rollback )); then
    self_update_rollback_main "$json" "$yes"
    return $?
  fi
  if (( list )); then
    self_update_list_main "$json"
    return $?
  fi
  self_update_apply_main "$json" "$yes"
}

# ----- lib/app_registry.sh -----

# Registry spec columns: id|name|definition file|impl file|capabilities
# The capabilities column is a comma-separated list; "backup" marks apps whose
# do_backup performs a real backup. Apps without it are skipped by backup-all
# without loading their implementation — the previous grep-the-source probe
# (searching do_backup's body for unsupported_action) was fragile and required
# sourcing every app just to plan a batch.
DEPLOY_APP_SPECS=(
  "newapi|New API|apps/newapi.sh|impl/install_newapi.sh|backup,restore"
  "sub2api|Sub2API|apps/sub2api.sh|impl/install_sub2api.sh|backup,restore"
  "vaultwarden|Vaultwarden|apps/vaultwarden.sh|impl/install_vaultwarden.sh|backup,restore"
  "cyberstrikeai|CyberStrikeAI|apps/cyberstrikeai.sh|impl/install_cyberstrikeai.sh|backup,restore"
  "blog|Hugo Blog|apps/blog.sh|impl/install_hugo_blog.sh|backup,restore"
  "tickflow|TickFlow Stock Panel|apps/tickflow.sh|impl/install_tickflow.sh|backup,restore"
  "cpa-stack|CLIProxyAPI + CPA Manager Plus|apps/cpa_stack.sh|impl/install_cpa_stack.sh|backup,restore"
  "ntfy|ntfy|apps/ntfy.sh|impl/install_ntfy.sh|backup,restore"
  "meilisearch|Meilisearch|apps/meilisearch.sh|impl/install_meilisearch.sh|backup,restore"
  "alist|Alist|apps/alist.sh|impl/install_alist.sh|backup,restore"
  "filebrowser|Filebrowser|apps/filebrowser.sh|impl/install_filebrowser.sh|backup,restore"
  "navidrome|Navidrome|apps/navidrome.sh|impl/install_navidrome.sh|backup,restore"
  "frps|frps|apps/frps.sh|impl/install_frps.sh|backup,restore"
  "gitea|Gitea|apps/gitea.sh|impl/install_gitea.sh|backup,restore"
  "gotify|Gotify|apps/gotify.sh|impl/install_gotify.sh|backup,restore"
  "beszel|Beszel|apps/beszel.sh|impl/install_beszel.sh|backup,restore"
)

DEPLOY_APP_IDS=()
DEPLOY_APP_NAMES=()
DEPLOY_APP_FILES=()
DEPLOY_APP_IMPL_FILES=()
DEPLOY_APP_CAPABILITIES=()

for deploy_app_spec in "${DEPLOY_APP_SPECS[@]}"; do
  IFS='|' read -r deploy_app_id deploy_app_name deploy_app_file deploy_app_impl_file deploy_app_caps <<< "$deploy_app_spec"
  DEPLOY_APP_IDS+=("$deploy_app_id")
  DEPLOY_APP_NAMES+=("$deploy_app_name")
  DEPLOY_APP_FILES+=("$deploy_app_file")
  DEPLOY_APP_IMPL_FILES+=("$deploy_app_impl_file")
  DEPLOY_APP_CAPABILITIES+=("${deploy_app_caps:-}")
done
unset deploy_app_spec deploy_app_id deploy_app_name deploy_app_file deploy_app_impl_file deploy_app_caps

deploy_trim() {
  local value="${1:-}"
  value="${value#"${value%%[![:space:]]*}"}"
  value="${value%"${value##*[![:space:]]}"}"
  printf '%s' "$value"
}

deploy_app_ids() {
  printf '%s\n' "${DEPLOY_APP_IDS[@]}"
}

deploy_app_offset_for() {
  local app_id="$1" offset
  for offset in "${!DEPLOY_APP_IDS[@]}"; do
    if [[ "${DEPLOY_APP_IDS[$offset]}" == "$app_id" ]]; then
      echo "$offset"
      return 0
    fi
  done
  return 1
}

deploy_app_metadata_for() {
  local app_id="$1" field="$2" offset
  offset="$(deploy_app_offset_for "$app_id")" || return 1
  case "$field" in
    file) echo "${DEPLOY_APP_FILES[$offset]}" ;;
    impl_file) echo "${DEPLOY_APP_IMPL_FILES[$offset]}" ;;
    name) echo "${DEPLOY_APP_NAMES[$offset]}" ;;
    capabilities) echo "${DEPLOY_APP_CAPABILITIES[$offset]}" ;;
    *) return 1 ;;
  esac
}

deploy_app_file_for() {
  deploy_app_metadata_for "$1" file
}

deploy_app_impl_file_for() {
  deploy_app_metadata_for "$1" impl_file
}

deploy_app_script_name_for() {
  local app_id="$1"
  case "$app_id" in
    blog) echo "install_hugo_blog.sh" ;;
    *) echo "install_${app_id//-/_}.sh" ;;
  esac
}

deploy_app_bundled_impl_script_name_for() {
  local app_id="$1"
  case "$app_id" in
    blog) echo "install_hugo_blog_impl.sh" ;;
    *) echo "install_${app_id}_impl.sh" ;;
  esac
}

deploy_app_name_for() {
  deploy_app_metadata_for "$1" name
}

# Print 0/1 for whether the app's capabilities list contains the given
# capability (for example "backup" or "restore").
deploy_app_has_capability() {
  local app_id="$1" capability="$2" caps cap
  caps="$(deploy_app_metadata_for "$app_id" capabilities)" || return 1
  case ",${caps}," in
    *,"$capability",*) return 0 ;;
    *) return 1 ;;
  esac
}

deploy_app_index_for() {
  local offset
  offset="$(deploy_app_offset_for "$1")" || return 1
  echo "$((offset + 1))"
}

deploy_app_id_from_selection() {
  local selection index=1 id instance
  selection="$(deploy_trim "${1:-}")"
  case "${selection,,}" in
    q|quit|exit) return 2 ;;
  esac
  # <app>@<instance>: split off the instance name and validate both halves.
  # Prints "<app_id> <instance>" (instance empty when not specified).
  if [[ "$selection" == *@* ]]; then
    id="${selection%%@*}"
    instance="${selection#*@}"
    if ! [[ "$instance" =~ ^[a-z0-9_-]{1,32}$ ]]; then
      return 1
    fi
    for id in "${DEPLOY_APP_IDS[@]}"; do
      if [[ "${id,,}" == "${selection%%@*}" ]]; then
        printf '%s %s\n' "$id" "$instance"
        return 0
      fi
    done
    return 1
  fi
  for id in "${DEPLOY_APP_IDS[@]}"; do
    if [[ "${selection,,}" == "$id" || "$selection" == "$index" ]]; then
      printf '%s\n' "$id"
      return 0
    fi
    index=$((index + 1))
  done
  return 1
}

# ----- lib/manager_args.sh -----

# Shared CLI argument parsing for the central batch commands
# (status-all / doctor-all / backup-all / check-update / update-all).
#
# Every central command used to implement its own --json/--include/--exclude
# (plus command-specific flags) loop, and some accepted flags were silently
# ignored.  This helper centralizes the common subset and rejects unknown
# flags uniformly.
#
# Usage:
#   manager_parse_args <spec> <usage_fn> [args...]
#
# <spec> is a whitespace-separated list of supported flags:
#   --json --short --strict --errors-only --only-installed --no-probe
#   --no-network --dry-run --yes --refresh --continue-on-error --help
#   --include --exclude
# Flags with values (--include/--exclude) consume the next argument or an
# =value form.  Parsed values are exported as MANAGER_ARG_* variables:
#   MANAGER_ARG_JSON              0|1
#   MANAGER_ARG_SHORT             0|1
#   MANAGER_ARG_STRICT            0|1
#   MANAGER_ARG_ERRORS_ONLY       0|1
#   MANAGER_ARG_ONLY_INSTALLED    0|1
#   MANAGER_ARG_NO_PROBE          0|1
#   MANAGER_ARG_NO_NETWORK        0|1
#   MANAGER_ARG_DRY_RUN           0|1
#   MANAGER_ARG_YES               0|1
#   MANAGER_ARG_REFRESH           0|1
#   MANAGER_ARG_CONTINUE_ON_ERROR 0|1
#   MANAGER_ARG_INCLUDE           CSV string ("" when unset)
#   MANAGER_ARG_EXCLUDE           CSV string ("" when unset)
# Returns 0 on success, 2 on a usage error (after calling the usage fn).

manager_parse_args() {
  local spec="$1" usage_fn="$2"
  shift 2
  local arg value
  local -a specs=()
  local f
  for f in $spec; do specs+=("$f"); done
  _manager_arg_supported() {
    local needle="$1"; shift
    local x
    for x in "$@"; do [[ "$x" == "$needle" ]] && return 0; done
    return 1
  }
  MANAGER_ARG_JSON=0
  MANAGER_ARG_SHORT=0
  MANAGER_ARG_STRICT=0
  MANAGER_ARG_ERRORS_ONLY=0
  MANAGER_ARG_ONLY_INSTALLED=0
  MANAGER_ARG_NO_PROBE=0
  MANAGER_ARG_NO_NETWORK=0
  MANAGER_ARG_DRY_RUN=0
  MANAGER_ARG_YES=0
  MANAGER_ARG_REFRESH=0
  MANAGER_ARG_CONTINUE_ON_ERROR=0
  MANAGER_ARG_INCLUDE=""
  MANAGER_ARG_EXCLUDE=""
  while (($#)); do
    arg="$1"; shift
    case "$arg" in
      --json)
        _manager_arg_supported --json "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_JSON=1 ;;
      --short)
        _manager_arg_supported --short "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_SHORT=1 ;;
      --strict)
        _manager_arg_supported --strict "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_STRICT=1 ;;
      --errors-only)
        _manager_arg_supported --errors-only "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_ERRORS_ONLY=1 ;;
      --only-installed)
        _manager_arg_supported --only-installed "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_ONLY_INSTALLED=1 ;;
      --no-probe)
        _manager_arg_supported --no-probe "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_NO_PROBE=1 ;;
      --no-network)
        _manager_arg_supported --no-network "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_NO_NETWORK=1 ;;
      --dry-run)
        _manager_arg_supported --dry-run "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_DRY_RUN=1 ;;
      --yes)
        _manager_arg_supported --yes "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_YES=1 ;;
      --refresh)
        _manager_arg_supported --refresh "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_REFRESH=1 ;;
      --continue-on-error)
        _manager_arg_supported --continue-on-error "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_CONTINUE_ON_ERROR=1 ;;
      --include)
        _manager_arg_supported --include "${specs[@]}" || { "$usage_fn"; return 2; }
        (($#)) || { "$usage_fn"; return 2; }
        value="$1"; shift; MANAGER_ARG_INCLUDE="$value" ;;
      --exclude)
        _manager_arg_supported --exclude "${specs[@]}" || { "$usage_fn"; return 2; }
        (($#)) || { "$usage_fn"; return 2; }
        value="$1"; shift; MANAGER_ARG_EXCLUDE="$value" ;;
      --include=*)
        _manager_arg_supported --include "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_INCLUDE="${arg#*=}" ;;
      --exclude=*)
        _manager_arg_supported --exclude "${specs[@]}" || { "$usage_fn"; return 2; }
        MANAGER_ARG_EXCLUDE="${arg#*=}" ;;
      --help|-h)
        _manager_arg_supported --help "${specs[@]}" || { "$usage_fn"; return 2; }
        "$usage_fn"; return 0 ;;
      *)
        "$usage_fn"; return 2 ;;
    esac
  done
  return 0
}

# ----- lib/notify.sh -----

# Global notification integration: ntfy / Gotify push backends with a
# fail-open contract — notification failures are logged as warnings and can
# never block the operation that triggered them.
#
# Configuration lives in /etc/deploy-notify.conf (root:600, same key=value
# format and trust gate as app configs):
#   NOTIFY_ENABLED=true|false
#   NOTIFY_BACKEND=ntfy|gotify
#   NOTIFY_URL=            service origin, e.g. https://ntfy.example.com
#   NOTIFY_TOPIC=          ntfy topic (ntfy only)
#   NOTIFY_TOKEN=          access token sent as Authorization: Bearer
#   NOTIFY_USERNAME=       gotify basic-auth username (gotify only)
#   NOTIFY_PASSWORD=       gotify basic-auth password (gotify only)

NOTIFY_CONF_FILE="${NOTIFY_CONF_FILE:-/etc/deploy-notify.conf}"

notify_load_config() {
  local conf_file="$NOTIFY_CONF_FILE"
  NOTIFY_ENABLED=false NOTIFY_BACKEND="" NOTIFY_URL="" NOTIFY_TOPIC=""
  NOTIFY_TOKEN="" NOTIFY_USERNAME="" NOTIFY_PASSWORD=""
  [[ -f "$conf_file" ]] || return 0
  # Same trust gate as app configs: root-owned, mode 600/400, or ignored.
  if ! app_conf_trusted_value "$conf_file" "NOTIFY_ENABLED" >/dev/null 2>&1; then
    return 1
  fi
  local line key value
  while IFS= read -r line; do
    [[ "$line" =~ ^[A-Z_]+= ]] || continue
    key="${line%%=*}"
    value="${line#*=}"
    value="${value%\"}"
    value="${value#\"}"
    case "$key" in
      NOTIFY_ENABLED|NOTIFY_BACKEND|NOTIFY_URL|NOTIFY_TOPIC|NOTIFY_TOKEN|NOTIFY_USERNAME|NOTIFY_PASSWORD)
        printf -v "$key" '%s' "$value"
        ;;
    esac
  done < "$conf_file"
}

# Redact anything that looks like a credential from message bodies before
# they leave the machine. Reuses the operation-log redaction patterns.
notify_redact() {
  local text="$1"
  printf '%s' "$text" | sed -E \
    -e 's/([[:alnum:]_.-]*(TOKEN|PASSWORD|SECRET|API_KEY|PRIVATE_KEY|KEY)[[:alnum:]_.-]*[[:space:]]*=[[:space:]]*)[^[:space:]]+/\1[REDACTED]/Ig' \
    -e 's#(Authorization:[[:space:]]*Bearer[[:space:]]+)[^[:space:]]+#\1[REDACTED]#Ig' \
    -e 's#(https?://[^:/[:space:]]+):[^@/[:space:]]+@#\1:[REDACTED]@#g'
}

# Send one notification. Never fails the caller: every error path warns to
# stderr (or silently no-ops when notifications are disabled/unconfigured)
# and returns 0 unless explicitly asked to report failure via NOTIFY_STRICT.
notify_send() {
  local title="$1" body="${2:-}"
  notify_load_config || { warn "$(t notify.warn.untrusted_config)"; return "${NOTIFY_STRICT:-0}"; }
  [[ "${NOTIFY_ENABLED,,}" == true ]] || {
    [[ "${NOTIFY_STRICT:-0}" == 1 ]] && warn "$(t notify.warn.disabled)"
    return "${NOTIFY_STRICT:-0}"
  }
  case "${NOTIFY_BACKEND,,}" in
    ntfy|gotify) ;;
    *) warn "$(t notify.warn.no_backend)"; return "${NOTIFY_STRICT:-0}" ;;
  esac
  [[ -n "$NOTIFY_URL" ]] || { warn "$(t notify.warn.no_url)"; return "${NOTIFY_STRICT:-0}"; }
  if ! command -v curl >/dev/null 2>&1; then
    warn "$(t notify.warn.curl_missing)"
    return "${NOTIFY_STRICT:-0}"
  fi
  title="$(notify_redact "$title")"
  body="$(notify_redact "$body")"
  local args=(curl --max-time 10 -sS -o /dev/null -w '%{http_code}')
  case "${NOTIFY_BACKEND,,}" in
    ntfy)
      if [[ -n "$NOTIFY_TOKEN" ]]; then
        args+=(-H "Authorization: Bearer ${NOTIFY_TOKEN}")
      fi
      args+=(-H "Title: ${title}" -H "Tags: warning" --data-binary "$body" \
        "${NOTIFY_URL%/}/${NOTIFY_TOPIC:-deploy-scripts}")
      ;;
    gotify)
      if [[ -n "$NOTIFY_TOKEN" ]]; then
        args+=(-H "Authorization: Bearer ${NOTIFY_TOKEN}")
      elif [[ -n "$NOTIFY_USERNAME" && -n "$NOTIFY_PASSWORD" ]]; then
        args+=(-u "${NOTIFY_USERNAME}:${NOTIFY_PASSWORD}")
      fi
      local gotify_payload
      gotify_payload="{\"title\":$(app_json_string "$title"),\"message\":$(app_json_string "$body"),\"priority\":5}"
      args+=(-H "Content-Type: application/json" \
        --data "$gotify_payload" \
        "${NOTIFY_URL%/}/message")
      ;;
  esac
  local http_code
  http_code="$("${args[@]}" 2>/dev/null)" || http_code="000"
  case "$http_code" in
    2*) info "$(t notify.info.sent)"; return 0 ;;
    *)
      warn "$(t notify.warn.send_failed "$http_code")"
      [[ "${NOTIFY_STRICT:-0}" == 1 ]] && return 1
      return 0
      ;;
  esac
}

# Interactive/CLI configuration for the notification backends. Values are
# merged over the existing config so each flag can be set independently;
# --disable flips NOTIFY_ENABLED while keeping the rest, and --test sends a
# harmless probe message. The file is written root:600 via atomic_write_file.
notify_config_main() {
  require_root "notify-config"
  local enable="" backend="" url="" topic="" token="" test_only=false clear_all=false
  while (($#)); do
    case "$1" in
      --enable) enable=true; shift ;;
      --disable) enable=false; shift ;;
      --backend) backend="${2:-}"; shift 2 ;;
      --url) url="${2:-}"; shift 2 ;;
      --topic) topic="${2:-}"; shift 2 ;;
      --token) token="${2:-}"; shift 2 ;;
      --test) test_only=true; shift ;;
      --clear) clear_all=true; shift ;;
      -h|--help)
        t notify.usage "$0"
        return 0
        ;;
      *)
        t notify.usage "$0"
        return 2
        ;;
    esac
  done
  if [[ "$clear_all" == "true" ]]; then
    rm -f "$NOTIFY_CONF_FILE"
    success "$(t notify.config.cleared "$NOTIFY_CONF_FILE")"
    return 0
  fi
  # Load current values as the merge base.
  local conf_file="$NOTIFY_CONF_FILE"
  NOTIFY_ENABLED=false NOTIFY_BACKEND="" NOTIFY_URL="" NOTIFY_TOPIC=""
  NOTIFY_TOKEN="" NOTIFY_USERNAME="" NOTIFY_PASSWORD=""
  if [[ -f "$conf_file" ]]; then
    local line key value
    while IFS= read -r line; do
      [[ "$line" =~ ^[A-Z_]+= ]] || continue
      key="${line%%=*}"
      value="${line#*=}"
      value="${value%\"}"
      value="${value#\"}"
      case "$key" in
        NOTIFY_ENABLED|NOTIFY_BACKEND|NOTIFY_URL|NOTIFY_TOPIC|NOTIFY_TOKEN|NOTIFY_USERNAME|NOTIFY_PASSWORD)
          printf -v "$key" '%s' "$value"
          ;;
      esac
    done < "$conf_file"
  fi
  [[ -n "$backend" ]] || true
  case "${backend,,}" in
    ""|ntfy|gotify) : ;;
    *) error "$(t error.url_invalid NOTIFY_BACKEND "$backend")" ;;
  esac
  [[ -n "$backend" ]] && NOTIFY_BACKEND="${backend,,}"
  [[ -n "$url" ]] && NOTIFY_URL="$url"
  [[ -n "$topic" ]] && NOTIFY_TOPIC="$topic"
  [[ -n "$token" ]] && { NOTIFY_TOKEN="$token"; NOTIFY_USERNAME=""; NOTIFY_PASSWORD=""; }
  [[ -n "$enable" ]] && NOTIFY_ENABLED="$( [[ "${enable}" == true ]] && echo true || echo false )"
  if [[ "$test_only" == "true" ]]; then
    # Probe with the merged values, not whatever the disk still holds:
    # notify_send reloads the config file internally, so stage the merged
    # values into a private probe file and point notify_send at it. A test
    # without an enabled backend or a reachable URL must fail loudly instead
    # of claiming success while silently skipping the send.
    local probe_file probe_status
    probe_file="$(mktemp "${TMPDIR:-/tmp}/deploy-notify-probe.XXXXXX")" || error "$(t error.tmpdir)"
    if ! atomic_write_file "$probe_file" 600 <<PROBE
NOTIFY_ENABLED="${NOTIFY_ENABLED}"
NOTIFY_BACKEND="${NOTIFY_BACKEND}"
NOTIFY_URL="${NOTIFY_URL}"
NOTIFY_TOPIC="${NOTIFY_TOPIC}"
NOTIFY_TOKEN="${NOTIFY_TOKEN}"
NOTIFY_USERNAME="${NOTIFY_USERNAME}"
NOTIFY_PASSWORD="${NOTIFY_PASSWORD}"
PROBE
    then
      rm -f "$probe_file"
      error "$(t error.config_write "$probe_file")"
    fi
    NOTIFY_STRICT=1 NOTIFY_CONF_FILE="$probe_file" notify_send \
      "deploy-scripts notification test" \
      "If you can read this, notifications work. No secrets are included."
    probe_status=$?
    rm -f "$probe_file"
    if [[ "$probe_status" -ne 0 ]]; then
      error "$(t notify.test.failed)"
    fi
    # The probe succeeded with the merged values, so persist them so the
    # tested configuration is exactly what later runs will use.
    if ! atomic_write_file "$conf_file" 600 <<CONF
NOTIFY_ENABLED="${NOTIFY_ENABLED}"
NOTIFY_BACKEND="${NOTIFY_BACKEND}"
NOTIFY_URL="${NOTIFY_URL}"
NOTIFY_TOPIC="${NOTIFY_TOPIC}"
NOTIFY_TOKEN="${NOTIFY_TOKEN}"
NOTIFY_USERNAME="${NOTIFY_USERNAME}"
NOTIFY_PASSWORD="${NOTIFY_PASSWORD}"
CONF
    then
      error "$(t error.config_write "$conf_file")"
    fi
    success "$(t notify.test.sent_ok)"
    return 0
  fi
  if ! atomic_write_file "$conf_file" 600 <<CONF
NOTIFY_ENABLED="${NOTIFY_ENABLED}"
NOTIFY_BACKEND="${NOTIFY_BACKEND}"
NOTIFY_URL="${NOTIFY_URL}"
NOTIFY_TOPIC="${NOTIFY_TOPIC}"
NOTIFY_TOKEN="${NOTIFY_TOKEN}"
NOTIFY_USERNAME="${NOTIFY_USERNAME}"
NOTIFY_PASSWORD="${NOTIFY_PASSWORD}"
CONF
  then
    error "$(t error.config_write "$conf_file")"
  fi
  success "$(t notify.config.saved "$conf_file")"
}

# ----- lib/schedule.sh -----

# Scheduled update/check runs: `deploy.sh schedule` writes a systemd
# service+timer pair (or a /etc/cron.d entry on non-systemd systems) that
# invokes the runner script; `deploy.sh unschedule` removes both. The runner
# takes the same manager lock as interactive batches, so scheduled and manual
# runs can never overlap, and reports its result through notify_send.
#
# Config lives in /etc/deploy-schedule.conf (root:600):
#   SCHEDULE_ENABLED=true|false
#   SCHEDULE_MODE=update-all|check-only
#   SCHEDULE_ON_CALENDAR=  systemd OnCalendar spec (default daily 04:30)
#   SCHEDULE_INCLUDE=      optional --include list passed to the batch command

SCHEDULE_CONF_FILE="${SCHEDULE_CONF_FILE:-/etc/deploy-schedule.conf}"
DEPLOY_SCHEDULE_SERVICE="${DEPLOY_SCHEDULE_SERVICE:-deploy-scripts-batch}"
DEPLOY_SCHEDULE_CRON_FILE="${DEPLOY_SCHEDULE_CRON_FILE:-/etc/cron.d/deploy-scripts-batch}"
DEPLOY_SCHEDULE_RUNNER="${DEPLOY_SCHEDULE_RUNNER:-/usr/local/bin/deploy-scripts-batch-runner}"

# Retry knob for scheduled batches: how many times a failed run is retried
# (default 0 = fire once), and the base backoff in seconds between attempts
# (doubled each retry, capped at 900).
SCHEDULE_RETRIES="${SCHEDULE_RETRIES:-0}"
SCHEDULE_RETRY_BACKOFF="${SCHEDULE_RETRY_BACKOFF:-300}"

schedule_load_config() {
  local conf_file="$SCHEDULE_CONF_FILE"
  SCHEDULE_ENABLED=false SCHEDULE_MODE="update-all" SCHEDULE_ON_CALENDAR="" SCHEDULE_INCLUDE=""
  [[ -f "$conf_file" ]] || return 0
  # Same trust gate as app and notification configs: root-owned, mode
  # 600/400, or the file is ignored entirely. A world-writable schedule
  # file could otherwise inject --include tokens into the batch command.
  # Unlike notify (which already warns), the runner call sites surface the
  # untrusted state explicitly so an attacker-writable schedule config can
  # never silently disable or alter a batch run.
  if ! app_conf_trusted_value "$conf_file" "SCHEDULE_ENABLED" >/dev/null 2>&1; then
    echo "schedule: ignoring untrusted schedule config: $conf_file" >&2
    return 1
  fi
  local line key value
  while IFS= read -r line; do
    [[ "$line" =~ ^[A-Z_]+= ]] || continue
    key="${line%%=*}"
    value="${line#*=}"
    value="${value%\"}"
    value="${value#\"}"
    case "$key" in
      SCHEDULE_ENABLED|SCHEDULE_MODE|SCHEDULE_ON_CALENDAR|SCHEDULE_INCLUDE|SCHEDULE_RETRIES|SCHEDULE_RETRY_BACKOFF)
        printf -v "$key" '%s' "$value"
        ;;
    esac
  done < "$conf_file"
}

# The script invoked by systemd/cron. Takes the manager lock (fd8, shared
# with interactive batches), runs the configured batch, and lets the batch's
# own notification report the outcome. DEPLOY_NOTIFY_SUPPRESS is NOT set —
# scheduled runs are exactly when notifications matter most.
schedule_write_runner() {
  local runner="$DEPLOY_SCHEDULE_RUNNER"
  local root_dir_literal
  printf -v root_dir_literal '%q' "$DEPLOY_ROOT_DIR"
  if ! atomic_write_file "$runner" 750 <<RUNNER
#!/bin/bash
# Auto-generated by deploy.sh schedule. Do not edit manually.
set -euo pipefail
umask 077
exec bash ${root_dir_literal}/deploy.sh schedule-run
RUNNER
  then
    return 1
  fi
}

# Internal action executed by the runner. Reuses the manager lock so a
# concurrent interactive update-all/backup-all makes this run skip cleanly.
# Failed batches are retried SCHEDULE_RETRIES times with exponential backoff
# (base SCHEDULE_RETRY_BACKOFF, doubled per attempt, capped at 900s) before
# the run finally reports failure through the notification path.
schedule_run_main() {
  require_root "schedule-run"
  schedule_load_config || true
  [[ "${SCHEDULE_ENABLED,,}" == true ]] || { echo "scheduled batch disabled; nothing to do." >&2; return 0; }
  local include_args=()
  if [[ -n "${SCHEDULE_INCLUDE:-}" ]]; then
    read -r -a include_args <<< "--include $SCHEDULE_INCLUDE"
  fi
  local mode="${SCHEDULE_MODE:-update-all}" batch_cmd attempt=0 max_attempts backoff status=0
  case "$mode" in
    check-only) batch_cmd="check-update" ;;
    update-all) batch_cmd="update-all" ;;
    *)
      echo "unknown schedule mode: $SCHEDULE_MODE" >&2
      return 2
      ;;
  esac
  [[ "$SCHEDULE_RETRIES" =~ ^[0-9]+$ ]] || SCHEDULE_RETRIES=0
  [[ "$SCHEDULE_RETRY_BACKOFF" =~ ^[0-9]+$ ]] || SCHEDULE_RETRY_BACKOFF=300
  backoff="$SCHEDULE_RETRY_BACKOFF"
  max_attempts=$(( SCHEDULE_RETRIES + 1 ))
  while (( attempt < max_attempts )); do
    if bash "$DEPLOY_ROOT_DIR/deploy.sh" "$batch_cmd" \
        ${include_args[@]+"${include_args[@]}"}; then
      return 0
    fi
    status=$?
    attempt=$((attempt + 1))
    if (( attempt < max_attempts )); then
      warn "$(t schedule.warn.retry "$status" "$attempt" "$max_attempts")"
      sleep "$backoff"
      backoff=$(( backoff * 2 ))
      (( backoff > 900 )) && backoff=900
    fi
  done
  return "$status"
}

# Validate a schedule specification before it reaches the unit files. On
# systemd systems the authoritative check is `systemd-analyze calendar`;
# when that tool is unavailable (or the spec is a plain HH:MM used by the
# cron fallback) we fall back to a conservative shape check so a typo fails
# loudly at `schedule` time instead of silently producing a never-firing
# timer.
schedule_validate_calendar() {
  local calendar="$1"
  if [[ "$calendar" =~ ^([0-9]+):([0-9]+)$ ]]; then
    local hour minute
    hour="$((10#${BASH_REMATCH[1]}))"
    minute="$((10#${BASH_REMATCH[2]}))"
    [[ "$hour" -le 23 && "$minute" -le 59 ]] || {
      echo "Invalid schedule specification: $calendar" >&2
      return 2
    }
    return 0
  fi
  if command -v systemd-analyze >/dev/null 2>&1; then
    if systemd-analyze calendar "$calendar" >/dev/null 2>&1; then
      return 0
    fi
    echo "Invalid OnCalendar specification: $calendar" >&2
    return 2
  fi
  # Conservative shape check without systemd-analyze: allow word-ish and
  # *-* date/time patterns, but reject whitespace-padded or obviously broken
  # values that would otherwise fail only when the timer is loaded.
  if [[ "$calendar" =~ ^[^[:space:]]+(.*[^[:space:]])?$ ]] \
      && [[ "$calendar" == *"/"* || "$calendar" == *:* || "$calendar" == *"-"* || "$calendar" == "*"* ]]; then
    return 0
  fi
  echo "Invalid schedule specification: $calendar" >&2
  return 2
}

# Write or refresh the scheduling units. Prefers systemd timers; falls back
# to /etc/cron.d where systemd is unavailable.
schedule_apply() {
  local calendar="$1"
  schedule_validate_calendar "$calendar" || return 2
  if command -v systemctl >/dev/null 2>&1 && systemctl is-system-running >/dev/null 2>&1; then
    local service_file="/etc/systemd/system/${DEPLOY_SCHEDULE_SERVICE}.service"
    local timer_file="/etc/systemd/system/${DEPLOY_SCHEDULE_SERVICE}.timer"
    atomic_write_file "$service_file" 644 <<SERVICE \
      || return 1
[Unit]
Description=deploy-scripts scheduled batch (update-all / check-update)
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=${DEPLOY_SCHEDULE_RUNNER}
SERVICE
    atomic_write_file "$timer_file" 644 <<TIMER || return 1
[Unit]
Description=Run deploy-scripts scheduled batch

[Timer]
OnCalendar=${calendar}
Persistent=true

[Install]
WantedBy=timers.target
TIMER
    systemctl daemon-reload || return 1
    systemctl enable --now "${DEPLOY_SCHEDULE_SERVICE}.timer" >/dev/null 2>&1 || return 1
  else
    local cron_spec="${calendar}"
    # Convert the common daily "HH:MM" systemd form to cron; anything more
    # exotic must already be a valid 5-field crontab expression.
    if [[ "$calendar" =~ ^([0-9]+):([0-9]+)$ ]]; then
      cron_spec="$((10#${BASH_REMATCH[2]})) $((10#${BASH_REMATCH[1]})) * * *"
    fi
    if ! [[ "$cron_spec" =~ ^[0-9*,-/]+[[:space:]]+[0-9*,-/]+[[:space:]]+[0-9*,-/]+[[:space:]]+[0-9*,-/]+[[:space:]]+[0-9*,-/]+$ ]]; then
      echo "Invalid schedule specification: $calendar" >&2
      return 2
    fi
    atomic_write_file "$DEPLOY_SCHEDULE_CRON_FILE" 644 <<CRON || return 1
# Auto-generated by deploy.sh schedule. Do not edit manually.
${cron_spec} root ${DEPLOY_SCHEDULE_RUNNER}
CRON
    chmod 644 "$DEPLOY_SCHEDULE_CRON_FILE" 2>/dev/null || true
  fi
}

schedule_remove_units() {
  if command -v systemctl >/dev/null 2>&1; then
    systemctl disable --now "${DEPLOY_SCHEDULE_SERVICE}.timer" >/dev/null 2>&1 || true
    rm -f "/etc/systemd/system/${DEPLOY_SCHEDULE_SERVICE}.service" \
          "/etc/systemd/system/${DEPLOY_SCHEDULE_SERVICE}.timer"
    systemctl daemon-reload >/dev/null 2>&1 || true
  fi
  rm -f "$DEPLOY_SCHEDULE_CRON_FILE"
}

schedule_main() {
  require_root "schedule"
  # Default subcommand is the config branch: `deploy.sh schedule` (with no
  # further argument) enables/edits the schedule. `deploy.sh schedule status`
  # reaches the status branch by passing "status" as the first argument.
  local subcommand="${1:-schedule}"
  shift || true
  case "${subcommand,,}" in
    -h|--help)
      t schedule.usage "$0"
      return 0
      ;;
    run|schedule-run)
      schedule_run_main "$@"
      return $?
      ;;
    status)
      schedule_load_config || true
      echo "enabled=${SCHEDULE_ENABLED} mode=${SCHEDULE_MODE:-update-all} calendar=${SCHEDULE_ON_CALENDAR:-<default>} retries=${SCHEDULE_RETRIES:-0} backoff=${SCHEDULE_RETRY_BACKOFF:-300} include=${SCHEDULE_INCLUDE:-<all>}"
      if command -v systemctl >/dev/null 2>&1 \
          && systemctl list-timers --all 2>/dev/null | grep -q "$DEPLOY_SCHEDULE_SERVICE"; then
        echo "systemd timer active"
      elif [[ -f "$DEPLOY_SCHEDULE_CRON_FILE" ]]; then
        echo "cron entry present"
      else
        echo "no schedule installed"
      fi
      ;;
    unschedule)
      schedule_remove_units
      rm -f "$SCHEDULE_CONF_FILE"
      success "$(t schedule.info.removed)"
      ;;
    schedule|enable|disable|*)
      local enable="" mode="" calendar="" include="" retries="" backoff=""
      [[ "${subcommand,,}" == "schedule" ]] && enable=true
      while (($#)); do
        case "$1" in
          --enable) enable=true; shift ;;
          --disable) enable=false; shift ;;
          --mode) mode="${2:-}"; shift 2 ;;
          --at) calendar="${2:-}"; shift 2 ;;
          --include) include="${2:-}"; shift 2 ;;
          --retries) retries="${2:-}"; shift 2 ;;
          --backoff) backoff="${2:-}"; shift 2 ;;
          *)
            t schedule.usage "$0"
            return 2
            ;;
        esac
      done
      schedule_load_config || true
      case "${mode,,}" in
        ""|update-all|check-only) : ;;
        *) error "$(t common.invalid_choice "$mode")" ;;
      esac
      [[ -n "$mode" ]] && SCHEDULE_MODE="${mode,,}"
      [[ -n "$calendar" ]] && SCHEDULE_ON_CALENDAR="$calendar"
      [[ -n "$include" ]] && SCHEDULE_INCLUDE="$include"
      if [[ -n "${retries:-}" ]]; then
        [[ "$retries" =~ ^[0-9]+$ ]] || error "$(t common.invalid_choice "$retries")"
        SCHEDULE_RETRIES="$retries"
      fi
      if [[ -n "${backoff:-}" ]]; then
        [[ "$backoff" =~ ^[0-9]+$ ]] || error "$(t common.invalid_choice "$backoff")"
        SCHEDULE_RETRY_BACKOFF="$backoff"
      fi
      [[ -n "$enable" ]] && SCHEDULE_ENABLED="$( [[ "$enable" == true ]] && echo true || echo false )"
      # Validate an explicit calendar before persisting it, so a typo can
      # never leave a broken value in the config file.
      if [[ -n "${SCHEDULE_ON_CALENDAR:-}" ]]; then
        schedule_validate_calendar "$SCHEDULE_ON_CALENDAR" || return 2
      fi
      if ! atomic_write_file "$SCHEDULE_CONF_FILE" 600 <<CONF
SCHEDULE_ENABLED="${SCHEDULE_ENABLED}"
SCHEDULE_MODE="${SCHEDULE_MODE}"
SCHEDULE_ON_CALENDAR="${SCHEDULE_ON_CALENDAR}"
SCHEDULE_INCLUDE="${SCHEDULE_INCLUDE}"
SCHEDULE_RETRIES="${SCHEDULE_RETRIES}"
SCHEDULE_RETRY_BACKOFF="${SCHEDULE_RETRY_BACKOFF}"
CONF
      then
        error "$(t error.config_write "$SCHEDULE_CONF_FILE")"
      fi
      if [[ "${SCHEDULE_ENABLED,,}" == true ]]; then
        schedule_write_runner || error "$(t error.config_write "$DEPLOY_SCHEDULE_RUNNER")"
        # The default calendar must be representable on both backends: the
        # systemd weekday form Mon..Fri is meaningless in the /etc/cron.d
        # fallback, which only converts plain HH:MM. Default to a plain
        # HH:MM for check-only (09:00 daily) so a non-systemd host gets a
        # working schedule instead of a rejection at apply time.
        schedule_apply "${SCHEDULE_ON_CALENDAR:-$( [[ "${SCHEDULE_MODE}" == check-only ]] && echo '09:00' || echo '04:30' )}" \
          || return 1
      else
        schedule_remove_units
      fi
      success "$(t schedule.info.saved)"
      ;;
  esac
}

# ----- lib/migrate.sh -----

# Machine migration: `deploy.sh export` bundles every app deployment config,
# the notification/schedule configs, and a backup manifest inventory into a
# single sha256-stamped tarball; `deploy.sh import` verifies and unpacks it
# on the new machine. App binaries/data themselves are NOT included — they
# are recovered on the new host via each app's restore action against
# replicated backups, which keeps the export small and secret-surface low.
#
# Layout inside <output>.tar.gz:
#   manifest.json                     single-line inventory (sha256 stamped)
#   etc/deploy-notify.conf
#   etc/deploy-schedule.conf          (optional, when present)
#   etc/<app>-deploy.conf             one per installed app
#   backups-inventory.json            latest backup + integrity per app

MIGRATE_EXPORT_DIR="${MIGRATE_EXPORT_DIR:-/etc}"

migrate_conf_files() {
  local f
  for f in "$MIGRATE_EXPORT_DIR"/*-deploy.conf; do
    [[ -f "$f" ]] && printf '%s\n' "$f"
  done
}

# Build the staged tree under a mktemp dir and print its path. Fails when
# nothing exportable exists rather than producing an empty archive.
migrate_stage_tree() {
  local stage="$1"
  local staged_any=false f app_id conf_name
  mkdir -p "$stage/etc"
  if [[ -f "$NOTIFY_CONF_FILE" ]]; then
    cp "$NOTIFY_CONF_FILE" "$stage/etc/deploy-notify.conf"
    staged_any=true
  fi
  if [[ -f "$SCHEDULE_CONF_FILE" ]]; then
    cp "$SCHEDULE_CONF_FILE" "$stage/etc/deploy-schedule.conf"
    staged_any=true
  fi
  for f in $(migrate_conf_files); do
    conf_name="$(basename "$f")"
    cp "$f" "$stage/etc/$conf_name"
    staged_any=true
  done
  [[ "$staged_any" == "true" ]] || return 1
}

# Single-line JSON: per-app latest archive name + integrity verdict, so the
# new machine knows which backups to replicate before restoring.
migrate_backups_inventory() {
  local stage="$1"
  local out first=1 app_id impl_file backup_dir_var backup_dir glob record
  out="{\"schema_version\":1,\"apps\":["
  for app_id in "${DEPLOY_APP_IDS[@]}"; do
    impl_file="$(deploy_app_impl_file_for "$app_id")"
    [[ -f "$impl_file" ]] || continue
    record="$("${BASH_BIN:-bash}" -c '
      source lib/core.sh 2>/dev/null
      APP_ID="'"$app_id"'"
      source "'"$(pwd)/$impl_file"'" >/dev/null 2>&1 || exit 0
      app_load_config >/dev/null 2>&1 || true
      dir=""
      for candidate in BACKUP_DIR VW_BACKUP_DIR CPA_STACK_BACKUP_DIR; do
        v="${!candidate:-}"
        [[ -n "$v" ]] && { dir="$v"; break; }
      done
      [[ -n "$dir" && -d "$dir" ]] || exit 0
      case '"$app_id"' in
        blog) glob="blog_*.tar.gz" ;;
        tickflow) glob="tickflow-data-*.tar.gz" ;;
        cpa-stack) glob="cpa-stack-*.tar.gz" ;;
        cyberstrikeai) glob="cyberstrike-ai_*.tar.gz" ;;
        vaultwarden) glob="vaultwarden_*.tar.gz" ;;
        newapi) glob="new-api_*.tar.gz" ;;
        sub2api) glob="sub2api_*.tar.gz sub2api_db_*.sql.gz" ;;
        *) glob="${APP_ID}_*.tar.gz" ;;
      esac
      backup_verify_latest_json "$dir" $glob
    ' 2>/dev/null)" || record=""
    [[ -n "$record" ]] || continue
    (( first )) || out+=","
    first=0
    out+="{\"app\":$(app_json_string "$app_id"),\"latest\":$record}"
  done
  out+="]}"
  printf '%s' "$out" > "${stage}/backups-inventory.json"
}

migrate_main() {
  require_root "migrate"
  local subcommand="${1:-}"
  shift || true
  case "${subcommand,,}" in
    export)
      local output="" redact=false
      while (($#)); do
        case "$1" in
          --output) output="${2:-}"; shift 2 ;;
          --redact) redact=true; shift ;;
          *) t migrate.usage "$0"; return 2 ;;
        esac
      done
      [[ -n "$output" ]] || output="/root/deploy-migration-$(date +%Y%m%d%H%M%S).tar.gz"
      local stage
      stage="$(mktemp -d "${output}.stage.XXXXXX")"
      if ! migrate_stage_tree "$stage"; then
        rm -rf "$stage"
        error "$(t migrate.error.nothing_to_export)"
      fi
      migrate_backups_inventory "$stage"
      # Redacted variant is an additional human-readable reference copy of
      # every conf with secret values masked; the real values still ship in
      # the plain files so import remains functional.
      if [[ "$redact" == "true" ]]; then
        local rf rf_out
        mkdir -p "$stage/redacted-reference"
        for rf in "$stage"/etc/*.conf; do
          rf_out="$stage/redacted-reference/$(basename "$rf").redacted.txt"
          sed -E 's/^((TOKEN|PASSWORD|SECRET|API_KEY|PRIVATE_KEY)[A-Za-z_]*=)".*"/\1"[REDACTED]"/I' \
            "$rf" > "$rf_out"
        done
      fi
      # Stamp the archive itself after creation.
      if ! tar -czf "$output" -C "$stage" . >&2; then
        rm -rf "$stage"
        error "$(t error.config_write "$output")"
      fi
      chmod 600 "$output" 2>/dev/null || true
      backup_write_sha256 "$output" >/dev/null || true
      rm -rf "$stage"
      success "$(t migrate.info.exported "$output")"
      info "$(t migrate.info.next_steps)"
      ;;
    import)
      local input=""
      while (($#)); do
        case "$1" in
          --input) input="${2:-}"; shift 2 ;;
          *) t migrate.usage "$0"; return 2 ;;
        esac
      done
      [[ -n "$input" && -f "$input" ]] || error "$(t migrate.error.archive_missing "${input:-none}")"
      # Integrity first: refuse a damaged bundle before touching /etc.
      if [[ -f "${input}.sha256" ]]; then
        backup_verify_archive "$input" || error "$(t backup.verify.failed "$(basename "$input")")"
      fi
      # Member safety: the sha256 sidecar proves the bundle is untampered,
      # but a compromised export machine could have produced a bundle with
      # traversal members. Reject absolute paths, `..`, and backslashes
      # before any byte lands on disk.
      if ! tar -tzf "$input" 2>/dev/null | awk '
          /^\// || /\.\./ || /\\/ {
            print "unsafe archive member: " $0 > "/dev/stderr"
            exit 1
          }'; then
        error "$(t backup.restore.invalid_archive "$(basename "$input")")"
      fi
      local stage
      stage="$(mktemp -d "${input}.import.XXXXXX")"
      if ! tar -xzf "$input" -C "$stage" >&2; then
        rm -rf "$stage"
        error "$(t backup.restore.invalid_archive "$(basename "$input")")"
      fi
      local f target installed=0
      for f in "$stage"/etc/*.conf; do
        [[ -f "$f" ]] || continue
        target="$MIGRATE_EXPORT_DIR/$(basename "$f")"
        atomic_copy_file "$f" "$target" 600 root:root || {
          rm -rf "$stage"
          error "$(t error.config_write "$target")"
        }
        installed=$((installed + 1))
      done
      rm -rf "$stage"
      success "$(t migrate.info.imported "$installed")"
      info "$(t migrate.info.manual_steps)"
      ;;
    *)
      t migrate.usage "$0"
      return 2
      ;;
  esac
}

# ----- lib/fleet.sh -----

# Fleet / multi-machine management: run status-all / update-all / backup-all
# across a host inventory over SSH with per-host timeouts, bounded concurrency
# and failure isolation, then merge the per-host JSON results. SSH credentials
# are never written to logs: hosts connect through the local SSH agent / keys
# only, and no password/token values are accepted in the inventory.
#
# Inventory format (/etc/deploy-hosts.conf, root:600, one host per line):
#   alias|user@host[:port]
# Blank lines and # comments are ignored; alias must be a simple token.

FLEET_HOSTS_FILE="${FLEET_HOSTS_FILE:-/etc/deploy-hosts.conf}"
FLEET_CONCURRENCY="${FLEET_CONCURRENCY:-4}"
FLEET_TIMEOUT="${FLEET_TIMEOUT:-120}"
# Remote directory holding deploy.sh on fleet hosts. Override per fleet run
# (FLEET_REMOTE_DIR=/srv/deploy bash deploy.sh fleet status-all) or in the
# environment; must be an absolute path with no spaces.
FLEET_REMOTE_DIR="${FLEET_REMOTE_DIR:-/opt/deploy-scripts}"
FLEET_SSH_OPTS=(-o BatchMode=yes -o ConnectTimeout=15 -o StrictHostKeyChecking=accept-new)

fleet_load_hosts() {
  FLEET_HOSTS=()
  local line alias target
  [[ -f "$FLEET_HOSTS_FILE" ]] || return 0
  # Same trust gate as app/notify/schedule configs: a world-writable host
  # inventory could redirect batch operations to an attacker-controlled
  # host, so non-root-owned or loose-mode files are ignored entirely.
  # (The inventory lines carry no key=value shape, so the owner/mode check
  # is done inline rather than through app_conf_trusted_value.)
  local owner mode
  owner="$(stat -c '%U' "$FLEET_HOSTS_FILE" 2>/dev/null || printf unknown)"
  mode="$(stat -c '%a' "$FLEET_HOSTS_FILE" 2>/dev/null || printf unknown)"
  if [[ "$owner" != root || ( "$mode" != 600 && "$mode" != 400 ) ]]; then
    echo "fleet: ignoring untrusted host inventory: $FLEET_HOSTS_FILE" >&2
    return 0
  fi
  while IFS= read -r line || [[ -n "$line" ]]; do
    line="${line%%#*}"
    line="${line#"${line%%[![:space:]]*}"}"
    line="${line%"${line##*[![:space:]]}"}"
    [[ -n "$line" ]] || continue
    alias="${line%%|*}"
    target="${line#*|}"
    case "$alias" in
      *[!A-Za-z0-9_-]*|"") continue ;;
    esac
    case "$target" in
      *[!A-Za-z0-9@.:\[\]_-]*|""|*" "*)
        echo "fleet: skipping host with invalid target: $alias" >&2
        continue
        ;;
    esac
    FLEET_HOSTS+=("$alias|$target")
  done < "$FLEET_HOSTS_FILE"
}

# SSH destination with an explicit -p port when the target carries one.
fleet_target_ssh_args() {
  local target="$1" port=""
  if [[ "$target" == *:* ]]; then
    port="${target##*:}"
    target="${target%:*}"
    [[ "$port" =~ ^[0-9]+$ ]] || port=""
  fi
  printf '%s' "$target"
  [[ -n "$port" ]] && printf ' -p %s' "$port"
}

# Run one remote command for one host; prints a single-line JSON record.
fleet_run_host() {
  local alias="$1" target="$2" remote_script="$3"
  local output record
  # Each SSH opt is a single token (no spaces), and fleet_target_ssh_args
  # emits space-separated "host [-p port]" pieces; expansion is deliberate.
  # shellcheck disable=SC2046,SC2048,SC2086
  output="$(timeout "${FLEET_TIMEOUT}" ssh ${FLEET_SSH_OPTS[*]} \
    $(fleet_target_ssh_args "$target") \
    "bash -s" <<REMOTE 2>/dev/null
set -euo pipefail
${remote_script}
REMOTE
  )" || {
    printf '{"host":%s,"ok":false,"error":"ssh or remote command failed"}' \
      "$(app_json_string "$alias")"
    return 0
  }
  # The remote side is this same framework; keep its last non-empty line.
  record="$(printf '%s\n' "$output" | tr -d '\r' | sed '/^[[:space:]]*$/d' | tail -n 1)"
  # A polluted or non-JSON remote line would corrupt the merged summary, so
  # validate the record is parseable JSON before embedding it.
  if ! printf '%s' "$record" | grep -qE '^\{.*\}$'; then
    record="{\"error\":$(app_json_string "$record")}"
  fi
  printf '{"host":%s,"ok":true,"result":%s}' \
    "$(app_json_string "$alias")" "$record"
}

fleet_main() {
  local subcommand="${1:-status-all}"
  shift || true
  case "${subcommand,,}" in
    status-all|update-all|backup-all) ;;
    *)
      echo "Usage: sudo bash $0 fleet [status-all|update-all|backup-all] [--hosts FILE] [--concurrency N] [--timeout SEC] [--remote-dir DIR]" >&2
      return 2
      ;;
  esac
  local action="${subcommand,,}"
  while (($#)); do
    case "$1" in
      --hosts) FLEET_HOSTS_FILE="${2:-}"; shift 2 ;;
      --concurrency) FLEET_CONCURRENCY="${2:-}"; shift 2 ;;
      --timeout) FLEET_TIMEOUT="${2:-}"; shift 2 ;;
      --remote-dir) FLEET_REMOTE_DIR="${2:-}"; shift 2 ;;
      *) echo "fleet: unknown option: $1" >&2; return 2 ;;
    esac
  done
  [[ "$FLEET_CONCURRENCY" =~ ^[0-9]+$ ]] && (( FLEET_CONCURRENCY >= 1 )) || FLEET_CONCURRENCY=4
  [[ "$FLEET_TIMEOUT" =~ ^[0-9]+$ ]] && (( FLEET_TIMEOUT >= 10 )) || FLEET_TIMEOUT=120
  if [[ -z "$FLEET_REMOTE_DIR" || "$FLEET_REMOTE_DIR" != /* || "$FLEET_REMOTE_DIR" == *" "* ]]; then
    echo "fleet: invalid remote directory: $FLEET_REMOTE_DIR (must be absolute with no spaces)" >&2
    return 2
  fi
  fleet_load_hosts
  if [[ ${#FLEET_HOSTS[@]} -eq 0 ]]; then
    echo "fleet: no hosts configured in $FLEET_HOSTS_FILE" >&2
    return 1
  fi
  local remote_script
  remote_script="cd ${FLEET_REMOTE_DIR} 2>/dev/null && bash deploy.sh ${action} --json 2>/dev/null || echo '{\"state\":\"failed\"}'"
  # Run with bounded concurrency; each host writes its JSON record to its
  # own temp file, and failures are isolated per host.
  local tmp_root alias target entry pid
  tmp_root="$(mktemp -d)"
  local -a pids=() running=()
  for entry in "${FLEET_HOSTS[@]}"; do
    alias="${entry%%|*}"
    target="${entry#*|}"
    out_file="$tmp_root/${alias}.json"
    ( fleet_run_host "$alias" "$target" "$remote_script" > "$out_file" ) &
    pids+=($!)
    running+=("$alias")
    if (( ${#pids[@]} >= FLEET_CONCURRENCY )); then
      wait "${pids[0]}" 2>/dev/null || true
      pids=("${pids[@]:1}")
      running=("${running[@]:1}")
    fi
  done
  for pid in "${pids[@]}"; do
    wait "$pid" 2>/dev/null || true
  done
  local first=1 record
  local summary
  summary="$(printf '{"schema_version":1,"action":"%s","concurrency":%s,"hosts":[' \
    "$action" "$FLEET_CONCURRENCY")"
  for entry in "${FLEET_HOSTS[@]}"; do
    alias="${entry%%|*}"
    record="$(cat "$tmp_root/${alias}.json" 2>/dev/null || true)"
    [[ -n "$record" ]] || record="{\"host\":$(app_json_string "$alias"),\"ok\":false,\"error\":\"no result\"}"
    (( first )) || summary+=","
    first=0
    summary+="$record"
  done
  summary+="]}"
  printf '%s\n' "$summary"
  # Machine-level operation history: one JSON line per fleet run, appended
  # under the framework log root. Best-effort; never fails the command.
  local history_dir history_file
  history_dir="${DEPLOY_OPERATION_LOG_ROOT:-/var/log/deploy-scripts}"
  history_file="${history_dir}/fleet-history.jsonl"
  mkdir -p "$history_dir" 2>/dev/null || true
  printf '%s\n' "$summary" >> "$history_file" 2>/dev/null || true
  rm -rf "$tmp_root"
}

# ----- lib/app_loader.sh -----

ensure_bundled_impl_dir() {
  [[ "${DEPLOY_BUNDLED:-0}" == "1" ]] || return 0
  [[ -n "${DEPLOY_BUNDLED_IMPL_DIR:-}" ]] && return 0

  local tmp_root
  tmp_root="${TMPDIR:-/tmp}"
  tmp_root="${tmp_root%/}"
  DEPLOY_BUNDLED_IMPL_DIR="$(mktemp -d "${tmp_root}/deploy-scripts.${APP_ID:-app}.XXXXXX")" \
    || error "Failed to create bundled implementation directory"
  if ! chmod 700 "$DEPLOY_BUNDLED_IMPL_DIR"; then
    safe_rm_dir "$DEPLOY_BUNDLED_IMPL_DIR" "bundled implementation directory"
    unset DEPLOY_BUNDLED_IMPL_DIR
    error "Failed to secure bundled implementation directory"
  fi
}

app_impl_script_path() {
  local script="${APP_IMPL_SCRIPT:-}"
  if [[ "${DEPLOY_BUNDLED:-0}" == "1" ]]; then
    ensure_bundled_impl_dir
    echo "${DEPLOY_BUNDLED_IMPL_DIR}/${BUNDLED_APP_IMPL_SCRIPT_NAME}"
    return 0
  fi
  [[ -n "$script" ]] || error "APP_IMPL_SCRIPT is not configured for ${APP_ID:-unknown}"
  if [[ "$script" = /* ]]; then
    echo "$script"
  else
    echo "${DEPLOY_ROOT_DIR}/${script}"
  fi
}

ensure_bundled_app_impl_script() {
  [[ "${DEPLOY_BUNDLED:-0}" == "1" ]] || return 0
  local script_path tmp_path
  ensure_bundled_impl_dir
  script_path="$(app_impl_script_path)"
  tmp_path="$(mktemp "${script_path}.XXXXXX")" \
    || error "Failed to create bundled app implementation payload"
  local marker
  marker="__DEPLOY_APP_IMPL_SCRIPT__ ${BUNDLED_APP_IMPL_SCRIPT_NAME:-}"
  if grep -qxF "$marker" "${BASH_SOURCE[0]}"; then
    if ! awk -v marker="$marker" '
        $0 == marker { found=1; next }
        found && $0 == "__DEPLOY_APP_IMPL_SCRIPT_END__" { exit }
        found { print }
      ' "${BASH_SOURCE[0]}" > "$tmp_path"; then
      rm -f "$tmp_path"
      cleanup_bundled_app_impl_script
      error "Failed to extract bundled implementation payload"
    fi
  elif ! awk "/^__DEPLOY_APP_IMPL_SCRIPT__$/ { found=1; next } found { print }" "${BASH_SOURCE[0]}" > "$tmp_path"; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Failed to extract bundled app implementation payload"
  fi
  if [[ ! -s "$tmp_path" ]]; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Bundled app implementation payload is empty"
  fi
  if ! chmod 700 "$tmp_path"; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Failed to secure bundled app implementation payload"
  fi
  if ! mv "$tmp_path" "$script_path"; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Failed to install bundled app implementation payload"
  fi
}

cleanup_bundled_app_impl_script() {
  [[ "${DEPLOY_BUNDLED:-0}" == "1" ]] || return 0
  [[ -n "${DEPLOY_BUNDLED_IMPL_DIR:-}" ]] || return 0
  safe_rm_dir "$DEPLOY_BUNDLED_IMPL_DIR" "bundled implementation directory"
  unset DEPLOY_BUNDLED_IMPL_DIR
}

# The framework logging helpers and CLI dispatch (info/success/warn/error/
# step/prompt, show_banner, usage, show_menu, dispatch_action) live in
# lib/logging.sh and lib/cli.sh, which load before the app implementation.
# Implementation scripts define only their own do_* / hook functions and
# never re-define framework functions, so no restore step is needed: keeping
# a copy here would drift from the real definitions (O12: `verify` was added
# to cli.sh but not to the old app_loader copy). This hook stays for
# backward compatibility but is intentionally a no-op.
restore_framework_functions() {
  :
}

load_app_impl() {
  APP_IMPL_SCRIPT="$1"
  ensure_bundled_impl_dir
  ensure_bundled_app_impl_script
  local script_path
  script_path="$(app_impl_script_path)"
  [[ -f "$script_path" ]] || error "App implementation script not found: $script_path"
  if DEPLOY_IMPL_SOURCE_ONLY=1 source "$script_path"; then
    unset DEPLOY_IMPL_SOURCE_ONLY
    cleanup_bundled_app_impl_script
  else
    local source_status=$?
    unset DEPLOY_IMPL_SOURCE_ONLY
    cleanup_bundled_app_impl_script
    return "$source_status"
  fi
  restore_framework_functions
}

# ----- lib/cli.sh -----

show_banner() {
  echo -e "\n${BOLD}${CYAN}${APP_NAME:-Deployment Manager}${NC}"
  [[ -n "${APP_DESCRIPTION:-}" ]] && echo -e "${APP_DESCRIPTION}\n"
}

usage() {
  echo "$(t common.usage "$0")" >&2
  echo "      $(t common.no_argument_menu)" >&2
  if [[ "${1:-}" == "--help" ]] && declare -p CONFIG_KEYS >/dev/null 2>&1; then
    local key
    echo "" >&2
    echo "$(t common.help_config_keys)" >&2
    for key in "${CONFIG_KEYS[@]}"; do
      printf '  %-24s %s\n' "$key" "${!key:-}" >&2
    done
    echo "" >&2
    echo "$(t common.help_env_hint)" >&2
  fi
}

# Application-level dry-run: prints the actions that install/update/backup/
# uninstall would take and exits without modifying the system. Each do_* and
# bapp_* entry point honors DEPLOY_DRY_RUN=1.
app_dry_run_guard() {
  local action="$1"
  [[ "${DEPLOY_DRY_RUN:-0}" == "1" ]] || return 0
  case "$action" in
    install)
      info "$(t common.dry_run_install "$APP_NAME")"
      app_dry_run_list_config
      ;;
    update)
      info "$(t common.dry_run_update "$APP_NAME")"
      ;;
    backup)
      info "$(t common.dry_run_backup "$APP_NAME")"
      ;;
    uninstall)
      info "$(t common.dry_run_uninstall "$APP_NAME")"
      ;;
    *)
      info "$(t common.dry_run_action "$APP_NAME" "$action")"
      ;;
  esac
  exit 0
}

app_dry_run_list_config() {
  [[ "${DEPLOY_DRY_RUN_SHOW_CONFIG:-0}" == "1" ]] || return 0
  local key
  if declare -p CONFIG_KEYS >/dev/null 2>&1; then
    echo "$(t common.dry_run_config)" >&2
    for key in "${CONFIG_KEYS[@]}"; do
      printf '  %-24s %s\n' "$key" "${!key:-}" >&2
    done
  fi
}

show_menu() {
  show_banner
  echo "$(t common.choose_action)"
  echo
  echo "  1) install    - $(t menu.install_desc)"
  echo "  2) update     - $(t menu.update_desc)"
  echo "  3) backup     - $(t menu.backup_desc)"
  echo "  4) restore    - $(t menu.restore_desc)"
  echo "  5) status     - $(t menu.status_desc)"
  echo "  6) doctor     - $(t menu.doctor_desc)"
  echo "  7) uninstall  - $(t menu.uninstall_desc)"
  echo "  q) $(t common.quit)"
  echo
  prompt "$(t common.selection_prompt)"
  local choice
  read -r choice
  dispatch_action "$choice"
}

# Export the app's deployment config before uninstall so the user can restore
# it later. Writes <BACKUP_DIR or /opt>/<app>-deploy-config-<ts>.conf (mode
# 600) and prints a hint about re-importing. Best-effort: failures are
# warnings, never block the uninstall.
app_export_config_before_uninstall() {
  local conf_file dir export_path
  conf_file="$(app_conf_file 2>/dev/null || true)"
  [[ -n "$conf_file" && -f "$conf_file" ]] || return 0
  dir="$(dirname "$conf_file")"
  export_path="${dir}/${APP_ID:-app}-deploy-config-export.conf"
  if [[ -d "${BACKUP_DIR:-}" ]] && [[ -w "${BACKUP_DIR}" ]]; then
    export_path="${BACKUP_DIR}/${APP_ID:-app}-deploy-config-export.conf"
  fi
  if ! cp "$conf_file" "$export_path" 2>/dev/null; then
    warn "$(t common.config_export_failed "$conf_file")"
    return 0
  fi
  chmod 600 "$export_path" 2>/dev/null || true
  info "$(t common.config_exported "$export_path")"
  info "$(t common.config_export_restore_hint "$export_path")"
}

dispatch_action() {
  local action="${1:-menu}"
  shift || true
  if declare -f deploy_trim >/dev/null 2>&1; then
    action="$(deploy_trim "$action")"
  fi
  case "${action,,}" in
      install|1) app_dry_run_guard install; operation_run_app_action install do_install "$@" ;;
      update|2) app_dry_run_guard update; operation_run_app_action update do_update "$@" ;;
      backup|3) app_dry_run_guard backup; operation_run_app_action backup do_backup "$@" ;;
      restore|4)
        if declare -f do_restore >/dev/null 2>&1; then
          operation_run_app_action restore do_restore "$@"
        else
          error "$(t error.unsupported_action "${APP_NAME:-app}" restore)"
        fi
        ;;
      cert|https)
        if declare -f do_cert >/dev/null 2>&1; then
          operation_run_app_action cert do_cert "$@"
        else
          error "$(t error.unsupported_action "${APP_NAME:-app}" cert)"
        fi
        ;;
      verify)
        if declare -f do_verify >/dev/null 2>&1; then
          operation_run_app_action verify do_verify "$@"
        else
          error "$(t error.unsupported_action "${APP_NAME:-app}" verify)"
        fi
        ;;
      token)
        if declare -f do_token >/dev/null 2>&1; then
          operation_run_app_action token do_token "$@"
        else
          error "$(t error.unsupported_action "${APP_NAME:-app}" token)"
        fi
        ;;
      signups)
        if declare -f do_signups >/dev/null 2>&1; then
          operation_run_app_action signups do_signups "$@"
        else
          error "$(t error.unsupported_action "${APP_NAME:-app}" signups)"
        fi
        ;;
      --dry-run|--dryrun)
        DEPLOY_DRY_RUN=1
        DEPLOY_DRY_RUN_SHOW_CONFIG=1
        export DEPLOY_DRY_RUN DEPLOY_DRY_RUN_SHOW_CONFIG
        if (($#)); then
          dispatch_action "$@"
        else
          error "$(t common.dry_run_requires_action "$APP_NAME")"
        fi
        ;;
      status|5) do_status "$@" ;;
      status-json|json-status) do_status_json "$@" ;;
      doctor|6) do_doctor "$@" ;;
      uninstall|7)
        app_dry_run_guard uninstall
        app_export_config_before_uninstall
        operation_run_app_action uninstall do_uninstall "$@" ;;
    menu|"") show_menu ;;
    help|-h|--help) usage --help ;;
    q|quit|exit) exit 0 ;;
    *) error "$(t common.invalid_choice "$action")" ;;
  esac
}

# ----- lib/manager_security_doctor.sh -----

manager_security_doctor_print_usage() {
  printf '%s\n' "$(t security_doctor.usage "${DEPLOY_SCRIPT_NAME:-deploy.sh}")" >&2
}

security_doctor_path() {
  local relative_path="$1" root="${DEPLOY_SECURITY_AUDIT_ROOT:-/}"
  if [[ "$root" == "/" ]]; then
    printf '/%s\n' "${relative_path#/}"
  else
    printf '%s/%s\n' "${root%/}" "${relative_path#/}"
  fi
}

security_doctor_reset() {
  SECURITY_DOCTOR_CHECKS=()
  SECURITY_DOCTOR_STATES=()
  SECURITY_DOCTOR_PATHS=()
  SECURITY_DOCTOR_MESSAGES=()
  SECURITY_DOCTOR_OK=0
  SECURITY_DOCTOR_WARNING=0
  SECURITY_DOCTOR_ERROR=0
  SECURITY_DOCTOR_NOT_CHECKED=0
}

security_doctor_record() {
  local check="$1" state="$2" path="$3" message="$4"
  SECURITY_DOCTOR_CHECKS+=("$check")
  SECURITY_DOCTOR_STATES+=("$state")
  SECURITY_DOCTOR_PATHS+=("$path")
  SECURITY_DOCTOR_MESSAGES+=("$message")
  case "$state" in
    ok) SECURITY_DOCTOR_OK=$((SECURITY_DOCTOR_OK + 1)) ;;
    warning) SECURITY_DOCTOR_WARNING=$((SECURITY_DOCTOR_WARNING + 1)) ;;
    error) SECURITY_DOCTOR_ERROR=$((SECURITY_DOCTOR_ERROR + 1)) ;;
    not_checked) SECURITY_DOCTOR_NOT_CHECKED=$((SECURITY_DOCTOR_NOT_CHECKED + 1)) ;;
  esac
}

security_doctor_file_contains_plain_sub2api_dsn() {
  local path="$1"
  grep -Eq '^[[:space:]]*(export[[:space:]]+)?PG_DSN[[:space:]]*=[[:space:]]*(postgres|postgresql)://' "$path" 2>/dev/null \
    || grep -Eq '(postgres|postgresql)://[^[:space:]]+@' "$path" 2>/dev/null
}

security_doctor_check_vaultwarden_tokens() {
  local root_dir tmp_dir candidate
  local -a matches=()
  root_dir="$(security_doctor_path /root)"
  tmp_dir="$(security_doctor_path /tmp)"

  if [[ -d "$root_dir" && ! -r "$root_dir" ]]; then
    security_doctor_record vaultwarden_legacy_token error "$root_dir" "$(t security_doctor.token.inspect_error)"
    return
  fi
  if [[ -d "$tmp_dir" && ! -r "$tmp_dir" ]]; then
    security_doctor_record vaultwarden_legacy_token error "$tmp_dir" "$(t security_doctor.token.tmp_inspect_error)"
    return
  fi

  shopt -s nullglob
  for candidate in "$root_dir"/.vaultwarden-admin-token.* "$tmp_dir"/vaultwarden-admin-token* "$tmp_dir"/vaultwarden-token*; do
    [[ -e "$candidate" || -L "$candidate" ]] && matches+=("$candidate")
  done
  shopt -u nullglob

  if ((${#matches[@]})); then
    security_doctor_record vaultwarden_legacy_token warning "${matches[0]}" "$(t security_doctor.token.found)"
  else
    security_doctor_record vaultwarden_legacy_token ok "$root_dir" "$(t security_doctor.token.none)"
  fi
}

security_doctor_check_sub2api_dsn() {
  local candidate inspected=0
  local -a candidates=()
  candidates=(
    "$(security_doctor_path /usr/local/bin/sub2api-backup)"
    "$(security_doctor_path /etc/sub2api-deploy.conf)"
  )
  for candidate in "${candidates[@]}"; do
    [[ -e "$candidate" ]] || continue
    inspected=1
    if [[ ! -r "$candidate" ]]; then
      security_doctor_record sub2api_plaintext_dsn error "$candidate" "$(t security_doctor.dsn.inspect_error)"
      return
    fi
    if security_doctor_file_contains_plain_sub2api_dsn "$candidate"; then
      security_doctor_record sub2api_plaintext_dsn warning "$candidate" "$(t security_doctor.dsn.found)"
      return
    fi
  done
  if ((inspected == 0)); then
    security_doctor_record sub2api_plaintext_dsn not_checked "$(security_doctor_path /usr/local/bin/sub2api-backup)" "$(t security_doctor.dsn.missing)"
  else
    security_doctor_record sub2api_plaintext_dsn ok "$(security_doctor_path /usr/local/bin/sub2api-backup)" "$(t security_doctor.dsn.none)"
  fi
}

security_doctor_config_value() {
  local path="$1" key="$2" line value
  line="$(grep -E "^[[:space:]]*${key}[[:space:]]*=" "$path" 2>/dev/null | head -n 1 || true)"
  [[ -n "$line" ]] || return 1
  value="${line#*=}"
  value="${value#"${value%%[![:space:]]*}"}"
  value="${value%"${value##*[![:space:]]}"}"
  if [[ "$value" == '"'*'"' && ${#value} -ge 2 ]]; then
    value="${value:1:${#value}-2}"
  fi
  printf '%s\n' "$value"
}

security_doctor_check_public_binds() {
  local etc_dir conf_file key bind_addr tls_enabled inspected=0
  local -a conf_files=()
  etc_dir="$(security_doctor_path /etc)"
  if [[ ! -d "$etc_dir" ]]; then
    security_doctor_record public_listener not_checked "$etc_dir" "$(t security_doctor.listener.missing_dir)"
    return
  fi
  if [[ ! -r "$etc_dir" ]]; then
    security_doctor_record public_listener error "$etc_dir" "$(t security_doctor.listener.inspect_error)"
    return
  fi

  shopt -s nullglob
  conf_files=("$etc_dir"/*-deploy.conf "$etc_dir"/vaultwarden_deploy.conf "$etc_dir"/tickflow-deploy.conf "$etc_dir"/cyberstrike-ai-deploy.conf "$etc_dir"/sub2api-deploy.conf)
  shopt -u nullglob
  if ((${#conf_files[@]} == 0)); then
    security_doctor_record public_listener not_checked "$etc_dir" "No managed deployment configuration files found."
    return
  fi

  declare -A seen_conf_files=()
  for conf_file in "${conf_files[@]}"; do
    [[ -f "$conf_file" ]] || continue
    [[ -n "${seen_conf_files[$conf_file]:-}" ]] && continue
    seen_conf_files["$conf_file"]=1
    if [[ ! -r "$conf_file" ]]; then
      security_doctor_record public_listener error "$conf_file" "Cannot read the managed deployment configuration."
      continue
    fi
    for key in BA_BIND_ADDR SUB2API_BIND_ADDR TICKFLOW_BIND_ADDR; do
      bind_addr="$(security_doctor_config_value "$conf_file" "$key" 2>/dev/null || true)"
      [[ -n "$bind_addr" ]] || continue
      inspected=$((inspected + 1))
      if ! app_public_bind_is_wildcard "$bind_addr"; then
        security_doctor_record public_listener ok "$conf_file" "$(t security_doctor.listener.not_wildcard "$key")"
        continue
      fi
      if [[ "$key" == BA_BIND_ADDR && "${conf_file##*/}" == "frps-deploy.conf" ]]; then
        security_doctor_record public_listener ok "$conf_file" "$(t security_doctor.listener.frps_exception)"
        continue
      fi
      tls_enabled=0
      if [[ "$key" == BA_BIND_ADDR ]]; then
        tls_enabled="$(security_doctor_config_value "$conf_file" BA_ENABLE_HTTPS 2>/dev/null || true)"
        if deploy_value_truthy "$tls_enabled"; then
          security_doctor_record public_listener ok "$conf_file" "$(t security_doctor.listener.tls "$key")"
          continue
        fi
      fi
      security_doctor_record public_listener warning "$conf_file" "$(t security_doctor.listener.plain "$key")"
    done
  done

  if ((inspected == 0)); then
    security_doctor_record public_listener not_checked "$etc_dir" "$(t security_doctor.listener.none)"
  fi
}

security_doctor_root_crontab_content() {
  local override_path="$1" output status
  SECURITY_DOCTOR_CRONTAB_SOURCE=""
  if [[ -n "$override_path" ]]; then
    if [[ ! -e "$override_path" ]]; then
      return 2
    fi
    [[ -r "$override_path" ]] || return 3
    SECURITY_DOCTOR_CRONTAB_SOURCE="$override_path"
    cat "$override_path"
    return 0
  fi
  command -v crontab >/dev/null 2>&1 || return 4
  set +e
  output="$(crontab -l -u root 2>/dev/null)"
  status=$?
  set -e
  if [[ "$status" -eq 0 ]]; then
    SECURITY_DOCTOR_CRONTAB_SOURCE="root crontab"
    printf '%s\n' "$output"
    return 0
  fi
  [[ "$status" -eq 1 ]] && return 2
  return 4
}

security_doctor_contains_legacy_backup_schedule() {
  grep -Eq '(/usr/local/bin/(vaultwarden-backup|sub2api-backup)|new-api-backup|cyberstrike-ai-backup)' 2>/dev/null
}

security_doctor_check_cron_residue() {
  local crontab_content status cron_dir cron_file base found=0
  local -a expected_files=(vaultwarden-backup certbot-renew sub2api-backup new-api-backup cyberstrike-ai-backup deploy-scripts-batch)

  set +e
  crontab_content="$(security_doctor_root_crontab_content "${DEPLOY_SECURITY_AUDIT_ROOT_CRONTAB_FILE:-}")"
  status=$?
  set -e
  case "$status" in
    0)
      if printf '%s\n' "$crontab_content" | security_doctor_contains_legacy_backup_schedule; then
        security_doctor_record legacy_root_crontab warning "${SECURITY_DOCTOR_CRONTAB_SOURCE:-root crontab}" "$(t security_doctor.cron.legacy_root)"
      else
        security_doctor_record legacy_root_crontab ok "${SECURITY_DOCTOR_CRONTAB_SOURCE:-root crontab}" "No legacy application backup schedule found in root crontab."
      fi
      ;;
    2) security_doctor_record legacy_root_crontab ok "root crontab" "$(t security_doctor.cron.empty)" ;;
    3) security_doctor_record legacy_root_crontab error "${DEPLOY_SECURITY_AUDIT_ROOT_CRONTAB_FILE}" "Cannot inspect the supplied root crontab fixture." ;;
    *) security_doctor_record legacy_root_crontab not_checked "root crontab" "$(t security_doctor.cron.inspect_error)"
       ;;
  esac

  cron_dir="$(security_doctor_path /etc/cron.d)"
  if [[ ! -d "$cron_dir" ]]; then
    security_doctor_record legacy_cron_file not_checked "$cron_dir" "$(t security_doctor.cron.dir_missing)"
    return
  fi
  if [[ ! -r "$cron_dir" ]]; then
    security_doctor_record legacy_cron_file error "$cron_dir" "$(t security_doctor.cron.dir_error)"
    return
  fi

  shopt -s nullglob
  for cron_file in "$cron_dir"/*; do
    [[ -f "$cron_file" && -r "$cron_file" ]] || continue
    base="${cron_file##*/}"
    case " ${expected_files[*]} " in
      *" ${base} "*) continue ;;
    esac
    if security_doctor_contains_legacy_backup_schedule < "$cron_file"; then
      security_doctor_record legacy_cron_file warning "$cron_file" "$(t security_doctor.cron.legacy_file)"
      found=1
    fi
  done
  shopt -u nullglob
  if ((found == 0)); then
    security_doctor_record legacy_cron_file ok "$cron_dir" "$(t security_doctor.cron.none)"
  fi
}

security_doctor_print_json() {
  local index first=1
  printf '{"schema_version":1,"generated_at":%s,"summary":{"ok":%s,"warning":%s,"error":%s,"not_checked":%s},"records":[' \
    "$(app_json_string "$(state_now)")" "$SECURITY_DOCTOR_OK" "$SECURITY_DOCTOR_WARNING" "$SECURITY_DOCTOR_ERROR" "$SECURITY_DOCTOR_NOT_CHECKED"
  for index in "${!SECURITY_DOCTOR_CHECKS[@]}"; do
    ((first)) || printf ','
    first=0
    printf '{"check":%s,"state":%s,"path":%s,"message":%s}' \
      "$(app_json_string "${SECURITY_DOCTOR_CHECKS[$index]}")" \
      "$(app_json_string "${SECURITY_DOCTOR_STATES[$index]}")" \
      "$(app_json_string "${SECURITY_DOCTOR_PATHS[$index]}")" \
      "$(app_json_string "${SECURITY_DOCTOR_MESSAGES[$index]}")"
  done
  printf ']}\n'
}

security_doctor_print_human() {
  local index
  printf '%-26s %-13s %-42s %s\n' Check State Path Detail
  for index in "${!SECURITY_DOCTOR_CHECKS[@]}"; do
    printf '%-26s %-13s %-42s %s\n' \
      "${SECURITY_DOCTOR_CHECKS[$index]}" "${SECURITY_DOCTOR_STATES[$index]}" \
      "${SECURITY_DOCTOR_PATHS[$index]}" "${SECURITY_DOCTOR_MESSAGES[$index]}"
  done
  printf '\nSummary: %s ok, %s warning, %s error, %s not checked.\n' \
    "$SECURITY_DOCTOR_OK" "$SECURITY_DOCTOR_WARNING" "$SECURITY_DOCTOR_ERROR" "$SECURITY_DOCTOR_NOT_CHECKED"
}

manager_security_doctor_main() {
  local json arg
  for arg in "$@"; do
    case "$arg" in
      --help|-h)
        manager_security_doctor_print_usage
        return 0
        ;;
    esac
  done
  if ! manager_parse_args "--json --help" manager_security_doctor_print_usage "$@"; then
    return $?
  fi
  json="$MANAGER_ARG_JSON"

  security_doctor_reset
  security_doctor_check_vaultwarden_tokens
  security_doctor_check_sub2api_dsn
  security_doctor_check_public_binds
  security_doctor_check_cron_residue

  if ((json)); then
    security_doctor_print_json
  else
    security_doctor_print_human
  fi
  ((SECURITY_DOCTOR_ERROR == 0))
}

# ----- lib/manager_cli.sh -----

manager_usage() {
  echo "$(t manager.usage "$0")" >&2
  echo "$(t manager.usage_central)" >&2
  echo "$(t manager.usage_examples "$0" "$0" "$0")" >&2
  echo "$(t manager.available_apps "$(deploy_app_ids | tr '\n' ' ' | sed 's/[[:space:]]*$//')")" >&2
}

show_manager_banner() {
  echo -e "\n${BOLD}${CYAN}$(t manager.title)${NC}"
  echo -e "$(t manager.description)\n"
}

show_manager_menu() {
  show_manager_banner
  echo "$(t manager.choose_app)"
  echo

  local index=1 app_id app_name
  for app_id in "${DEPLOY_APP_IDS[@]}"; do
    app_name="$(deploy_app_name_for "$app_id")"
    printf '  %s) %-16s %s\n' "$index" "$app_id" "$app_name"
    index=$((index + 1))
  done
  echo "  s) $(t manager.status_all)"
  echo "  p) $(t manager.problems)"
  echo "  u) $(t manager.check_updates)"
  echo "  f) $(t manager.check_self_update)"
  echo "  q) $(t common.quit)"
  echo

  prompt "$(t manager.selection_prompt)"
  local choice app_id status
  read -r choice
  case "${choice,,}" in
    s|status-all) manager_status_main status-all; return ;;
    p|problems) manager_status_main problems; return ;;
    u|check-update) manager_update_main; return ;;
    f|self-update) self_update_main --check; return ;;
    q|quit|exit) exit 0 ;;
  esac
  set +e
  app_id="$(deploy_app_id_from_selection "$choice")"
  status=$?
  set -e
  if [[ "$status" -eq 2 ]]; then
    exit 0
  fi
  if [[ "$status" -ne 0 ]]; then
    error "$(t manager.invalid_app "$choice")"
  fi
  manager_load_app "$app_id"
  show_menu
}

manager_load_app() {
  local app_id="$1" app_file
  if [[ "${DEPLOY_BUNDLED_MANAGER:-0}" == "1" ]]; then
    BUNDLED_APP_IMPL_SCRIPT_NAME="$(deploy_app_bundled_impl_script_name_for "$app_id")"
    manager_source_bundled_app_definition "$app_id"
    return 0
  fi
  app_file="$(deploy_app_file_for "$app_id")" || error "$(t manager.invalid_app "$app_id")"
  app_file="${DEPLOY_ROOT_DIR}/${app_file}"
  [[ -f "$app_file" ]] || error "$(t manager.app_file_missing "$app_file")"
  source "$app_file"
}

manager_source_bundled_app_definition() {
  local app_id="$1" marker
  marker="__DEPLOY_APP_DEFINITION__ ${app_id}"
  if ! grep -qxF "$marker" "${BASH_SOURCE[0]}"; then
    error "$(t manager.app_definition_missing "$app_id")"
  fi
  source <(
    awk -v marker="$marker" '
      $0 == marker { found=1; next }
      found && $0 == "__DEPLOY_APP_DEFINITION_END__" { exit }
      found { print }
    ' "${BASH_SOURCE[0]}"
  )
}

manager_list_apps() {
  local app_id app_name
  for app_id in "${DEPLOY_APP_IDS[@]}"; do
    app_name="$(deploy_app_name_for "$app_id")"
    printf '%-16s %s\n' "$app_id" "$app_name"
  done
}

manager_main() {
  local command="${1:-menu}" app_id status selection_output instance
  command="$(deploy_trim "$command")"
  case "${command,,}" in
    overview|status-all|problems|health-all)
      shift || true
      manager_status_main "${command,,}" "$@"
      ;;
    doctor-all)
      shift || true
      manager_doctor_main "$@"
      ;;
    doctor-security|security-doctor)
      shift || true
      manager_security_doctor_main "$@"
      ;;
    doctor)
      shift || true
      case "${1:-}" in
        security) shift || true; manager_security_doctor_main "$@" ;;
        *) manager_security_doctor_print_usage; return 2 ;;
      esac
      ;;
    backup-all)
      shift || true
      manager_backup_main "$@"
      ;;
    notify-config)
      shift || true
      notify_config_main "$@"
      ;;
    schedule|unschedule)
      shift || true
      # schedule_main parses its own subcommand: `deploy.sh schedule` enables/
      # edits, `deploy.sh schedule status|unschedule|run` dispatches to those
      # branches. Only unschedule maps directly here.
      if [[ "${command,,}" == "unschedule" ]]; then
        schedule_main unschedule "$@"
      else
        schedule_main "$@"
      fi
      ;;
    schedule-run)
      shift || true
      schedule_run_main "$@"
      ;;
    export|import)
      shift || true
      migrate_main "$command" "$@"
      ;;
    fleet)
      shift || true
      fleet_main "$@"
      ;;
    check-update)
      shift || true
      manager_update_main "$@"
      ;;
    update-all)
      shift || true
      manager_update_all_main "$@"
      ;;
    history)
      shift || true
      manager_history_main "$@"
      ;;
    self-version)
      shift || true
      local self_version_json=0 self_version_arg
      while (($#)); do
        self_version_arg="$1"
        case "$self_version_arg" in
          --json) self_version_json=1; shift ;;
          -h|--help) printf '%s\n' "Usage: deploy.sh self-version [--json]" >&2; return 0 ;;
          *) printf 'self-version: unknown option: %s\n' "$self_version_arg" >&2; return 2 ;;
        esac
      done
      self_update_load_config || { printf 'self-version: invalid self-update configuration\n' >&2; return 1; }
      self_update_print_version "$self_version_json"
      ;;
    self-update)
      shift || true
      self_update_main "$@"
      ;;
    menu|"")
      show_manager_menu
      ;;
    list|apps)
      manager_list_apps
      ;;
    help|-h|--help)
      manager_usage
      ;;
    q|quit|exit)
      exit 0
      ;;
    *)
      # The selection prints "<app_id> [instance]"; set APP_INSTANCE in the
      # current shell so per-instance config/lock paths take effect.
      set +e
      selection_output="$(deploy_app_id_from_selection "$command")"
      status=$?
      set -e
      if [[ "$status" -eq 2 ]]; then
        exit 0
      fi
      if [[ "$status" -ne 0 ]]; then
        manager_usage
        error "$(t manager.invalid_app "$command")"
      fi
      app_id="${selection_output%% *}"
      instance="${selection_output#* }"
      if [[ "$instance" == "$app_id" || -z "$instance" ]]; then
        APP_INSTANCE=""
      else
        APP_INSTANCE="$instance"
      fi
      shift || true
      manager_load_app "$app_id"
      dispatch_action "$@"
      ;;
  esac
}

manager_main "$@"
exit 0

