    else
      warn "$(t app.vaultwarden.warn.web_vault_extract)"
      error "$(t app.vaultwarden.error.web_vault_install)"
    fi
  else
    info "$(t app.vaultwarden.info.web_vault_github)"
    local _wv_ver="${WEB_VAULT_VER:-}"
    if [[ -z "$_wv_ver" ]]; then
      _wv_ver=$(get_latest_webvault_ver)
