echo "  ╚══════════════════════════════════════════════════════╝"
echo -e "${NC}"
echo -e "  ${BOLD}$(t app.blog.workflow_title)${NC}"
echo ""
echo -e "  ${CYAN}# $(t app.blog.workflow_new_post)${NC}"
echo -e "  cd ${SITE_DIR}"
echo -e "  hugo new content post/my-post/index.md"
echo ""
echo -e "  ${CYAN}# $(t app.blog.workflow_preview)${NC}"
echo -e "  hugo server -D --bind 0.0.0.0 --port 1313"
echo -e "  # $(t app.blog.workflow_visit "$INTERNAL_IP")"
echo ""
echo -e "  ${CYAN}# $(t app.blog.workflow_publish)${NC}"
echo -e "  hugo --destination ${PUBLIC_DIR} --gc --minify"
echo -e "  /usr/local/bin/blog-publish"
echo ""
if [[ "$ENABLE_CMS" == "true" ]]; then
echo -e "  ${BOLD}$(t app.blog.cms_usage)${NC}"
echo ""
echo -e "  ${CYAN}# $(t app.blog.cms_github_backend)${NC}"
echo -e "  $(t app.blog.cms_oauth_step1)"
echo -e "$(t app.blog.cms_oauth_homepage "$CMS_SITE_URL")"
echo -e "$(t app.blog.cms_oauth_callback)"
echo -e "$(t app.blog.cms_oauth_proxy)"
echo -e "  $(t app.blog.cms_push_repo "$SITE_DIR" "$CMS_REPO")"
echo -e "  $(t app.blog.cms_login "$CMS_SITE_URL")"
echo ""
echo -e "  ${CYAN}# $(t app.blog.cms_local_debug)${NC}"
echo -e "  # $(t app.blog.cms_test_repo "$SITE_DIR")"
echo -e "  # $(t app.blog.cms_run_server)"
echo ""
fi
echo -e "  ${BOLD}$(t app.blog.https_title)${NC}"
echo -e "  apt install certbot python3-certbot-nginx -y"
echo -e "  certbot --nginx -d ${BLOG_DOMAIN:-your-domain.com}"
echo ""
echo -e "  ${BOLD}$(t app.blog.theme_docs)${NC}  https://stack.jimmycai.com"
echo -e "  ${BOLD}📖  Decap CMS：${NC} https://decapcms.org/docs/"
echo ""
echo -e "  ${YELLOW}${BOLD}[i]${NC} $(t app.blog.rebuild_hint "$PUBLIC_DIR")"
echo ""
}

_blog_status_path() {
  local label="$1" path="$2"
  if [[ -e "$path" || -L "$path" ]]; then
    printf '  %s: %b%s%b (%s)\n' "$label" "$GREEN" "$(t app.blog.status.exists)" "$NC" "$path"
  else
    printf '  %s: %b%s%b (%s)\n' "$label" "$RED" "$(t app.blog.status.missing)" "$NC" "$path"
  fi
}

do_status() {
  show_banner
  [[ $EUID -ne 0 ]] && warn "$(t app.blog.warn.non_root_status "$0")"
  _blog_load_config_if_root
  step "$(t app.blog.step_status)"

  _blog_status_path "$(t app.blog.status.site)" "$SITE_DIR"
  _blog_status_path "$(t app.blog.status.public)" "$PUBLIC_DIR"
  _blog_status_path "$(t app.blog.status.nginx_root)" "$NGINX_ROOT"
  _blog_status_path "$(t app.blog.status.nginx_config)" "/etc/nginx/sites-available/blog"
  _blog_status_path "$(t app.blog.status.publish_helper)" "/usr/local/bin/blog-publish"

  if [[ -d "$PUBLIC_DIR" ]]; then
    local html_count
    html_count=$(find "$PUBLIC_DIR" -name "*.html" 2>/dev/null | wc -l | tr -d '[:space:]')
    printf '  %s\n' "$(t app.blog.status.html_count "${html_count:-0}")"
  fi

  if command -v systemctl >/dev/null 2>&1; then
    printf '  %s: %s\n' "$(t app.blog.status.nginx)" "$(service_status_label nginx)"
  fi

  if command -v hugo >/dev/null 2>&1; then
    printf '  %s: %s\n' "$(t app.blog.status.hugo)" "$(hugo version 2>/dev/null | head -1 || t status.unknown)"
  else
    printf '  %s: %b%s%b\n' "$(t app.blog.status.hugo)" "$YELLOW" "$(t app.blog.status.hugo_missing)" "$NC"
  fi

  if command -v curl >/dev/null 2>&1; then
    local http_code
    http_code=$(curl -H "Host: ${BLOG_DOMAIN:-localhost}" -o /dev/null -s -w "%{http_code}" --max-time 5 "http://127.0.0.1/" 2>/dev/null || true)
    http_code="${http_code:-000}"
    printf '  %s: %s\n' "$(t app.blog.status.local_health)" "$(t app.blog.status.local_response "$http_code" "${BLOG_DOMAIN:-localhost}")"
  else
    printf '  %s: %s\n' "$(t app.blog.status.local_health)" "$(t app.blog.status.local_skip)"
  fi
}

do_update() {
  show_banner
  require_root "update"
  _blog_load_config_if_root
  command -v systemctl >/dev/null 2>&1 || error "$(t app.blog.error.systemd_required)"
  command -v nginx >/dev/null 2>&1 || error "$(t app.blog.update.error_nginx_missing)"
  command -v hugo >/dev/null 2>&1 || error "$(t app.blog.update.error_hugo_missing)"
  acquire_lock
  require_safe_path "SITE_DIR" "$SITE_DIR"
  require_safe_path "PUBLIC_DIR" "$PUBLIC_DIR"
  require_safe_path "NGINX_ROOT" "$NGINX_ROOT"
  [[ -d "$SITE_DIR" ]] || error "$(t app.blog.update.error_not_installed "$SITE_DIR")"
  [[ -d "${SITE_DIR}/.git" ]] || error "$(t app.blog.update.error_git_missing "$SITE_DIR")"
  [[ -f /etc/nginx/sites-available/blog || -L /etc/nginx/sites-enabled/blog ]] \
    || error "$(t app.blog.update.error_nginx_site_missing)"

  step "$(t app.blog.step_install_hugo)"
  _blog_install_hugo_package
  _blog_build_site
  _blog_deploy_public
  _write_publish_script

  if nginx -t >/dev/null 2>&1; then
    if systemctl reload nginx; then
      success "$(t app.blog.update.nginx_reloaded)"
    else
      warn "$(t app.blog.update.nginx_reload_failed)"
    fi
  else
    nginx -t >&2 || true
    warn "$(t app.blog.update.nginx_config_failed)"
  fi

  step "$(t app.blog.step_health)"
  local http_code
  http_code=$(curl -H "Host: ${BLOG_DOMAIN:-localhost}" -o /dev/null -s -w "%{http_code}" --max-time 5 "http://127.0.0.1/" 2>/dev/null || echo "000")
  if [[ "$http_code" == "200" ]]; then
    success "$(t app.blog.http_ok)"
  else
    warn "$(t app.blog.http_warn "$http_code")"
  fi
  app_save_config
  success "$(t app.blog.update.success "$NGINX_ROOT")"
}

do_backup() {
  show_banner
  require_root "backup"
  _blog_load_config_if_root
  acquire_lock
  step "$(t app.blog.step_backup)"
  require_safe_path "BLOG_BACKUP_DIR" "$BLOG_BACKUP_DIR"
  if ! mkdir -p "$BLOG_BACKUP_DIR"; then
    error "$(t app.blog.backup.error_dir "$BLOG_BACKUP_DIR")"
  fi

  local timestamp archive archive_tmp stage copied=false
  timestamp=$(date +%Y%m%d_%H%M%S)
  archive="${BLOG_BACKUP_DIR}/blog_${timestamp}.tar.gz"
  archive_tmp="${archive}.tmp"
  if ! stage=$(mktemp -d "${BLOG_BACKUP_DIR}/.blog-backup.XXXXXX"); then
    error "$(t app.blog.backup.error_dir "$BLOG_BACKUP_DIR")"
  fi

  _backup_dir_into_stage() {
    local source="$1" target_name="$2"
    if [[ ! -d "$source" ]]; then
      warn "$(t app.blog.backup.warn_missing "$source")"
      return 0
    fi
    if ! mkdir -p "${stage}/${target_name}" || ! cp -a "${source}/." "${stage}/${target_name}/"; then
      rm -rf "$stage" "$archive_tmp"
      error "$(t app.blog.backup.error_archive "$archive")"
    fi
    copied=true
  }

  _backup_file_into_stage() {
    local source="$1" target_name="$2"
    if [[ ! -f "$source" ]]; then
      warn "$(t app.blog.backup.warn_missing "$source")"
      return 0
    fi
    if ! cp -a "$source" "${stage}/${target_name}"; then
      rm -rf "$stage" "$archive_tmp"
      error "$(t app.blog.backup.error_archive "$archive")"
    fi
    copied=true
  }

  _backup_dir_into_stage "$SITE_DIR" site
  _backup_dir_into_stage "$PUBLIC_DIR" public
  _backup_dir_into_stage "$NGINX_ROOT" nginx-root
  _backup_file_into_stage /etc/nginx/sites-available/blog nginx-site.conf
  _backup_file_into_stage /usr/local/bin/blog-publish blog-publish

  if [[ "$copied" != "true" ]]; then
    rm -rf "$stage" "$archive_tmp"
    error "$(t app.blog.backup.error_no_sources)"
  fi
  if ! tar -czf "$archive_tmp" -C "$stage" .; then
    rm -rf "$stage" "$archive_tmp"
    error "$(t app.blog.backup.error_archive "$archive")"
  fi
  rm -rf "$stage"
  if ! chmod 600 "$archive_tmp" || ! mv "$archive_tmp" "$archive"; then
    rm -f "$archive_tmp"
    error "$(t app.blog.backup.error_archive "$archive")"
  fi
  local digest installed_version=""
  if ! digest="$(backup_write_sha256 "$archive")" \
     || ! backup_write_manifest "$archive" "blog" 1 "$installed_version"; then
    warn "$(t app.blog.backup.warn_integrity "$archive")"
  fi
  success "$(t app.blog.backup.success "$archive")"

  local _keep_days="${BLOG_BACKUP_KEEP_DAYS}"
  [[ "$_keep_days" =~ ^[0-9]+$ ]] || _keep_days=0
  if [[ "$_keep_days" -gt 0 ]]; then
    local old_backup
    while IFS= read -r -d '' old_backup; do
      if rm -f "$old_backup"; then
        info "$(t app.blog.backup.cleaned "$old_backup")"
      else
        warn "$(t app.blog.backup.clean_failed "$old_backup")"
      fi
    done < <(find "$BLOG_BACKUP_DIR" -maxdepth 1 -name 'blog_*.tar.gz' -type f -mtime "+${_keep_days}" -print0 2>/dev/null)
  fi
}

_blog_latest_backup_archive() {
  local backup_dir="$1" candidate candidate_mtime latest="" latest_mtime=0
  while IFS= read -r -d '' candidate; do
    candidate_mtime=$(stat -c %Y "$candidate" 2>/dev/null || echo 0)
    if [[ "$candidate_mtime" =~ ^[0-9]+$ && "$candidate_mtime" -gt "$latest_mtime" ]]; then
      latest="$candidate"
      latest_mtime="$candidate_mtime"
    fi
  done < <(find "$backup_dir" -maxdepth 1 -name 'blog_*.tar.gz' -type f -print0 2>/dev/null)
  printf '%s' "$latest"
}

do_verify() {
  show_banner
  require_root "verify"
  _blog_load_config_if_root
  step "$(t backup.verify.step)"
  require_safe_path "BLOG_BACKUP_DIR" "$BLOG_BACKUP_DIR"
  [[ -d "$BLOG_BACKUP_DIR" ]] || error "$(t app.blog.restore.no_backups "$BLOG_BACKUP_DIR")"
  app_verify_latest_backup "$BLOG_BACKUP_DIR" 'blog_*.tar.gz'
}

_blog_archive_paths_are_safe() {
  local archive="$1" member
  tar -tzf "$archive" | while IFS= read -r member; do
    case "$member" in
      ""|/*|*'/../'*|../*|*'/..'|..|*"\\"*)
        return 1
        ;;
    esac
  done
}

_blog_restore_dir_from_backup() {
  local source_dir="$1" target_name="$2" target_path="$3"
  local target_parent target_base restore_tmp restore_bak
  require_safe_path "$target_name" "$target_path"
  target_parent="$(dirname "$target_path")"
  target_base="$(basename "$target_path")"
  if ! mkdir -p "$target_parent"; then
    error "$(t app.blog.restore.error_target "$target_path")"
  fi
  if ! restore_tmp=$(mktemp -d "${target_parent}/.${target_base}.restore.XXXXXX"); then
    error "$(t app.blog.restore.error_target "$target_path")"
  fi
  restore_bak="${target_path}.restore.$(date +%Y%m%d%H%M%S)"
  if ! cp -a "${source_dir}/." "$restore_tmp/"; then
    rm -rf "$restore_tmp"
    error "$(t app.blog.restore.error_target "$target_path")"
  fi
  if [[ -e "$target_path" || -L "$target_path" ]]; then
    if ! mv "$target_path" "$restore_bak"; then
      rm -rf "$restore_tmp"
      error "$(t app.blog.restore.error_target "$target_path")"
    fi
  fi
  if mv "$restore_tmp" "$target_path"; then
    rm -rf "$restore_bak"
    success "$(t app.blog.restore.restored_dir "$target_path")"
  else
    rm -rf "$restore_tmp"
    if [[ -e "$restore_bak" || -L "$restore_bak" ]]; then
      mv "$restore_bak" "$target_path" 2>/dev/null || true
    fi
    error "$(t app.blog.restore.error_target "$target_path")"
  fi
}

_blog_restore_file_from_backup() {
  local source_file="$1" target_name="$2" target_path="$3" mode="$4"
  require_safe_path "$target_name" "$target_path"
  if ! atomic_copy_file "$source_file" "$target_path" "$mode" root:root; then
    error "$(t app.blog.restore.error_target "$target_path")"
  fi
  success "$(t app.blog.restore.restored_file "$target_path")"
}

do_restore() {
  show_banner
  require_root "restore"
  _blog_load_config_if_root
  acquire_lock
  step "$(t app.blog.step_restore)"
  require_safe_path "BLOG_BACKUP_DIR" "$BLOG_BACKUP_DIR"
  local backup_dir="${BLOG_BACKUP_DIR%/}" archive extract_dir restored=false
  [[ -d "$backup_dir" ]] || error "$(t app.blog.restore.no_backups "$backup_dir")"
  archive="${BLOG_RESTORE_ARCHIVE:-}"
  if [[ -z "$archive" ]]; then
    archive="$(_blog_latest_backup_archive "$backup_dir")"
  fi
  [[ -n "$archive" ]] || error "$(t app.blog.restore.no_backups "$backup_dir")"
  [[ "$archive" == "$backup_dir"/blog_*.tar.gz && -f "$archive" ]] \
    || error "$(t app.blog.restore.invalid_archive "$archive")"
  if ! _blog_archive_paths_are_safe "$archive"; then
    error "$(t app.blog.restore.invalid_archive "$archive")"
  fi
  info "$(t app.blog.restore.using "$archive")"
  if ! extract_dir=$(mktemp -d "${backup_dir}/.blog-restore.XXXXXX"); then
    error "$(t app.blog.restore.error_extract "$archive")"
  fi
  if ! tar -xzf "$archive" -C "$extract_dir" >&2; then
    rm -rf "$extract_dir"
    error "$(t app.blog.restore.error_extract "$archive")"
  fi

  if [[ -d "${extract_dir}/site" ]]; then
    _blog_restore_dir_from_backup "${extract_dir}/site" "SITE_DIR" "$SITE_DIR"
    restored=true
  else
    warn "$(t app.blog.restore.warn_missing site)"
  fi
  if [[ -d "${extract_dir}/public" ]]; then
    _blog_restore_dir_from_backup "${extract_dir}/public" "PUBLIC_DIR" "$PUBLIC_DIR"
    restored=true
  else
    warn "$(t app.blog.restore.warn_missing public)"
  fi
  if [[ -d "${extract_dir}/nginx-root" ]]; then
    _blog_restore_dir_from_backup "${extract_dir}/nginx-root" "NGINX_ROOT" "$NGINX_ROOT"
    restored=true
  else
    warn "$(t app.blog.restore.warn_missing nginx-root)"
  fi
  if [[ -f "${extract_dir}/nginx-site.conf" ]]; then
    _blog_restore_file_from_backup "${extract_dir}/nginx-site.conf" "NGINX_SITE" /etc/nginx/sites-available/blog 644
    app_write_nginx_site_link /etc/nginx/sites-available/blog /etc/nginx/sites-enabled/blog "app.blog.error.nginx_write"
    restored=true
  else
    warn "$(t app.blog.restore.warn_missing nginx-site.conf)"
  fi
  if [[ -f "${extract_dir}/blog-publish" ]]; then
    _blog_restore_file_from_backup "${extract_dir}/blog-publish" "BLOG_PUBLISH" /usr/local/bin/blog-publish 750
    restored=true
  else
    warn "$(t app.blog.restore.warn_missing blog-publish)"
  fi
  rm -rf "$extract_dir"
  [[ "$restored" == "true" ]] || error "$(t app.blog.restore.invalid_archive "$archive")"

  if command -v nginx >/dev/null 2>&1; then
    if nginx -t; then
      if systemctl reload nginx; then
        success "$(t app.blog.restore.nginx_reloaded)"
      else
        warn "$(t app.blog.restore.nginx_reload_failed)"
      fi
    else
      error "$(t app.blog.restore.error_nginx_config)"
    fi
  else
    warn "$(t app.blog.restore.nginx_missing)"
  fi
  success "$(t app.blog.restore.success)"
}

_blog_remove_file() {
  local path="$1"
  [[ -e "$path" || -L "$path" ]] || return 0
  if rm -f "$path"; then
    success "$(t app.blog.uninstall.removed_file "$path")"
  else
    error "$(t app.blog.uninstall.remove_failed "$path")"
  fi
}

_blog_remove_dir() {
  local name="$1" path="$2"
  [[ -e "$path" || -L "$path" ]] || return 0
  if safe_rm_dir "$path" "$name"; then
    success "$(t app.blog.uninstall.removed_dir "$path")"
  else
    error "$(t app.blog.uninstall.remove_failed "$path")"
  fi
}

do_uninstall() {
  show_banner
  require_root "uninstall"
  _blog_load_config_if_root
  acquire_lock
  require_safe_path "SITE_DIR" "$SITE_DIR"
  require_safe_path "PUBLIC_DIR" "$PUBLIC_DIR"
  require_safe_path "NGINX_ROOT" "$NGINX_ROOT"
  require_safe_path "BLOG_BACKUP_DIR" "$BLOG_BACKUP_DIR"

  warn "$(t app.blog.uninstall.warning)"
  local confirm delete_backups
  if deploy_assume_yes; then
    confirm="YES"
  else
    prompt "$(t app.blog.uninstall.continue_prompt)"
    read -r confirm
  fi
  [[ "$confirm" == "YES" ]] || { info "$(t app.blog.uninstall.cancelled)"; exit 0; }
  if deploy_assume_yes; then
    if deploy_env_truthy DEPLOY_DELETE_BACKUP; then
      delete_backups="yes"
    else
      delete_backups="no"
    fi
  else
    prompt "$(t app.blog.uninstall.delete_backups_prompt "$BLOG_BACKUP_DIR")"
    read -r delete_backups
  fi

  _blog_remove_file /etc/nginx/sites-enabled/blog
  _blog_remove_file /etc/nginx/sites-available/blog
  app_nginx_default_site_restore
  _blog_remove_file /usr/local/bin/blog-publish
  _blog_remove_dir "PUBLIC_DIR" "$PUBLIC_DIR"
  _blog_remove_dir "NGINX_ROOT" "$NGINX_ROOT"
  _blog_remove_dir "SITE_DIR" "$SITE_DIR"

  if [[ "${delete_backups,,}" == "y" || "${delete_backups,,}" == "yes" ]]; then
    _blog_remove_dir "BLOG_BACKUP_DIR" "$BLOG_BACKUP_DIR"
  else
    info "$(t app.blog.uninstall.kept_backups "$BLOG_BACKUP_DIR")"
  fi

  if command -v nginx >/dev/null 2>&1 && command -v systemctl >/dev/null 2>&1; then
    if nginx -t >/dev/null 2>&1; then
      if systemctl reload nginx >/dev/null 2>&1; then
        success "$(t app.blog.uninstall.nginx_reloaded)"
      else
        nginx -t >&2 || true
        warn "$(t app.blog.uninstall.nginx_reload_failed)"
      fi
    else
      nginx -t >&2 || true
      warn "$(t app.blog.uninstall.nginx_test_failed)"
    fi
  fi

  success "$(t app.blog.uninstall.success)"
}
__DEPLOY_APP_IMPL_SCRIPT_END__

__DEPLOY_APP_IMPL_SCRIPT__ install_tickflow_impl.sh
#!/usr/bin/env bash
set -euo pipefail
umask 077

TICKFLOW_DOMAIN="${TICKFLOW_DOMAIN:-}"
TICKFLOW_REPO="${TICKFLOW_REPO:-shy3130/tickflow-stock-panel}"
TICKFLOW_BRANCH="${TICKFLOW_BRANCH:-main}"
# An optional immutable source pin. When set, the installer checks out this
# full git commit instead of following TICKFLOW_BRANCH.
TICKFLOW_COMMIT="${TICKFLOW_COMMIT:-}"
INSTALLED_VERSION="${INSTALLED_VERSION:-}"
TICKFLOW_INSTALL_DIR="${TICKFLOW_INSTALL_DIR:-/opt/tickflow-stock-panel}"
TICKFLOW_DATA_DIR="${TICKFLOW_DATA_DIR:-${TICKFLOW_INSTALL_DIR}/data}"
TICKFLOW_ENV_FILE="${TICKFLOW_ENV_FILE:-${TICKFLOW_INSTALL_DIR}/.env}"
TICKFLOW_COMPOSE_FILE="${TICKFLOW_COMPOSE_FILE:-${TICKFLOW_INSTALL_DIR}/docker-compose.yml}"
TICKFLOW_TIERS_FILE="${TICKFLOW_TIERS_FILE:-${TICKFLOW_INSTALL_DIR}/tiers.yaml}"
TICKFLOW_SERVICE_NAME="${TICKFLOW_SERVICE_NAME:-tickflow-stock-panel}"
TICKFLOW_PORT="${TICKFLOW_PORT:-3018}"
TICKFLOW_LOG_DIR="${TICKFLOW_LOG_DIR:-${TICKFLOW_INSTALL_DIR}/logs}"
TICKFLOW_AUTH_PASSWORD="${TICKFLOW_AUTH_PASSWORD:-}"
# Bind address for the container port mapping. 127.0.0.1 by default: the
# panel has no authentication unless TICKFLOW_AUTH_PASSWORD is set, so
# publishing it on 0.0.0.0 would expose an unauthenticated stock panel to the
# network. Put it behind an HTTPS reverse proxy instead.
TICKFLOW_BIND_ADDR="${TICKFLOW_BIND_ADDR:-127.0.0.1}"
TICKFLOW_BACKEND_EXTRAS="${TICKFLOW_BACKEND_EXTRAS:-}"

CONFIG_KEYS=(
  TICKFLOW_DOMAIN TICKFLOW_REPO TICKFLOW_BRANCH TICKFLOW_COMMIT INSTALLED_VERSION TICKFLOW_INSTALL_DIR
  TICKFLOW_DATA_DIR TICKFLOW_ENV_FILE TICKFLOW_COMPOSE_FILE TICKFLOW_TIERS_FILE
  TICKFLOW_SERVICE_NAME TICKFLOW_PORT TICKFLOW_LOG_DIR TICKFLOW_AUTH_PASSWORD
  TICKFLOW_BIND_ADDR
  TICKFLOW_BACKEND_EXTRAS
)

# Backward-compat: check for old-style config path.
app_conf_register_legacy "/etc/tickflow-deploy.conf"
CONF_FILE="$(app_conf_file)"
LOCK_FILE="$(app_lock_file)"

_tickflow_doctor_service_name() {
  printf '%s\n' "$TICKFLOW_SERVICE_NAME"
}
APP_DOCTOR_SERVICE_FN=_tickflow_doctor_service_name
# Central check-update adapter. A configured full commit is an immutable
# target and therefore compares locally without querying a moving branch;
# otherwise TickFlow retains its branch-following update behavior.
_tickflow_check_update_json() {
  local conf_file
  conf_file="$(app_conf_file 2>/dev/null || true)"
  [[ -n "$conf_file" && -f "$conf_file" ]] && load_config_file "$conf_file" "${CONFIG_KEYS[@]}"
  if [[ -n "${TICKFLOW_COMMIT:-}" ]]; then
    version_check_git_commit_json "$TICKFLOW_INSTALL_DIR" "$TICKFLOW_COMMIT"
  else
    version_check_git_branch_json "$TICKFLOW_INSTALL_DIR" "${TICKFLOW_BRANCH:-main}" "${3:-0}"
  fi
}
APP_CHECK_UPDATE_FN=_tickflow_check_update_json

_tickflow_status_version_json() {
  local conf_file
  conf_file="$(app_conf_file 2>/dev/null || true)"
  [[ -n "$conf_file" && -f "$conf_file" ]] && load_config_file "$conf_file" "${CONFIG_KEYS[@]}"
  if [[ -n "${TICKFLOW_COMMIT:-}" ]]; then
    version_check_git_commit_json "$TICKFLOW_INSTALL_DIR" "$TICKFLOW_COMMIT"
  else
    version_check_git_branch_json "$TICKFLOW_INSTALL_DIR" "${TICKFLOW_BRANCH:-main}" 1
  fi
}
APP_STATUS_VERSION_FN=_tickflow_status_version_json

_tickflow_status_backup() {
  local install_dir="${TICKFLOW_INSTALL_DIR:-}" backup_dir configured_dir
  if configured_dir="$(app_conf_trusted_value "$(app_conf_file 2>/dev/null || true)" "TICKFLOW_INSTALL_DIR")"; then
    install_dir="$configured_dir"
  fi
  if [[ -z "$install_dir" ]] || ! is_safe_path "$install_dir"; then
    printf '{"state":"unknown","last_success_at":null,"path":null,"message":"install directory is unsafe or missing"}'
    return
  fi
  backup_dir="${install_dir}-backups"
  if ! is_safe_path "$backup_dir"; then
    printf '{"state":"unknown","last_success_at":null,"path":null,"message":"backup directory is unsafe"}'
    return
  fi
  if [[ ! -d "$backup_dir" ]]; then
    printf '{"state":"missing","last_success_at":null,"path":%s,"message":"backup directory is missing"}' "$(app_json_string "$backup_dir")"
    return
  fi
  app_backup_latest_archive_json "$backup_dir" 'tickflow-data-*.tar.gz'
}
APP_STATUS_BACKUP_FN=_tickflow_status_backup

preflight_check() {
  [[ "${1:-}" == "status" || $EUID -eq 0 ]] || error "$(t error.root_required "$0" "${1:-}")"
  command -v apt-get >/dev/null 2>&1 || error "$(t app.tickflow.error.apt_only)"
  command -v systemctl >/dev/null 2>&1 || error "$(t app.tickflow.error.systemd_required)"
  case "$(uname -m)" in
    x86_64|aarch64|arm64) ;;
    *) error "$(t app.tickflow.error.arch "$(uname -m)")" ;;
  esac
  _validate_config_values
}

check_connectivity() {
  app_check_connectivity app.tickflow.error.repo_unreachable \
    "https://github.com" \
    "https://api.github.com"
}

_validate_config_values() {
  app_validate_port "$TICKFLOW_PORT" "TICKFLOW_PORT"
  app_validate_domain "TICKFLOW_DOMAIN" "$TICKFLOW_DOMAIN"
  app_validate_systemd_name "TICKFLOW_SERVICE_NAME" "$TICKFLOW_SERVICE_NAME"
  app_validate_github_repo "TICKFLOW_REPO" "$TICKFLOW_REPO"
  app_validate_git_ref "TICKFLOW_BRANCH" "$TICKFLOW_BRANCH"
  if [[ -n "$TICKFLOW_COMMIT" ]] && ! [[ "$TICKFLOW_COMMIT" =~ ^[A-Fa-f0-9]{40}$ ]]; then
    error "$(t app.tickflow.error.commit_invalid "$TICKFLOW_COMMIT")"
  fi
  require_safe_path "TICKFLOW_INSTALL_DIR" "$TICKFLOW_INSTALL_DIR"
  require_safe_path "TICKFLOW_DATA_DIR" "$TICKFLOW_DATA_DIR"
  require_safe_path "TICKFLOW_LOG_DIR" "$TICKFLOW_LOG_DIR"
  require_safe_path "TICKFLOW_ENV_FILE" "$TICKFLOW_ENV_FILE"
  require_safe_path "TICKFLOW_COMPOSE_FILE" "$TICKFLOW_COMPOSE_FILE"
  require_safe_path "TICKFLOW_TIERS_FILE" "$TICKFLOW_TIERS_FILE"
  if [[ -n "$TICKFLOW_AUTH_PASSWORD" ]] && [[ ${#TICKFLOW_AUTH_PASSWORD} -lt 6 ]]; then
    error "$(t app.tickflow.error.auth_password_short)"
  fi
  case "${TICKFLOW_BIND_ADDR:-127.0.0.1}" in
    127.0.0.1|0.0.0.0|::1|::) : ;;
    *) error "$(t app.tickflow.error.bind_addr "${TICKFLOW_BIND_ADDR:-unset}")" ;;
  esac
  app_enforce_secure_public_bind "${TICKFLOW_BIND_ADDR:-127.0.0.1}" 0 "TickFlow"
}

_compose_bin() {
  compose_command
}

_require_compose_runtime() {
  compose_require_runtime
}

_env_value_from_file() {
  local key="$1"
  local env_file="${2:-$TICKFLOW_ENV_FILE}"
  local line value
  [[ -f "$env_file" ]] || return 1

  while IFS= read -r line || [[ -n "$line" ]]; do
    line="${line%$'\r'}"
    [[ "$line" == "${key}="* ]] || continue
    value="${line#*=}"
    if [[ "$value" =~ ^\"(.*)\"$ ]]; then
      value="${BASH_REMATCH[1]}"
    fi
    printf '%s' "$value"
    return 0
  done < "$env_file"

  return 1
}

_tickflow_record_installed_version() {
  local revision
  revision="$(git -C "$TICKFLOW_INSTALL_DIR" rev-parse --verify HEAD 2>/dev/null || true)"
  if ! [[ "$revision" =~ ^[A-Fa-f0-9]{40}$ ]]; then
    error "$(t app.tickflow.error.installed_version "$TICKFLOW_INSTALL_DIR")"
  fi
  INSTALLED_VERSION="$revision"
}

_tickflow_checkout_pinned_commit() {
  local repo_dir="$1"
  info "$(t app.tickflow.info.repo_pinned "$TICKFLOW_COMMIT")"
  git -C "$repo_dir" fetch --quiet --depth 1 origin "$TICKFLOW_COMMIT" \
    || error "$(t app.tickflow.error.commit_fetch "$TICKFLOW_COMMIT" "$TICKFLOW_REPO")"
  git -C "$repo_dir" checkout --detach "$TICKFLOW_COMMIT" \
    || error "$(t app.tickflow.error.commit_checkout "$TICKFLOW_COMMIT" "$repo_dir")"
}

_clone_or_update_repo() {
  local parent repo_dir
  parent="$(dirname "$TICKFLOW_INSTALL_DIR")"
  repo_dir="$TICKFLOW_INSTALL_DIR"
  require_safe_path "TICKFLOW_INSTALL_DIR" "$repo_dir"
  if ! mkdir -p "$parent"; then
    error "$(t app.tickflow.error.install_parent_dir "$parent")"
  fi
  if [[ -d "$repo_dir/.git" ]]; then
    if [[ -n "$TICKFLOW_COMMIT" ]]; then
      _tickflow_checkout_pinned_commit "$repo_dir"
    else
      info "$(t app.tickflow.info.repo_exists "$TICKFLOW_BRANCH")"
      git -C "$repo_dir" fetch --prune origin "$TICKFLOW_BRANCH" || error "$(t app.tickflow.error.repo_update "$repo_dir")"
      git -C "$repo_dir" checkout "$TICKFLOW_BRANCH" || error "$(t app.tickflow.error.repo_update "$repo_dir")"
      git -C "$repo_dir" pull --ff-only origin "$TICKFLOW_BRANCH" || error "$(t app.tickflow.error.repo_update "$repo_dir")"
    fi
  else
    if [[ -e "$repo_dir" || -L "$repo_dir" ]]; then
      error "$(t app.tickflow.error.install_dir_not_repo "$repo_dir")"
    fi
    if [[ -n "$TICKFLOW_COMMIT" ]]; then
      git init -q "$repo_dir" || error "$(t app.tickflow.error.repo_clone "$TICKFLOW_REPO" "$repo_dir")"
      git -C "$repo_dir" remote add origin "https://github.com/${TICKFLOW_REPO}.git" \
        || error "$(t app.tickflow.error.repo_clone "$TICKFLOW_REPO" "$repo_dir")"
      _tickflow_checkout_pinned_commit "$repo_dir"
    else
      git clone --depth 1 --branch "$TICKFLOW_BRANCH" "https://github.com/${TICKFLOW_REPO}.git" "$repo_dir" \
        || error "$(t app.tickflow.error.repo_clone "$TICKFLOW_REPO" "$repo_dir")"
    fi
  fi
  _tickflow_record_installed_version
  success "$(t app.tickflow.success.source_ready "$repo_dir")"
}

_ensure_data_layout() {
  if ! mkdir -p "$TICKFLOW_DATA_DIR" "$TICKFLOW_LOG_DIR"; then
    error "$(t app.tickflow.error.runtime_dirs "$TICKFLOW_DATA_DIR" "$TICKFLOW_LOG_DIR")"
  fi
  if [[ ! -f "$TICKFLOW_TIERS_FILE" ]]; then
    atomic_write_file "$TICKFLOW_TIERS_FILE" 644 <<'EOF' \
      || error "$(t app.tickflow.error.tiers_write "$TICKFLOW_TIERS_FILE")"
# Managed by deploy-scripts.
# This file is required by tickflow-stock-panel docker compose.
EOF
  fi
}

_write_env_file() {
  local tickflow_api_key=""
  local ai_provider="openai_compat"
  local ai_base_url="https://api.deepseek.com/v1"
  local ai_api_key=""
  local ai_model="deepseek-chat"
  local ai_daily_token_budget="500000"
  local log_level="INFO"
  local auth_password="${TICKFLOW_AUTH_PASSWORD:-}"
  local existing_value
  mkdir -p "$(dirname "$TICKFLOW_ENV_FILE")"
  if existing_value="$(_env_value_from_file TICKFLOW_API_KEY)"; then
    tickflow_api_key="$existing_value"
  fi
  if existing_value="$(_env_value_from_file AI_PROVIDER)"; then
    ai_provider="$existing_value"
  fi
  if existing_value="$(_env_value_from_file AI_BASE_URL)"; then
    ai_base_url="$existing_value"
  fi
  if existing_value="$(_env_value_from_file AI_API_KEY)"; then
    ai_api_key="$existing_value"
  fi
  if existing_value="$(_env_value_from_file AI_MODEL)"; then
    ai_model="$existing_value"
  fi
  if existing_value="$(_env_value_from_file AI_DAILY_TOKEN_BUDGET)"; then
    ai_daily_token_budget="$existing_value"
  fi
  if existing_value="$(_env_value_from_file LOG_LEVEL)"; then
    log_level="$existing_value"
  fi
  # Password precedence: an explicit TICKFLOW_AUTH_PASSWORD wins (the user is
  # deliberately rotating it); otherwise keep an existing AUTH_PASSWORD from a
  # previous install; otherwise generate a random one. Never leave the panel
  # unauthenticated.
  if [[ -z "$auth_password" ]]; then
    if existing_value="$(_env_value_from_file AUTH_PASSWORD)"; then
      auth_password="$existing_value"
    fi
  fi
  if [[ -z "$auth_password" ]]; then
    auth_password="$(LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom | head -c 40 || true)"
    if [[ -z "$auth_password" ]]; then
      auth_password="$(openssl rand -hex 20 2>/dev/null || true)"
    fi
    [[ -n "$auth_password" ]] || error "$(t app.tickflow.error.env_write "$TICKFLOW_ENV_FILE")"
  fi
  atomic_write_file "$TICKFLOW_ENV_FILE" 600 <<EOF \
    || error "$(t app.tickflow.error.env_write "$TICKFLOW_ENV_FILE")"
TICKFLOW_API_KEY=${tickflow_api_key}
AI_PROVIDER=${ai_provider}
AI_BASE_URL=${ai_base_url}
AI_API_KEY=${ai_api_key}
AI_MODEL=${ai_model}
AI_DAILY_TOKEN_BUDGET=${ai_daily_token_budget}
HOST=0.0.0.0
PORT=${TICKFLOW_PORT}
LOG_LEVEL=${log_level}
AUTH_PASSWORD=${auth_password}
BACKEND_EXTRAS=${TICKFLOW_BACKEND_EXTRAS}
DATA_DIR=./data
EOF
}

_write_compose_file() {
  atomic_write_file "$TICKFLOW_COMPOSE_FILE" 644 <<EOF \
    || error "$(t app.tickflow.error.compose_write "$TICKFLOW_COMPOSE_FILE")"
services:
  app:
    build:
      context: .
      dockerfile: Dockerfile
      args:
        BACKEND_EXTRAS: ${BACKEND_EXTRAS:-}
    container_name: TickFlow_Stock_Panel
    ports:
      - "${TICKFLOW_BIND_ADDR:-127.0.0.1}:${TICKFLOW_PORT}:3018"
    env_file:
      - .env
    volumes:
      - ./data:/app/data
      - ./tiers.yaml:/app/tiers.yaml:ro
    restart: unless-stopped
EOF
}

_write_systemd_unit() {
  local unit_path="/etc/systemd/system/${TICKFLOW_SERVICE_NAME}.service"
  local compose_cmd install_dir_literal compose_file_literal
  compose_cmd="$(compose_command)"
  printf -v install_dir_literal '%q' "$TICKFLOW_INSTALL_DIR"
  printf -v compose_file_literal '%q' "$TICKFLOW_COMPOSE_FILE"
  if ! systemd_write_unit "$unit_path" <<EOF
[Unit]
Description=TickFlow Stock Panel
After=network-online.target docker.service
Wants=network-online.target docker.service

[Service]
Type=oneshot
RemainAfterExit=yes
WorkingDirectory=${TICKFLOW_INSTALL_DIR}
ExecStart=/bin/bash -lc 'cd ${install_dir_literal} && ${compose_cmd} -f ${compose_file_literal} up -d --build'
ExecStop=/bin/bash -lc 'cd ${install_dir_literal} && ${compose_cmd} -f ${compose_file_literal} down'
ExecReload=/bin/bash -lc 'cd ${install_dir_literal} && ${compose_cmd} -f ${compose_file_literal} up -d --build'
TimeoutStartSec=0
TimeoutStopSec=120

[Install]
WantedBy=multi-user.target
EOF
  then
    error "$(t app.tickflow.error.service_write "$unit_path")"
  fi
  systemctl daemon-reload || error "$(t app.tickflow.error.service_reload "$TICKFLOW_SERVICE_NAME")"
  success "$(t app.tickflow.success.systemd "$TICKFLOW_SERVICE_NAME")"
}

_print_service_diagnostics() {
  warn "$(t app.tickflow.warn.service_diagnostics)"
  systemctl status "$TICKFLOW_SERVICE_NAME" --no-pager -l 2>/dev/null \
    | head -20 | sed 's/^/  /' >&2 || true
}

_print_status_path() {
  local label="$1" path="$2"
  if [[ -e "$path" ]]; then
    echo -e "  ${GREEN}[✓]${NC} $(t app.tickflow.status.path_ok "$label" "$path")"
  else
    echo -e "  ${YELLOW}[!]${NC} $(t app.tickflow.status.path_missing "$label" "$path")"
  fi
}

_health_check() {
  local code elapsed=0
  until code=$(curl -o /dev/null -s -w "%{http_code}" --max-time 5 "http://127.0.0.1:${TICKFLOW_PORT}/" 2>/dev/null || echo 000) \
      && [[ "$code" =~ ^(200|301|302)$ ]]; do
    sleep 1
    elapsed=$((elapsed + 1))
    [[ $elapsed -ge 20 ]] && break
  done
  if [[ "$code" =~ ^(200|301|302)$ ]]; then
    success "$(t app.tickflow.success.health "$code")"
    return 0
  fi
  warn "$(t app.tickflow.warn.health "$code")"
  return 1
}

_print_summary() {
  local state="$1"
  local internal_ip
  internal_ip="$(hostname -I 2>/dev/null | awk '{print $1}' || true)"
  internal_ip="${internal_ip:-YOUR_SERVER_IP}"
  echo ""
  echo -e "${BOLD}${GREEN}"
  echo "  ╔══════════════════════════════════════════════════════╗"
  if [[ "$state" == "pending" ]]; then
    printf "  ║               %s                     ║\n" "$(t app.tickflow.summary.title_pending)"
  else
    printf "  ║               %s                     ║\n" "$(t app.tickflow.summary.title_ready)"
  fi
  echo "  ╠══════════════════════════════════════════════════════╣"
  if [[ -n "$TICKFLOW_DOMAIN" ]]; then
    echo -e "  ║  $(t app.tickflow.summary.public)  ${CYAN}http://${TICKFLOW_DOMAIN}${GREEN}"
  fi
  echo -e "  ║  $(t app.tickflow.summary.internal)  ${CYAN}http://${internal_ip}:${TICKFLOW_PORT}${GREEN}"
  echo "  ╠══════════════════════════════════════════════════════╣"
  echo -e "  ║  $(t app.tickflow.summary.repo)  ${YELLOW}${TICKFLOW_REPO}${GREEN}"
  echo -e "  ║  $(t app.tickflow.summary.compose)  ${YELLOW}${TICKFLOW_INSTALL_DIR}${GREEN}"
  echo -e "  ║  $(t app.tickflow.summary.data)  ${YELLOW}${TICKFLOW_DATA_DIR}${GREEN}"
  echo -e "  ║  $(t app.tickflow.summary.env)  ${YELLOW}${TICKFLOW_ENV_FILE}${GREEN}"
  echo "  ╠══════════════════════════════════════════════════════╣"
  echo -e "  ║  $(t app.tickflow.summary.auth_file)  ${YELLOW}${TICKFLOW_ENV_FILE}${GREEN}"
  echo -e "  ║  ${RED}${BOLD}$(t app.tickflow.summary.auth_warning "$TICKFLOW_ENV_FILE")${GREEN}"
  echo "  ╚══════════════════════════════════════════════════════╝"
  echo -e "${NC}"
  echo -e "  ${BOLD}$(t app.tickflow.summary.systemd)${NC}"
  echo ""
  echo -e "  ${CYAN}systemctl status ${TICKFLOW_SERVICE_NAME}${NC}      $(t app.tickflow.summary.status_cmd)"
  echo -e "  ${CYAN}journalctl -u ${TICKFLOW_SERVICE_NAME} -f${NC}      $(t app.tickflow.summary.logs_cmd)"
  echo -e "  ${CYAN}systemctl restart ${TICKFLOW_SERVICE_NAME}${NC}     $(t app.tickflow.summary.restart_cmd)"
}

tickflow_remove_dir_or_error() {
  app_remove_dir_or_error "$1" "$2" "$3" "app.tickflow.error.remove_dir"
}

tickflow_remove_file_or_error() {
  app_remove_file_or_error "$1" "$2" "app.tickflow.error.remove_file"
}

do_install() {
  show_banner
  preflight_check "install"
  acquire_lock
  step "$(t app.tickflow.step.deps)"
  if ! apt-get update -qq; then
    warn "$(t app.tickflow.warn.apt_update)"
  fi
  if ! apt-get install -y -qq git curl ca-certificates docker.io docker-compose-plugin; then
    if ! apt-get install -y -qq git curl ca-certificates docker.io docker-compose; then
      error "$(t app.tickflow.error.deps_install)"
    fi
  fi
  if ! systemctl enable --now docker >/dev/null 2>&1; then
    warn "$(t app.tickflow.warn.docker_enable_failed)"
  fi
  _require_compose_runtime
  success "$(t app.tickflow.success.deps)"
  step "$(t app.tickflow.step.fetch_source)"
  _clone_or_update_repo
  step "$(t app.tickflow.step.config)"
  _ensure_data_layout
  _write_env_file
  _write_compose_file
  success "$(t app.tickflow.success.config)"
  step "$(t app.tickflow.step.systemd)"
  _write_systemd_unit
  step "$(t app.tickflow.step.start)"
  app_check_port_conflict "$TICKFLOW_PORT" "TICKFLOW_PORT"
  if ! systemctl enable "$TICKFLOW_SERVICE_NAME" >/dev/null 2>&1; then
    warn "$(t app.tickflow.warn.service_enable_failed "$TICKFLOW_SERVICE_NAME" "$TICKFLOW_SERVICE_NAME")"
  fi
  if ! systemctl start "$TICKFLOW_SERVICE_NAME"; then
    _print_service_diagnostics
    error "$(t app.tickflow.error.service_start "$TICKFLOW_SERVICE_NAME")"
  fi
  success "$(t app.tickflow.success.started)"
  local state="ready"
  if ! _health_check; then
    state="pending"
  fi
  app_save_config
  _print_summary "$state"
}

do_update() {
  show_banner
  preflight_check "update"
  acquire_lock
  app_load_config
  _validate_config_values
  _require_compose_runtime
  step "$(t app.tickflow.step.fetch_source)"
  _clone_or_update_repo
  step "$(t app.tickflow.step.config)"
  _ensure_data_layout
  _write_env_file
  _write_compose_file
  step "$(t app.tickflow.step.start)"
  app_check_port_conflict "$TICKFLOW_PORT" "TICKFLOW_PORT"
  if ! systemctl restart "$TICKFLOW_SERVICE_NAME"; then
    _print_service_diagnostics
    error "$(t app.tickflow.error.service_start "$TICKFLOW_SERVICE_NAME")"
  fi
  local state="ready"
  if ! _health_check; then
    state="pending"
  fi
  app_save_config
  _print_summary "$state"
}

do_backup() {
  show_banner
  preflight_check "backup"
  acquire_lock
  app_load_config
  require_safe_path "TICKFLOW_INSTALL_DIR" "$TICKFLOW_INSTALL_DIR"
  local backup_dir="${TICKFLOW_INSTALL_DIR}-backups"
  require_safe_path "TICKFLOW_BACKUP_DIR" "$backup_dir"
  if ! mkdir -p "$backup_dir"; then
    error "$(t app.tickflow.backup.error_dir "$backup_dir")"
  fi
  local backup_source
  for backup_source in data tiers.yaml .env; do
    if [[ ! -e "${TICKFLOW_INSTALL_DIR}/${backup_source}" ]]; then
      error "$(t app.tickflow.backup.error_source_missing "${TICKFLOW_INSTALL_DIR}/${backup_source}")"
    fi
  done
  local archive
  archive="${backup_dir}/tickflow-data-$(date +%Y%m%d%H%M%S).tar.gz"
  local archive_tmp="${archive}.tmp"
  if ! tar -czf "$archive_tmp" -C "$TICKFLOW_INSTALL_DIR" data tiers.yaml .env >&2; then
    rm -f "$archive_tmp"
    error "$(t app.tickflow.backup.error_archive "$archive")"
  fi
  if ! chmod 600 "$archive_tmp" || ! mv "$archive_tmp" "$archive"; then
    rm -f "$archive_tmp"
    error "$(t app.tickflow.backup.error_archive "$archive")"
  fi
  # Integrity metadata: a sha256 sidecar plus a manifest, so do_verify and the
  # shared status projection can confirm the archive instead of reporting it
  # as unverified forever. Best-effort on failure — the archive itself exists.
  if ! backup_write_sha256 "$archive" >/dev/null \
     || ! backup_write_manifest "$archive" "$APP_ID" 1 "${INSTALLED_VERSION:-}"; then
    warn "$(t app.tickflow.warn.integrity_failed "$archive")"
  fi
  success "$(t app.tickflow.backup.success "$archive")"
}

do_status() {
  show_banner
  preflight_check "status"
  app_load_config
  [[ $EUID -ne 0 ]] && warn "$(t app.tickflow.warn.non_root_status "$0")"
  echo -e "\n${BOLD}[$(t app.tickflow.status.systemd)]${NC}"
  if systemctl is-active --quiet "$TICKFLOW_SERVICE_NAME" 2>/dev/null; then
    echo -e "  ${GREEN}[✓]${NC} $(t app.tickflow.status.service_active "$TICKFLOW_SERVICE_NAME")"
  else
    echo -e "  ${RED}[✗]${NC} $(t app.tickflow.status.service_inactive "$TICKFLOW_SERVICE_NAME")"
  fi
  if systemctl is-enabled --quiet "$TICKFLOW_SERVICE_NAME" 2>/dev/null; then
    echo -e "  ${GREEN}[✓]${NC} $(t app.tickflow.status.service_enabled "$TICKFLOW_SERVICE_NAME")"
  else
    echo -e "  ${YELLOW}[!]${NC} $(t app.tickflow.status.service_disabled "$TICKFLOW_SERVICE_NAME")"
  fi
  systemctl status "$TICKFLOW_SERVICE_NAME" --no-pager -l 2>/dev/null \
    | head -12 | sed 's/^/  /' || true
  echo -e "\n${BOLD}[$(t app.tickflow.status.paths)]${NC}"
  _print_status_path "$(t app.tickflow.status.install_dir)" "$TICKFLOW_INSTALL_DIR"
  _print_status_path "$(t app.tickflow.status.data_dir)" "$TICKFLOW_DATA_DIR"
  _print_status_path "$(t app.tickflow.status.env_file)" "$TICKFLOW_ENV_FILE"
  _print_status_path "$(t app.tickflow.status.compose_file)" "$TICKFLOW_COMPOSE_FILE"
  _print_status_path "$(t app.tickflow.status.tiers_file)" "$TICKFLOW_TIERS_FILE"
  _print_status_path "$(t app.tickflow.status.log_dir)" "$TICKFLOW_LOG_DIR"
  echo -e "\n${BOLD}[$(t app.tickflow.status.backups)]${NC}"
  local backup_dir="${TICKFLOW_INSTALL_DIR}-backups"
  if [[ -d "$backup_dir" ]]; then
    local backup_count backup_size
    backup_count=$(find "$backup_dir" -maxdepth 1 -name "tickflow-data-*.tar.gz" -type f 2>/dev/null | wc -l | tr -d ' ' || printf '0')
    backup_size=$(du -sh "$backup_dir" 2>/dev/null | awk '{print $1}' || t status.unknown)
    echo -e "  ${GREEN}[✓]${NC} $(t app.tickflow.status.backup_count "$backup_count" "$backup_size")"
  else
    echo -e "  ${YELLOW}[!]${NC} $(t app.tickflow.status.backup_missing "$backup_dir")"
  fi
  echo -e "\n${BOLD}[$(t app.tickflow.status.http_health)]${NC}"
  if command -v curl >/dev/null 2>&1; then
    local http_code
    http_code=$(curl -o /dev/null -s -w "%{http_code}" --max-time 5 "http://127.0.0.1:${TICKFLOW_PORT}/" 2>/dev/null || echo 000)
    if [[ "$http_code" =~ ^(200|301|302)$ ]]; then
      echo -e "  ${GREEN}[✓]${NC} $(t app.tickflow.status.local_response "$http_code")"
    else
      echo -e "  ${YELLOW}[!]${NC} $(t app.tickflow.status.local_response_warn "$http_code")"
    fi
  else
    echo -e "  ${YELLOW}[!]${NC} $(t app.tickflow.status.curl_missing)"
  fi
  echo ""
}

do_uninstall() {
  show_banner
  preflight_check "uninstall"
  acquire_lock
  app_load_config
  require_safe_path "TICKFLOW_INSTALL_DIR" "$TICKFLOW_INSTALL_DIR"
  local backup_dir="${TICKFLOW_INSTALL_DIR}-backups"
  require_safe_path "TICKFLOW_BACKUP_DIR" "$backup_dir"
  echo -e "${RED}${BOLD}"
  echo "  $(t app.tickflow.uninstall.removes)"
  echo "  $(t app.tickflow.uninstall.keep_install "$TICKFLOW_INSTALL_DIR")"
  echo "  $(t app.tickflow.uninstall.keep_backup "$backup_dir")"
  echo -e "${NC}"
  local confirm
  if deploy_assume_yes; then
    confirm="YES"
  else
    prompt "$(t app.tickflow.prompt.continue)"
    read -r confirm
  fi
  [[ "$confirm" != "YES" ]] && { info "$(t app.tickflow.info.cancelled)"; exit 0; }
  local DELETE_INSTALL=false
  if deploy_assume_yes; then
    deploy_env_truthy DEPLOY_DELETE_INSTALL && DELETE_INSTALL=true
  else
    prompt "$(t app.tickflow.prompt.delete_install "$TICKFLOW_INSTALL_DIR")"
    local delete_install; read -r delete_install
    [[ "${delete_install,,}" == "y" ]] && DELETE_INSTALL=true
  fi
  local DELETE_BACKUP=false
  if deploy_assume_yes; then
    deploy_env_truthy DEPLOY_DELETE_BACKUP && DELETE_BACKUP=true
  else
    prompt "$(t app.tickflow.prompt.delete_backup "$backup_dir")"
    local delete_backup; read -r delete_backup
    [[ "${delete_backup,,}" == "y" ]] && DELETE_BACKUP=true
  fi
  if ! systemctl stop "$TICKFLOW_SERVICE_NAME" >/dev/null 2>&1; then
    if systemctl is-active --quiet "$TICKFLOW_SERVICE_NAME" 2>/dev/null; then
      error "$(t app.tickflow.error.service_stop_failed_active "$TICKFLOW_SERVICE_NAME" "$TICKFLOW_SERVICE_NAME")"
    fi
    warn "$(t app.tickflow.warn.service_stop_failed "$TICKFLOW_SERVICE_NAME" "$TICKFLOW_SERVICE_NAME")"
  fi
  if ! systemctl disable "$TICKFLOW_SERVICE_NAME" >/dev/null 2>&1; then
    warn "$(t app.tickflow.warn.service_disable_failed "$TICKFLOW_SERVICE_NAME" "$TICKFLOW_SERVICE_NAME")"
  fi
  tickflow_remove_file_or_error "/etc/systemd/system/${TICKFLOW_SERVICE_NAME}.service" "TICKFLOW_SERVICE_FILE"
  if ! systemctl daemon-reload; then
    error "$(t app.tickflow.error.service_reload "$TICKFLOW_SERVICE_NAME")"
  fi
  if $DELETE_INSTALL && [[ -e "$TICKFLOW_INSTALL_DIR" || -L "$TICKFLOW_INSTALL_DIR" ]]; then
    tickflow_remove_dir_or_error "$TICKFLOW_INSTALL_DIR" "TICKFLOW_INSTALL_DIR" "$(t app.tickflow.success.deleted_install "$TICKFLOW_INSTALL_DIR")"
  else
    info "$(t app.tickflow.info.kept_install "$TICKFLOW_INSTALL_DIR")"
  fi
  if $DELETE_BACKUP && [[ -e "$backup_dir" || -L "$backup_dir" ]]; then
    tickflow_remove_dir_or_error "$backup_dir" "TICKFLOW_BACKUP_DIR" "$(t app.tickflow.success.deleted_backup "$backup_dir")"
  else
    info "$(t app.tickflow.info.kept_backup "$backup_dir")"
  fi
  tickflow_remove_file_or_error "$CONF_FILE" "CONF_FILE"
  success "$(t app.tickflow.success.removed)"
}

do_verify() {
  show_banner
  require_root "verify"
  app_load_config
  step "$(t backup.verify.step)"
  local backup_dir="${TICKFLOW_INSTALL_DIR}-backups"
  require_safe_path "TICKFLOW_INSTALL_DIR" "$TICKFLOW_INSTALL_DIR"
  require_safe_path "TICKFLOW_BACKUP_DIR" "$backup_dir"
  [[ -d "$backup_dir" ]] || error "$(t backup.verify.no_backups "$backup_dir")"
  app_verify_latest_backup "$backup_dir" 'tickflow-data-*.tar.gz'
}

do_restore() {
  show_banner
  require_root "restore"
  app_load_config
  acquire_lock
  step "$(t backup.restore.step)"
  require_safe_path "TICKFLOW_INSTALL_DIR" "$TICKFLOW_INSTALL_DIR"
  local backup_dir="${TICKFLOW_INSTALL_DIR}-backups"
  require_safe_path "TICKFLOW_BACKUP_DIR" "$backup_dir"
  [[ -d "$backup_dir" ]] || error "$(t backup.restore.no_backups "$backup_dir")"
  local archive
  archive="${TICKFLOW_RESTORE_ARCHIVE:-}"
  if [[ -n "$archive" ]]; then
    [[ "$archive" == "$backup_dir"/tickflow-data-*.tar.gz && -f "$archive" ]] \
      || error "$(t backup.restore.invalid_archive "$archive")"
  else
    archive="$(backup_latest_archive "$backup_dir" 'tickflow-data-*.tar.gz' || true)"
    [[ -n "$archive" ]] || error "$(t backup.restore.no_backups "$backup_dir")"
  fi
  # Verify integrity metadata before touching anything; archives without a
  # sidecar (created before manifests were written) fail closed with guidance.
  if ! backup_verify_archive "$archive"; then
    error "$(t backup.restore.invalid_archive "$(basename "$archive")")"
  fi
  # The archive holds exactly the three members do_backup stores: data/,
  # tiers.yaml, .env — all relative to INSTALL_DIR.
  local member_list member found_data=false found_env=false found_tiers=false
  if ! member_list="$(tar -tzf "$archive" 2>/dev/null)"; then
    error "$(t backup.restore.invalid_archive "$archive")"
  fi
  while IFS= read -r member; do
    case "$member" in
      ""|/*|*'/../'*|../*|*'/..'|..|*"\\"*)
        error "$(t backup.restore.invalid_archive "$(basename "$archive")")"
        ;;
      data|data/*) found_data=true ;;
      .env) found_env=true ;;
      tiers.yaml) found_tiers=true ;;
    esac
  done <<< "$member_list"
  if ! [[ "$found_data" || "$found_env" || "$found_tiers" ]]; then
    error "$(t backup.restore.invalid_archive "$(basename "$archive")")"
  fi
  info "$(t backup.restore.using "$archive")"

  systemctl stop "$TICKFLOW_SERVICE_NAME" \
    || error "$(t backup.restore.stop_failed "$TICKFLOW_SERVICE_NAME")"
  # Aside-copy each existing target so a failed extraction rolls back cleanly.
  local aside_dir stamp target
  stamp="$(date +%Y%m%d%H%M%S)"
  if ! aside_dir=$(mktemp -d "${TICKFLOW_INSTALL_DIR}/.restore-aside.XXXXXX"); then
    systemctl start "$TICKFLOW_SERVICE_NAME" || true
    error "$(t backup.restore.invalid_archive "$archive")"
  fi
  for target in data tiers.yaml .env; do
    if [[ -e "${TICKFLOW_INSTALL_DIR}/${target}" ]]; then
      mv "${TICKFLOW_INSTALL_DIR}/${target}" "${aside_dir}/${target}.restore.${stamp}" \
        || { rm -rf "$aside_dir"; systemctl start "$TICKFLOW_SERVICE_NAME" || true; error "$(t backup.restore.invalid_archive "$archive")"; }
    fi
  done
  local extract_ok=true
  tar -xzf "$archive" -C "$TICKFLOW_INSTALL_DIR" >&2 || extract_ok=false
  if [[ "$extract_ok" != "true" ]]; then
    for target in data tiers.yaml .env; do
      if [[ -e "${aside_dir}/${target}.restore.${stamp}" ]]; then
        rm -rf "${TICKFLOW_INSTALL_DIR:?}/${target}"
        mv "${aside_dir}/${target}.restore.${stamp}" "${TICKFLOW_INSTALL_DIR}/${target}" 2>/dev/null || true
      fi
    done
    rm -rf "$aside_dir"
    systemctl start "$TICKFLOW_SERVICE_NAME" || true
    error "$(t backup.restore.invalid_archive "$archive")"
  fi
  chown -R root:root "$TICKFLOW_INSTALL_DIR/data" 2>/dev/null || true
  rm -rf "$aside_dir"
  if systemctl start "$TICKFLOW_SERVICE_NAME"; then
    wait_for_service "$TICKFLOW_SERVICE_NAME" 20 || true
  fi
  if ! systemctl is-active --quiet "$TICKFLOW_SERVICE_NAME"; then
    warn "$(t backup.restore.start_failed_rollback)"
    if systemctl stop "$TICKFLOW_SERVICE_NAME" 2>/dev/null; then
      for target in data tiers.yaml .env; do
        rm -rf "${TICKFLOW_INSTALL_DIR:?}/${target}"
      done
      local rolled_back=false
      for target in data tiers.yaml .env; do
        if [[ -e "${aside_dir}/${target}.restore.${stamp}" ]]; then
          mv "${aside_dir}/${target}.restore.${stamp}" "${TICKFLOW_INSTALL_DIR}/${target}" && rolled_back=true
        fi
      done
      if [[ "$rolled_back" == "true" ]]; then
        success "$(t backup.restore.rollback_done)"
      else
        warn "$(t backup.restore.rollback_failed "$aside_dir")"
      fi
    else
      warn "$(t backup.restore.rollback_failed "$aside_dir")"
    fi
    if systemctl start "$TICKFLOW_SERVICE_NAME" \
      && systemctl is-active --quiet "$TICKFLOW_SERVICE_NAME"; then
      success "$(t backup.restore.restored "$(basename "$archive")")"
      return 0
    fi
    error "$(t binary_app.error.update_failed "$(systemctl is-active "$TICKFLOW_SERVICE_NAME" 2>/dev/null || echo unknown)")"
  fi
  success "$(t backup.restore.restored "$(basename "$archive")")"
}
__DEPLOY_APP_IMPL_SCRIPT_END__

__DEPLOY_APP_IMPL_SCRIPT__ install_cpa-stack_impl.sh
#!/usr/bin/env bash

CPA_DOMAIN="${CPA_DOMAIN:-}"
CPAMP_DOMAIN="${CPAMP_DOMAIN:-}"
ENABLE_HTTPS="${ENABLE_HTTPS:-true}"
CPA_ALLOW_REMOTE="${CPA_ALLOW_REMOTE:-true}"
CERTBOT_EMAIL="${CERTBOT_EMAIL:-}"
CPA_STACK_COMPONENT="${CPA_STACK_COMPONENT:-all}"
CPA_MANAGEMENT_KEY="${CPA_MANAGEMENT_KEY:-}"
CPA_API_KEY="${CPA_API_KEY:-}"
CPAMP_ADMIN_KEY="${CPAMP_ADMIN_KEY:-}"
CPA_STACK_BACKUP_DIR="${CPA_STACK_BACKUP_DIR:-/opt/cpa-stack-backups}"
BACKUP_KEEP_DAYS="${BACKUP_KEEP_DAYS:-30}"

CPA_REPOSITORY="router-for-me/CLIProxyAPI"
CPAMP_REPOSITORY="seakee/CPA-Manager-Plus"
CPA_SERVICE_NAME="cli-proxy-api"
CPAMP_SERVICE_NAME="cpa-manager-plus"
CPA_SERVICE_USER="cli-proxy-api"
CPAMP_SERVICE_USER="cpa-manager-plus"
CPA_INSTALL_DIR="${CPA_INSTALL_DIR:-/opt/cli-proxy-api}"
CPAMP_INSTALL_DIR="${CPAMP_INSTALL_DIR:-/opt/cpa-manager-plus}"
CPA_CONFIG_DIR="${CPA_CONFIG_DIR:-/etc/cli-proxy-api}"
CPA_CONFIG_FILE="${CPA_CONFIG_DIR}/config.yaml"
CPA_DATA_DIR="${CPA_DATA_DIR:-/var/lib/cli-proxy-api}"
CPA_AUTH_DIR="${CPA_DATA_DIR}/auths"
CPAMP_DATA_DIR="${CPAMP_DATA_DIR:-/var/lib/cpa-manager-plus}"
CPAMP_ENV_DIR="${CPAMP_ENV_DIR:-/etc/cpa-stack}"
CPAMP_ENV_FILE="${CPAMP_ENV_DIR}/cpamp.env"
CPA_BIN="${CPA_INSTALL_DIR}/cli-proxy-api"
CPAMP_BIN="${CPAMP_INSTALL_DIR}/cpa-manager-plus"
NGINX_SITE="/etc/nginx/sites-available/cpa-stack"
NGINX_SITE_LINK="/etc/nginx/sites-enabled/cpa-stack"
NGINX_MAP_FILE="/etc/nginx/conf.d/cpa-stack-connection-upgrade.conf"
ACME_WEBROOT="/var/www/certbot"

CONFIG_KEYS=(
  CPA_DOMAIN
  CPAMP_DOMAIN
  ENABLE_HTTPS
  CPA_ALLOW_REMOTE
  CERTBOT_EMAIL
  CPA_STACK_BACKUP_DIR
  BACKUP_KEEP_DAYS
  CPA_INSTALL_DIR
  CPAMP_INSTALL_DIR
  CPA_CONFIG_DIR
  CPA_DATA_DIR
  CPAMP_DATA_DIR
  CPAMP_ENV_DIR
  INSTALLED_CPA_VERSION
  INSTALLED_CPAMP_VERSION
)

CONF_FILE="$(app_conf_file)"
LOCK_FILE="$(app_lock_file)"

_cpa_stack_doctor_primary_service() {
  printf '%s\n' "$CPA_SERVICE_NAME"
}
_cpa_stack_doctor_services() {
  printf '%s\n' "$CPA_SERVICE_NAME" "$CPAMP_SERVICE_NAME" nginx
}
APP_DOCTOR_SERVICE_FN=_cpa_stack_doctor_primary_service
APP_DOCTOR_SERVICES_FN=_cpa_stack_doctor_services
# Central check-update adapter: the stack ships two independently released
# GitHub binaries, so both components are compared against their repository's
# latest release through the shared checker and merged into one verdict.
# Component versions are read straight from the deployment config because
# central commands load definitions without running app actions.
_cpa_stack_state_rank() {
  case "$1" in
    update_available) printf '4\n' ;;
    check_failed) printf '3\n' ;;
    stale) printf '2\n' ;;
    unknown) printf '1\n' ;;
    *) printf '0\n' ;;
  esac
}
_cpa_stack_merge_version_json() {
  local a="$1" b="$2" a_state b_state a_cache b_cache a_checked b_checked a_error b_error
  local cache_state checked_at error_summary verdict_state
  a_state="$(state_json_field "$a" update_state 2>/dev/null || printf up_to_date)"
  b_state="$(state_json_field "$b" update_state 2>/dev/null || printf up_to_date)"
  a_cache="$(state_json_field "$a" cache_state 2>/dev/null || printf miss)"
  b_cache="$(state_json_field "$b" cache_state 2>/dev/null || printf miss)"
  a_checked="$(state_json_field "$a" checked_at 2>/dev/null || true)"
  b_checked="$(state_json_field "$b" checked_at 2>/dev/null || true)"
  a_error="$(state_json_field "$a" error 2>/dev/null || true)"
  b_error="$(state_json_field "$b" error 2>/dev/null || true)"
  [[ "$a_checked" == null ]] && a_checked=""
  [[ "$b_checked" == null ]] && b_checked=""
  [[ "$a_error" == null ]] && a_error=""
  [[ "$b_error" == null ]] && b_error=""
  checked_at="$a_checked"
  if [[ -z "$checked_at" ]]; then
    checked_at="$b_checked"
  elif [[ -n "$b_checked" && "$b_checked" > "$checked_at" ]]; then
    checked_at="$b_checked"
  fi
  case ",$a_cache,$b_cache," in
    *,stale,*) cache_state=stale ;;
    *,fresh,*|*,refreshed,*|*,not_persisted,*) cache_state=refreshed ;;
    *) cache_state=miss ;;
  esac
  error_summary="${a_error:+cpa: ${a_error}}"
  if [[ -n "$error_summary" && -n "$b_error" ]]; then
    error_summary+="; "
  fi
  error_summary+="${b_error:+cpamp: ${b_error}}"
  if (( $( _cpa_stack_state_rank "$a_state" ) >= $( _cpa_stack_state_rank "$b_state" ) )); then
    verdict_state="$a_state"
  else
    verdict_state="$b_state"
  fi
  # Component fields keep a stable cpa-then-cpamp order regardless of which
  # side won the verdict, so consumers can always split on the same layout.
  # When both sides lack a value the merge must stay JSON null: the legacy
  # status contract promises "version":null for uninstalled apps, and a
  # literal "null/null" string would break that surface for automation.
  local merged_installed merged_latest
  if [[ "$(state_json_field "$a" installed 2>/dev/null || printf null)" == null &&
        "$(state_json_field "$b" installed 2>/dev/null || printf null)" == null ]]; then
    merged_installed=null
  else
    merged_installed="$(state_json_field "$a" installed 2>/dev/null || printf null)/$(state_json_field "$b" installed 2>/dev/null || printf null)"
  fi
  if [[ "$(state_json_field "$a" latest 2>/dev/null || printf null)" == null &&
        "$(state_json_field "$b" latest 2>/dev/null || printf null)" == null ]]; then
    merged_latest=null
  else
    merged_latest="$(state_json_field "$a" latest 2>/dev/null || printf null)/$(state_json_field "$b" latest 2>/dev/null || printf null)"
  fi
  local merged_json components_json
  merged_json="$(version_check_emit_json \
    "$merged_installed" \
    "$merged_latest" \
    "$checked_at" "$verdict_state" github_release "$cache_state" "$error_summary")"
  components_json="{\"cpa\":$(version_check_component_json cpa "$CPA_REPOSITORY" "$a"),\"cpamp\":$(version_check_component_json cpamp "$CPAMP_REPOSITORY" "$b")}"
  version_check_attach_components_json "$merged_json" "$components_json"
}
_cpa_stack_load_installed_versions() {
  local conf_file
  conf_file="$(app_conf_file 2>/dev/null || true)"
  [[ -n "$conf_file" && -f "$conf_file" ]] || return 0
  load_config_file "$conf_file" "${CONFIG_KEYS[@]}"
}
_cpa_stack_check_update_json() {
  local refresh="${2:-0}" no_network="${3:-0}" a_json b_json
  _cpa_stack_load_installed_versions
  a_json="$(version_check_binary_release_json "cpa-stack-cpa" "$CPA_REPOSITORY" "${INSTALLED_CPA_VERSION:-}" "$refresh" "$no_network")"
  b_json="$(version_check_binary_release_json "cpa-stack-cpamp" "$CPAMP_REPOSITORY" "${INSTALLED_CPAMP_VERSION:-}" "$refresh" "$no_network")"
  _cpa_stack_merge_version_json "$a_json" "$b_json"
}
APP_CHECK_UPDATE_FN=_cpa_stack_check_update_json
_cpa_stack_status_version_json() {
  _cpa_stack_load_installed_versions
  local a_json b_json
  a_json="$(version_check_cached_binary_release_json "cpa-stack-cpa" "${INSTALLED_CPA_VERSION:-}")"
  b_json="$(version_check_cached_binary_release_json "cpa-stack-cpamp" "${INSTALLED_CPAMP_VERSION:-}")"
  _cpa_stack_merge_version_json "$a_json" "$b_json"
}
APP_STATUS_VERSION_FN=_cpa_stack_status_version_json
_cpa_stack_status_backup() {
  app_status_backup_json "CPA_STACK_BACKUP_DIR" "${CPA_STACK_BACKUP_DIR:-}" \
    "backup directory is unsafe or missing" 'cpa-stack-*.tar.gz'
}
APP_STATUS_BACKUP_FN=_cpa_stack_status_backup

cpa_stack_show_banner() {
  echo -e "${BOLD}$(t app.cpa_stack.banner)${NC}"
}

cpa_stack_truthy() {
  case "${1,,}" in
    1|true|yes|y|on) return 0 ;;
    *) return 1 ;;
  esac
}

cpa_stack_component_includes() {
  local component="$1"
  [[ "$CPA_STACK_COMPONENT" == "all" || "$CPA_STACK_COMPONENT" == "$component" ]]
}

cpa_stack_validate_component() {
  case "$CPA_STACK_COMPONENT" in
    all|cpa|cpamp) ;;
    *) error "$(t app.cpa_stack.error.component "$CPA_STACK_COMPONENT")" ;;
  esac
}

_validate_config_values() {
  app_validate_domain "CPA_DOMAIN" "$CPA_DOMAIN"
  app_validate_domain "CPAMP_DOMAIN" "$CPAMP_DOMAIN"
  app_validate_bool "ENABLE_HTTPS" "$ENABLE_HTTPS"
  app_validate_bool "CPA_ALLOW_REMOTE" "$CPA_ALLOW_REMOTE"
  if [[ -n "${CERTBOT_EMAIL:-}" ]]; then
    app_validate_email "CERTBOT_EMAIL" "$CERTBOT_EMAIL"
  fi
  [[ "$BACKUP_KEEP_DAYS" =~ ^[0-9]+$ ]] || error "$(t app.cpa_stack.error.keep_days)"
  require_safe_path "CPA_STACK_BACKUP_DIR" "$CPA_STACK_BACKUP_DIR"
  if [[ -n "$CPA_DOMAIN" && "$CPA_DOMAIN" == "$CPAMP_DOMAIN" ]]; then
    error "$(t app.cpa_stack.error.domains_same)"
  fi
}

cpa_stack_require_domains() {
  while [[ -z "$CPA_DOMAIN" ]]; do
    prompt "$(t app.cpa_stack.prompt.cpa_domain)"
    read -r CPA_DOMAIN
    if ! is_valid_dns_name "$CPA_DOMAIN"; then
      warn "$(t app.cpa_stack.error.domain_invalid "CPA_DOMAIN" "$CPA_DOMAIN")"
      CPA_DOMAIN=""
    fi
  done
  while [[ -z "$CPAMP_DOMAIN" ]]; do
    prompt "$(t app.cpa_stack.prompt.cpamp_domain)"
    read -r CPAMP_DOMAIN
    if ! is_valid_dns_name "$CPAMP_DOMAIN"; then
      warn "$(t app.cpa_stack.error.domain_invalid "CPAMP_DOMAIN" "$CPAMP_DOMAIN")"
      CPAMP_DOMAIN=""
    fi
  done
  _validate_config_values
  if cpa_stack_truthy "$ENABLE_HTTPS" && [[ -z "$CERTBOT_EMAIL" ]]; then
    if deploy_assume_yes; then
      error "$(t app.cpa_stack.error.noninteractive_email)"
    else
      while true; do
        prompt "$(t app.cpa_stack.prompt.email)"
        local _email; read -r _email
        [[ -z "$_email" ]] && { warn "$(t app.cpa_stack.warn.email_empty)"; continue; }
        if ! app_is_valid_email "$_email"; then
          warn "$(t app.cpa_stack.warn.email_invalid "$_email")"
          continue
        fi
        CERTBOT_EMAIL="$_email"
        break
      done
    fi
  fi
}

cpa_stack_preflight() {
  local action="${1:-}"
  if [[ "$action" != "status" && "$action" != "doctor" ]]; then
    require_root "$action"
  fi
  if [[ "$action" != "status" && "$action" != "doctor" ]] && ! command -v apt-get >/dev/null 2>&1; then
    error "$(t app.cpa_stack.error.apt_only)"
  fi
  if [[ "$action" != "status" && "$action" != "doctor" ]] && ! command -v systemctl >/dev/null 2>&1; then
    error "$(t app.cpa_stack.error.systemd_required)"
  fi
  cpa_stack_validate_component
  app_load_config
}

cpa_stack_arch() {
  case "$(uname -m)" in
    x86_64|amd64) printf '%s\n' amd64 ;;
    aarch64|arm64) printf '%s\n' arm64 ;;
    *) error "$(t app.cpa_stack.error.arch "$(uname -m)")" ;;
  esac
}

cpa_stack_cpa_asset_name() {
  local tag="$1" arch="$2"
  case "$arch" in
    amd64) printf 'CLIProxyAPI_%s_linux_amd64.tar.gz\n' "${tag#v}" ;;
    arm64) printf 'CLIProxyAPI_%s_linux_aarch64.tar.gz\n' "${tag#v}" ;;
  esac
}

cpa_stack_cpamp_asset_name() {
  local tag="$1" arch="$2"
  case "$arch" in
    amd64) printf 'cpa-manager-plus_%s_linux_amd64.tar.gz\n' "$tag" ;;
    arm64) printf 'cpa-manager-plus_%s_linux_arm64.tar.gz\n' "$tag" ;;
  esac
}

cpa_stack_release_json() {
  local repository="$1"
  curl -fsSL --retry 2 --connect-timeout 10 --max-time 30 \
    -H 'Accept: application/vnd.github+json' \
    -H 'User-Agent: deploy-scripts-cpa-stack' \
    "https://api.github.com/repos/${repository}/releases/latest"
}

cpa_stack_release_tag() {
  json_tag_name "$1"
}

cpa_stack_release_asset_url() {
  local json="$1" asset="$2" compact remainder after_asset
  compact="$(printf '%s' "$json" | tr -d '\r\n\t ' )"
  after_asset="${compact#*\"name\":\""${asset}"\"}"
  [[ "$after_asset" != "$compact" ]] || return 0
  remainder="${after_asset#*\"browser_download_url\":\"}"
  [[ "$remainder" != "$after_asset" ]] || return 0
  printf '%s\n' "${remainder%%\"*}"
}
cpa_stack_download_verified_archive() {
  local repository="$1" tag="$2" asset="$3" destination="$4"
  local checksum_url archive_url checksum_file expected actual
  checksum_url="https://github.com/${repository}/releases/download/${tag}/checksums.txt"
  archive_url="https://github.com/${repository}/releases/download/${tag}/${asset}"
  checksum_file="${destination}.checksums"

  if ! curl -fL --retry 2 --connect-timeout 10 --max-time 180 -H 'User-Agent: deploy-scripts-cpa-stack' -o "$destination" "$archive_url"; then
    rm -f "$destination" "$checksum_file"
    error "$(t app.cpa_stack.error.download "$asset")"
  fi
  if ! curl -fsSL --retry 2 --connect-timeout 10 --max-time 30 -H 'User-Agent: deploy-scripts-cpa-stack' -o "$checksum_file" "$checksum_url"; then
    rm -f "$destination" "$checksum_file"
    error "$(t app.cpa_stack.error.download "checksums.txt")"
  fi
  expected="$(awk -v asset="$asset" '$NF == asset || $NF == "./" asset { print $1; exit }' "$checksum_file")"
  actual="$(sha256sum "$destination" | awk '{print $1}')"
  rm -f "$checksum_file"
  if [[ -z "$expected" || "$expected" != "$actual" ]]; then
    rm -f "$destination"
    error "$(t app.cpa_stack.error.checksum "$asset")"
  fi
}

cpa_stack_install_binary() {
  local source="$1" target="$2" owner="$3" backup
  [[ -s "$source" ]] || error "$(t app.cpa_stack.error.binary_missing "$(basename "$target")" "$(dirname "$source")")"
  backup="${target}.bak.$(date +%Y%m%d_%H%M%S)"
  if [[ -f "$target" ]] && ! cp -a "$target" "$backup"; then
    error "$(t app.cpa_stack.error.binary_backup "$target")"
  fi
  if ! atomic_copy_file "$source" "$target" 0755 "$owner"; then
    [[ -f "$backup" ]] && cp -a "$backup" "$target" || true
    error "$(t app.cpa_stack.error.binary_install "$target")"
  fi
}

cpa_stack_install_release() {
  local component="$1" repository tag arch asset json archive extract_dir binary
  case "$component" in
    cpa)
      repository="$CPA_REPOSITORY"
      ;;
    cpamp)
      repository="$CPAMP_REPOSITORY"
      ;;
    *) return 1 ;;
  esac
  json="$(cpa_stack_release_json "$repository" 2>/dev/null)" || error "$(t app.cpa_stack.error.github "$repository")"
  tag="$(cpa_stack_release_tag "$json")"
  [[ -n "$tag" ]] || error "$(t app.cpa_stack.error.github "$repository")"
  arch="$(cpa_stack_arch)"
  if [[ "$component" == "cpa" ]]; then
    asset="$(cpa_stack_cpa_asset_name "$tag" "$arch")"
  else
    asset="$(cpa_stack_cpamp_asset_name "$tag" "$arch")"
  fi
  [[ -n "$(cpa_stack_release_asset_url "$json" "$asset")" ]] || error "$(t app.cpa_stack.error.release_asset "$tag" "$repository" "$asset")"
  step "$(t app.cpa_stack.step.download "$component" "$tag")"
  archive="$(mktemp "/tmp/${component}.XXXXXX")" || error "$(t app.cpa_stack.error.download "$asset")"
  extract_dir="$(mktemp -d "/tmp/${component}.XXXXXX")" || { rm -f "$archive"; error "$(t app.cpa_stack.error.extract "$asset")"; }
  if ! cpa_stack_download_verified_archive "$repository" "$tag" "$asset" "$archive"; then
    rm -f "$archive"; rm -rf "$extract_dir"; return 1
  fi
  if ! tar -xzf "$archive" -C "$extract_dir"; then
    rm -f "$archive"; rm -rf "$extract_dir"; error "$(t app.cpa_stack.error.extract "$asset")"
  fi
  if [[ "$component" == "cpa" ]]; then
    binary="$(find "$extract_dir" -type f -name cli-proxy-api -print -quit)"
    [[ -n "$binary" ]] || { rm -f "$archive"; rm -rf "$extract_dir"; error "$(t app.cpa_stack.error.binary_missing "cli-proxy-api" "$asset")"; }
    cpa_stack_install_binary "$binary" "$CPA_BIN" "${CPA_SERVICE_USER}:${CPA_SERVICE_USER}"
    INSTALLED_CPA_VERSION="$tag"
  else
    binary="$(find "$extract_dir" -type f -name cpa-manager-plus -print -quit)"
    [[ -n "$binary" ]] || { rm -f "$archive"; rm -rf "$extract_dir"; error "$(t app.cpa_stack.error.binary_missing "cpa-manager-plus" "$asset")"; }
    cpa_stack_install_binary "$binary" "$CPAMP_BIN" "${CPAMP_SERVICE_USER}:${CPAMP_SERVICE_USER}"
    INSTALLED_CPAMP_VERSION="$tag"
  fi
  rm -f "$archive"
  rm -rf "$extract_dir"
  app_save_config
}

cpa_stack_ensure_user() {
  local user="$1"
  if ! id "$user" >/dev/null 2>&1; then
    useradd --system --no-create-home --shell /usr/sbin/nologin "$user" \
      || error "$(t app.cpa_stack.error.user "$user")"
  fi
}

cpa_stack_prepare_runtime() {
  step "$(t app.cpa_stack.step.users)"
  cpa_stack_ensure_user "$CPA_SERVICE_USER"
  cpa_stack_ensure_user "$CPAMP_SERVICE_USER"
  local path owner
  while IFS='|' read -r path owner; do
    if ! mkdir -p "$path" || ! chown "$owner" "$path"; then
      error "$(t app.cpa_stack.error.directory "$path")"
    fi
  done <<EOF
$CPA_INSTALL_DIR|$CPA_SERVICE_USER:$CPA_SERVICE_USER
$CPA_CONFIG_DIR|root:$CPA_SERVICE_USER
$CPA_DATA_DIR|$CPA_SERVICE_USER:$CPA_SERVICE_USER
$CPA_AUTH_DIR|$CPA_SERVICE_USER:$CPA_SERVICE_USER
$CPAMP_INSTALL_DIR|$CPAMP_SERVICE_USER:$CPAMP_SERVICE_USER
$CPAMP_DATA_DIR|$CPAMP_SERVICE_USER:$CPAMP_SERVICE_USER
$CPAMP_ENV_DIR|root:root
$CPA_STACK_BACKUP_DIR|root:root
$ACME_WEBROOT|www-data:www-data
EOF
  chmod 0770 "$CPA_CONFIG_DIR" || true
  chmod 0750 "$CPA_DATA_DIR" "$CPA_AUTH_DIR" "$CPAMP_DATA_DIR" || true
  chmod 0700 "$CPAMP_ENV_DIR" "$CPA_STACK_BACKUP_DIR" || true
  [[ -f "$CPA_CONFIG_FILE" ]] && chmod 0660 "$CPA_CONFIG_FILE" 2>/dev/null || true
}

cpa_stack_random_key() {
  local prefix="$1"
  printf '%s%s\n' "$prefix" "$(openssl rand -hex 32)"
}

cpa_stack_write_cpa_config() {
  if [[ -f "$CPA_CONFIG_FILE" ]]; then
    warn "$(t app.cpa_stack.warn.config_preserved "$CPA_CONFIG_FILE")"
    if [[ -z "$CPA_MANAGEMENT_KEY" ]]; then
      local prior
      prior="$(sed -nE 's/^[[:space:]]*secret-key:[[:space:]]*"([^"]+)".*/\1/p' "$CPA_CONFIG_FILE" | tail -n 1)"
      [[ -n "$prior" ]] && CPA_MANAGEMENT_KEY="$prior"
    fi
    [[ -n "$CPA_MANAGEMENT_KEY" ]] || error "$(t app.cpa_stack.error.config_exists "$CPA_CONFIG_FILE")"
    return 0
  fi
  [[ -n "$CPA_MANAGEMENT_KEY" ]] || CPA_MANAGEMENT_KEY="$(cpa_stack_random_key 'cpa_')"
  [[ -n "$CPA_API_KEY" ]] || CPA_API_KEY="$(cpa_stack_random_key 'sk-')"
  if ! cat <<EOF | atomic_write_file "$CPA_CONFIG_FILE" 0660 "root:${CPA_SERVICE_USER}"
host: "127.0.0.1"
port: 8317

auth-dir: "${CPA_AUTH_DIR}"

api-keys:
  - "${CPA_API_KEY}"

usage-statistics-enabled: true

remote-management:
  # CPAMP's web panel calls the CPA management API from the browser over the
  # public domain; CPA rejects non-loopback clients unless allow-remote is
  # true. Keep false only when the panel is never used from a browser.
  allow-remote: ${CPA_ALLOW_REMOTE}
  secret-key: "${CPA_MANAGEMENT_KEY}"
EOF
  then
    error "$(t app.cpa_stack.error.config_write "$CPA_CONFIG_FILE")"
  fi
  if ! cpa_stack_truthy "$CPA_ALLOW_REMOTE"; then
    warn "$(t app.cpa_stack.warn.remote_disabled)"
  fi
}

cpa_stack_load_cpamp_env() {
  local prior_admin="" prior_management="" prior_upstream=""
  if [[ -f "$CPAMP_ENV_FILE" ]]; then
    load_config_file "$CPAMP_ENV_FILE" CPA_MANAGER_ADMIN_KEY CPA_MANAGEMENT_KEY CPA_UPSTREAM_URL || true
    prior_admin="${CPA_MANAGER_ADMIN_KEY:-}"
    prior_management="${CPA_MANAGEMENT_KEY:-}"
    prior_upstream="${CPA_UPSTREAM_URL:-}"
  fi
  [[ -n "$CPAMP_ADMIN_KEY" ]] || CPAMP_ADMIN_KEY="$prior_admin"
  [[ -n "$CPA_MANAGEMENT_KEY" ]] || CPA_MANAGEMENT_KEY="$prior_management"
  [[ -n "$CPA_MANAGEMENT_KEY" ]] || error "$(t app.cpa_stack.error.management_key_required)"
  [[ -n "$CPAMP_ADMIN_KEY" ]] || CPAMP_ADMIN_KEY="$(cpa_stack_random_key 'cpamp_')"
  CPA_UPSTREAM_URL="${prior_upstream:-http://127.0.0.1:8317}"
}

cpa_stack_write_cpamp_env() {
  cpa_stack_load_cpamp_env
  CPA_MANAGER_ADMIN_KEY="$CPAMP_ADMIN_KEY"
  if ! write_config_file "$CPAMP_ENV_FILE" \
    CPA_MANAGER_ADMIN_KEY CPA_UPSTREAM_URL CPA_MANAGEMENT_KEY; then
    error "$(t app.cpa_stack.error.cpamp_env_write "$CPAMP_ENV_FILE")"
  fi
}

cpa_stack_write_services() {
  step "$(t app.cpa_stack.step.services)"
  if ! cat <<EOF | systemd_write_unit "/etc/systemd/system/${CPA_SERVICE_NAME}.service"
[Unit]
Description=CLIProxyAPI
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=${CPA_SERVICE_USER}
Group=${CPA_SERVICE_USER}
WorkingDirectory=${CPA_INSTALL_DIR}
ExecStart=${CPA_BIN} -config ${CPA_CONFIG_FILE}
Restart=on-failure
RestartSec=3
NoNewPrivileges=true
PrivateTmp=true
ProtectHome=true

[Install]
WantedBy=multi-user.target
EOF
  then
    error "$(t app.cpa_stack.error.service "$CPA_SERVICE_NAME")"
  fi
  if ! cat <<EOF | systemd_write_unit "/etc/systemd/system/${CPAMP_SERVICE_NAME}.service"
[Unit]
Description=CPA Manager Plus Manager Server
After=network-online.target ${CPA_SERVICE_NAME}.service
Wants=network-online.target

[Service]
Type=simple
User=${CPAMP_SERVICE_USER}
Group=${CPAMP_SERVICE_USER}
WorkingDirectory=${CPAMP_INSTALL_DIR}
Environment=HTTP_ADDR=127.0.0.1:18317
Environment=USAGE_DATA_DIR=${CPAMP_DATA_DIR}
EnvironmentFile=${CPAMP_ENV_FILE}
ExecStart=${CPAMP_BIN}
Restart=on-failure
RestartSec=3
NoNewPrivileges=true
PrivateTmp=true
ProtectHome=true

[Install]
WantedBy=multi-user.target
EOF
  then
    error "$(t app.cpa_stack.error.service "$CPAMP_SERVICE_NAME")"
  fi
  systemctl daemon-reload || error "$(t app.cpa_stack.error.service "$CPA_SERVICE_NAME")"
  systemctl enable "$CPA_SERVICE_NAME" "$CPAMP_SERVICE_NAME" >/dev/null \
    || error "$(t app.cpa_stack.error.service "$CPA_SERVICE_NAME")"
  systemctl restart "$CPA_SERVICE_NAME" || error "$(t app.cpa_stack.error.service "$CPA_SERVICE_NAME")"
  wait_for_service "$CPA_SERVICE_NAME" 20 || error "$(t app.cpa_stack.error.service "$CPA_SERVICE_NAME")"
  systemctl restart "$CPAMP_SERVICE_NAME" || error "$(t app.cpa_stack.error.service "$CPAMP_SERVICE_NAME")"
  wait_for_service "$CPAMP_SERVICE_NAME" 20 || error "$(t app.cpa_stack.error.service "$CPAMP_SERVICE_NAME")"
}

cpa_stack_nginx_common_headers() {
  cat <<'EOF'
    client_max_body_size 64m;
    proxy_http_version 1.1;
    proxy_read_timeout 3600s;
    proxy_send_timeout 3600s;
    proxy_buffering off;

    proxy_set_header Host              $host;
    proxy_set_header X-Real-IP         $remote_addr;
    proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header Upgrade           $http_upgrade;
    proxy_set_header Connection        $cpa_stack_connection_upgrade;
EOF
}

cpa_stack_write_nginx_http() {
  step "$(t app.cpa_stack.step.nginx)"
  mkdir -p /etc/nginx/conf.d /etc/nginx/sites-available /etc/nginx/sites-enabled "$ACME_WEBROOT" \
    || error "$(t app.cpa_stack.error.nginx "$NGINX_SITE")"
  if ! cat <<'EOF' | atomic_write_file "$NGINX_MAP_FILE" 0644 root:root
map $http_upgrade $cpa_stack_connection_upgrade {
    default upgrade;
    ''      close;
}
EOF
  then
    error "$(t app.cpa_stack.error.nginx "$NGINX_MAP_FILE")"
  fi
  if ! cat <<EOF | atomic_write_file "$NGINX_SITE" 0644 root:root
server {
    listen 80;
    listen [::]:80;
    server_name ${CPA_DOMAIN};

    location /.well-known/acme-challenge/ {
        root ${ACME_WEBROOT};
    }

$(cpa_stack_nginx_common_headers)
    location / {
        proxy_pass http://127.0.0.1:8317;
    }
}

server {
    listen 80;
    listen [::]:80;
    server_name ${CPAMP_DOMAIN};

    location /.well-known/acme-challenge/ {
        root ${ACME_WEBROOT};
    }

$(cpa_stack_nginx_common_headers)
    location = / {
        return 302 /management.html;
    }

    location / {
        proxy_pass http://127.0.0.1:18317;
    }
}
EOF
  then
    error "$(t app.cpa_stack.error.nginx "$NGINX_SITE")"
  fi
  atomic_symlink "$NGINX_SITE" "$NGINX_SITE_LINK" \
    || error "$(t app.cpa_stack.error.nginx "$NGINX_SITE_LINK")"
  nginx -t || error "$(t app.cpa_stack.error.nginx "$NGINX_SITE")"
  systemctl enable nginx >/dev/null || true
  systemctl restart nginx || error "$(t app.cpa_stack.error.nginx "$NGINX_SITE")"
}

cpa_stack_nginx_http2_directives() {
  local version
  version="$(nginx -v 2>&1 | sed -nE 's/.*nginx\/([0-9]+\.[0-9]+\.[0-9]+).*/\1/p')"
  if [[ -n "$version" ]] && awk -v v="$version" 'BEGIN { split(v, a, "."); exit !(a[1]*10000 + a[2]*100 + a[3] >= 12501) }'; then
    cat <<'EOF'
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
EOF
  else
    cat <<'EOF'
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
EOF
  fi
}

cpa_stack_write_nginx_https() {
  local cert_dir="/etc/letsencrypt/live/${CPA_DOMAIN}"
  [[ -f "${cert_dir}/fullchain.pem" && -f "${cert_dir}/privkey.pem" ]] || return 1
  if ! cat <<EOF | atomic_write_file "$NGINX_SITE" 0644 root:root
server {
    listen 80;
    listen [::]:80;
    server_name ${CPA_DOMAIN};

    location /.well-known/acme-challenge/ {
        root ${ACME_WEBROOT};
    }

    location / {
        return 301 https://\$host\$request_uri;
    }
}

server {
$(cpa_stack_nginx_http2_directives)
    server_name ${CPA_DOMAIN};

    ssl_certificate ${cert_dir}/fullchain.pem;
    ssl_certificate_key ${cert_dir}/privkey.pem;

$(cpa_stack_nginx_common_headers)
    location / {
        proxy_pass http://127.0.0.1:8317;
    }
}

server {
    listen 80;
    listen [::]:80;
    server_name ${CPAMP_DOMAIN};

    location /.well-known/acme-challenge/ {
        root ${ACME_WEBROOT};
    }

    location / {
        return 301 https://\$host\$request_uri;
    }
}

server {
$(cpa_stack_nginx_http2_directives)
    server_name ${CPAMP_DOMAIN};

    ssl_certificate ${cert_dir}/fullchain.pem;
    ssl_certificate_key ${cert_dir}/privkey.pem;

$(cpa_stack_nginx_common_headers)
    location = / {
        return 302 /management.html;
    }

    location / {
        proxy_pass http://127.0.0.1:18317;
    }
}
EOF
  then
    return 1
  fi
  nginx -t && systemctl reload nginx
}

cpa_stack_configure_https() {
  cpa_stack_truthy "$ENABLE_HTTPS" || return 0
  step "$(t app.cpa_stack.step.https)"
  if ! certbot certonly --webroot -w "$ACME_WEBROOT" \
      --email "$CERTBOT_EMAIL" --agree-tos --non-interactive \
      -d "$CPA_DOMAIN" -d "$CPAMP_DOMAIN"; then
    warn "$(t app.cpa_stack.warn.certbot "$CPA_DOMAIN" "$CPAMP_DOMAIN")"
    return 0
  fi
  cpa_stack_write_nginx_https || error "$(t app.cpa_stack.error.nginx "$NGINX_SITE")"
}

cpa_stack_install_dependencies() {
  step "$(t app.cpa_stack.step.dependencies)"
  apt-get update -qq || warn "apt-get update failed; package installation may fail."
  DEBIAN_FRONTEND=noninteractive apt-get install -y -qq \
    curl ca-certificates nginx certbot python3-certbot-nginx openssl \
    || error "$(t app.cpa_stack.error.deps)"
}

cpa_stack_stop_components() {
  if cpa_stack_component_includes cpamp; then
    systemctl stop "$CPAMP_SERVICE_NAME" >/dev/null 2>&1 || true
  fi
  if cpa_stack_component_includes cpa; then
    systemctl stop "$CPA_SERVICE_NAME" >/dev/null 2>&1 || true
  fi
}

cpa_stack_verify_health() {
  local name="$1" url="$2" code
  command -v curl >/dev/null 2>&1 || return 0
  code="$(curl -sS -o /dev/null -w '%{http_code}' --max-time 8 "$url" 2>/dev/null || echo 000)"
  if [[ "$code" =~ ^2 ]]; then
    success "$(t app.cpa_stack.success.health "$name" "$code")"
    return 0
  fi
  warn "$(t app.cpa_stack.warn.http_health "$name" "$code")"
  return 1
}

cpa_stack_prune_backups() {
  find "$CPA_STACK_BACKUP_DIR" -maxdepth 1 -type f -name 'cpa-stack-*.tar.gz' -mtime "+${BACKUP_KEEP_DAYS}" -delete 2>/dev/null || true
}

do_install() {
  cpa_stack_show_banner
  cpa_stack_preflight install
  acquire_lock
  cpa_stack_require_domains
  app_save_config
  cpa_stack_install_dependencies
  cpa_stack_prepare_runtime
  step "$(t app.cpa_stack.step.config)"
  cpa_stack_write_cpa_config
  cpa_stack_write_cpamp_env
  cpa_stack_stop_components
  cpa_stack_install_release cpa
  cpa_stack_install_release cpamp
  cpa_stack_write_services
  cpa_stack_write_nginx_http
  cpa_stack_configure_https
  # Health verification failures are non-fatal (firewall/dependency timing),
  # but the summary must reflect the actual state: a pending title instead of
  # a success title, matching the binary_app/newapi convention.
  local health_ok=true
  cpa_stack_verify_health CPA http://127.0.0.1:8317/healthz || health_ok=false
  cpa_stack_verify_health CPAMP http://127.0.0.1:18317/health || health_ok=false
  local scheme="http"
  cpa_stack_truthy "$ENABLE_HTTPS" && [[ -f "/etc/letsencrypt/live/${CPA_DOMAIN}/fullchain.pem" ]] && scheme="https"
  if [[ "$health_ok" == true ]]; then
    success "$(t app.cpa_stack.success.installed "${scheme}://${CPA_DOMAIN}" "${scheme}://${CPAMP_DOMAIN}")"
  else
    info "$(t app.cpa_stack.success.installed_pending "${scheme}://${CPA_DOMAIN}" "${scheme}://${CPAMP_DOMAIN}")"
  fi
  info "$(t app.cpa_stack.info.oauth)"
  info "$(t app.cpa_stack.info.login_command "$CPA_SERVICE_USER" "$CPA_BIN" "$CPA_CONFIG_FILE")"
}

do_update() {
  cpa_stack_show_banner
  cpa_stack_preflight update
  acquire_lock
  [[ -f "$CPA_CONFIG_FILE" ]] || error "$(t app.cpa_stack.warn.config_missing "$CPA_CONFIG_FILE")"
  cpa_stack_install_dependencies
  cpa_stack_prepare_runtime
  cpa_stack_stop_components
  if cpa_stack_component_includes cpa; then
    cpa_stack_install_release cpa
  fi
  if cpa_stack_component_includes cpamp; then
    cpa_stack_install_release cpamp
  fi
  cpa_stack_write_services
  cpa_stack_write_nginx_http
  cpa_stack_configure_https
  cpa_stack_verify_health CPA http://127.0.0.1:8317/healthz || true
  cpa_stack_verify_health CPAMP http://127.0.0.1:18317/health || true
  success "$(t app.cpa_stack.success.updated)"
}

do_cert() {
  cpa_stack_show_banner
  cpa_stack_preflight cert
  acquire_lock
  if ! cpa_stack_truthy "$ENABLE_HTTPS"; then
    error "$(t app.cpa_stack.error.https_disabled)"
  fi
  [[ -n "$CERTBOT_EMAIL" ]] || error "$(t app.cpa_stack.error.email_required)"
  cpa_stack_install_dependencies
  cpa_stack_write_nginx_http
  cpa_stack_configure_https
  cpa_stack_verify_health CPA http://127.0.0.1:8317/healthz || true
  cpa_stack_verify_health CPAMP http://127.0.0.1:18317/health || true
  local scheme="http"
  cpa_stack_truthy "$ENABLE_HTTPS" && [[ -f "/etc/letsencrypt/live/${CPA_DOMAIN}/fullchain.pem" ]] && scheme="https"
  if [[ "$scheme" == "https" ]]; then
    success "$(t app.cpa_stack.success.https "${scheme}://${CPA_DOMAIN}" "${scheme}://${CPAMP_DOMAIN}")"
  else
    warn "$(t app.cpa_stack.warn.certbot "$CPA_DOMAIN" "$CPAMP_DOMAIN")"
  fi
}

do_backup() {
  cpa_stack_show_banner
  cpa_stack_preflight backup
  acquire_lock
  require_safe_path "CPA_STACK_BACKUP_DIR" "$CPA_STACK_BACKUP_DIR"
  step "$(t app.cpa_stack.step.backup)"
  mkdir -p "$CPA_STACK_BACKUP_DIR" || error "$(t app.cpa_stack.error.backup "$CPA_STACK_BACKUP_DIR")"
  local timestamp archive tmp cpamp_was_active=false
  timestamp="$(date +%Y%m%d_%H%M%S)"
  archive="${CPA_STACK_BACKUP_DIR}/cpa-stack-${timestamp}.tar.gz"
  tmp="${archive}.tmp"
  systemctl is-active --quiet "$CPAMP_SERVICE_NAME" && cpamp_was_active=true
  if $cpamp_was_active; then
    systemctl stop "$CPAMP_SERVICE_NAME" || error "$(t app.cpa_stack.error.service "$CPAMP_SERVICE_NAME")"
  fi
  # CPAMP data directory includes usage.sqlite, its WAL/SHM files, and data.key.
  local -a backup_paths=()
  for candidate in \
      etc/cpa-stack \
      etc/cli-proxy-api \
      opt/cpa-manager-plus/config.json \
      var/lib/cpa-manager-plus \
      var/lib/cli-proxy-api; do
    [[ -e "/${candidate}" ]] && backup_paths+=("$candidate")
  done
  if ! tar -C / -czf "$tmp" "${backup_paths[@]}" 2>/dev/null; then
    rm -f "$tmp"
    if $cpamp_was_active; then
      systemctl start "$CPAMP_SERVICE_NAME" || true
    fi
    error "$(t app.cpa_stack.error.backup "$archive")"
  fi
  if ! mv "$tmp" "$archive"; then
    rm -f "$tmp"
    if $cpamp_was_active; then
      systemctl start "$CPAMP_SERVICE_NAME" || true
    fi
    error "$(t app.cpa_stack.error.backup "$archive")"
  fi
  if $cpamp_was_active; then
    systemctl start "$CPAMP_SERVICE_NAME" || error "$(t app.cpa_stack.error.service "$CPAMP_SERVICE_NAME")"
  fi
  cpa_stack_prune_backups
  success "$(t app.cpa_stack.success.backup "$archive")"
}

do_status() {
  cpa_stack_show_banner
  app_load_config
  printf '\n[%s]\n' "$(t app.cpa_stack.status.services)"
  printf '  %s: %s\n' "$CPA_SERVICE_NAME" "$(service_status_label "$CPA_SERVICE_NAME")"
  printf '  %s: %s\n' "$CPAMP_SERVICE_NAME" "$(service_status_label "$CPAMP_SERVICE_NAME")"
  printf '  nginx: %s\n' "$(service_status_label nginx)"
  printf '\n[%s]\n' "$(t app.cpa_stack.status.local_health)"
  cpa_stack_verify_health CPA http://127.0.0.1:8317/healthz || true
  cpa_stack_verify_health CPAMP http://127.0.0.1:18317/health || true
  printf '\n[%s]\n' "$(t app.cpa_stack.status.paths)"
  for path in "$CPA_CONFIG_FILE" "$CPA_AUTH_DIR" "$CPAMP_ENV_FILE" "$CPAMP_DATA_DIR" "$NGINX_SITE" "$CPA_STACK_BACKUP_DIR"; do
    [[ -e "$path" ]] && printf '  [ok] %s\n' "$path" || printf '  [--] %s\n' "$path"
  done
}

do_doctor() {
  cpa_stack_show_banner
  app_load_config
  local failures=0 warnings=0
  printf '\n%s\n' "$(t doctor.title)"
  if [[ -n "$CPA_DOMAIN" && -n "$CPAMP_DOMAIN" ]]; then
    success "$(t app.cpa_stack.doctor.domains "$CPA_DOMAIN" "$CPAMP_DOMAIN")"
  else
    warn "$(t app.cpa_stack.error.domain_required "CPA_DOMAIN / CPAMP_DOMAIN")"; warnings=$((warnings + 1))
  fi
  for requirement in curl nginx systemctl; do
    if command -v "$requirement" >/dev/null 2>&1; then
      success "$(t app.cpa_stack.doctor.command_ok "$requirement")"
    else
      warn "$(t app.cpa_stack.doctor.command_missing "$requirement")"; failures=$((failures + 1))
    fi
  done
  for service in "$CPA_SERVICE_NAME" "$CPAMP_SERVICE_NAME" nginx; do
    if systemctl is-active --quiet "$service" 2>/dev/null; then
      success "$(t app.cpa_stack.doctor.service_active "$service")"
    else
      warn "$(t app.cpa_stack.doctor.service_inactive "$service")"; warnings=$((warnings + 1))
    fi
  done
  if [[ -f "$CPA_CONFIG_FILE" ]]; then
    if grep -Eq '^host:[[:space:]]*"?127\.0\.0\.1' "$CPA_CONFIG_FILE" \
        && grep -Eq '^usage-statistics-enabled:[[:space:]]*true' "$CPA_CONFIG_FILE"; then
      success "$(t app.cpa_stack.doctor.cpa_loopback_ok)"
    else
      warn "$(t app.cpa_stack.doctor.cpa_loopback_bad)"; warnings=$((warnings + 1))
    fi
  else
    warn "$(t app.cpa_stack.warn.config_missing "$CPA_CONFIG_FILE")"; failures=$((failures + 1))
  fi
  if [[ -f "$CPAMP_ENV_FILE" ]]; then
    success "$(t app.cpa_stack.doctor.env_ok)"
  else
    warn "$(t app.cpa_stack.warn.config_missing "$CPAMP_ENV_FILE")"; failures=$((failures + 1))
  fi
  if command -v ss >/dev/null 2>&1; then
    if ss -ltnH 2>/dev/null | awk '{print $4}' | grep -Eq '(^|:)8317$|(^|:)18317$'; then
      if ss -ltnH 2>/dev/null | awk '{print $4}' | grep -Eq '(^|:)0\.0\.0\.0:8317$|(^|:)\[::\]:8317$|(^|:)0\.0\.0\.0:18317$|(^|:)\[::\]:18317$'; then
        warn "$(t app.cpa_stack.doctor.public_listener_bad)"; failures=$((failures + 1))
      else
        success "$(t app.cpa_stack.doctor.loopback_ok)"
      fi
    fi
  fi
  cpa_stack_verify_health CPA http://127.0.0.1:8317/healthz || true
  cpa_stack_verify_health CPAMP http://127.0.0.1:18317/health || true
  if (( failures > 0 )); then
    warn "$(t app.cpa_stack.doctor.done_blocking "$failures" "$warnings")"
    return 1
  fi
  if (( warnings > 0 )); then
    warn "$(t app.cpa_stack.doctor.done_warnings "$warnings")"
  else
    success "$(t app.cpa_stack.doctor.done_ok)"
  fi
}

do_uninstall() {
  cpa_stack_show_banner
  cpa_stack_preflight uninstall
  acquire_lock
  local confirm delete_data=false
  if deploy_assume_yes; then
    confirm="YES"
  else
    prompt "$(t app.cpa_stack.prompt.continue)"
    read -r confirm
  fi
  [[ "$confirm" == "YES" ]] || error "$(t app.cpa_stack.error.uninstall_cancelled)"
  if deploy_assume_yes; then
    deploy_env_truthy DEPLOY_DELETE_DATA && delete_data=true
  else
    prompt "$(t app.cpa_stack.prompt.delete_data "/var/lib/cli-proxy-api and /var/lib/cpa-manager-plus")"
    local answer
    read -r answer
    [[ "${answer,,}" == "y" || "${answer,,}" == "yes" ]] && delete_data=true
  fi
  systemctl disable --now "$CPAMP_SERVICE_NAME" "$CPA_SERVICE_NAME" >/dev/null 2>&1 || true
  rm -f "/etc/systemd/system/${CPA_SERVICE_NAME}.service" "/etc/systemd/system/${CPAMP_SERVICE_NAME}.service"
  systemctl daemon-reload || true
  rm -f "$NGINX_SITE_LINK" "$NGINX_SITE" "$NGINX_MAP_FILE"
  rm -f "$CONF_FILE"
  if command -v nginx >/dev/null 2>&1 && nginx -t >/dev/null 2>&1; then
    systemctl reload nginx || true
  fi
  if $delete_data; then
    safe_rm_dir "$CPA_DATA_DIR" "CPA_DATA_DIR"
    safe_rm_dir "$CPAMP_DATA_DIR" "CPAMP_DATA_DIR"
    safe_rm_dir "$CPA_CONFIG_DIR" "CPA_CONFIG_DIR"
    safe_rm_dir "$CPAMP_ENV_DIR" "CPAMP_ENV_DIR"
    safe_rm_dir "$CPA_STACK_BACKUP_DIR" "CPA_STACK_BACKUP_DIR"
  else
    info "$(t app.cpa_stack.info.kept_data "$CPA_DATA_DIR")"
    info "$(t app.cpa_stack.info.kept_data "$CPAMP_DATA_DIR")"
  fi
  success "$(t app.cpa_stack.success.removed)"
}

do_verify() {
  cpa_stack_show_banner
  require_root "verify"
  app_load_config
  step "$(t backup.verify.step)"
  require_safe_path "CPA_STACK_BACKUP_DIR" "$CPA_STACK_BACKUP_DIR"
  app_verify_latest_backup "$CPA_STACK_BACKUP_DIR" 'cpa-stack-*.tar.gz'
}

# Restore the five root-relative paths captured by do_backup. The archive is
# a tar -C / of etc/cpa-stack, etc/cli-proxy-api, opt/cpa-manager-plus/
# config.json, var/lib/cpa-manager-plus, and var/lib/cli-proxy-api, so
# extraction targets / directly. CPAMP is stopped for the swap (it holds the
# sqlite data); CPA keeps running. Every existing target is set aside first,
# enabling a clean rollback when extraction fails or services cannot return.
do_restore() {
  cpa_stack_show_banner
  require_root "restore"
  app_load_config
  acquire_lock
  step "$(t backup.restore.step)"
  require_safe_path "CPA_STACK_BACKUP_DIR" "$CPA_STACK_BACKUP_DIR"
  [[ -d "$CPA_STACK_BACKUP_DIR" ]] || error "$(t backup.restore.no_backups "$CPA_STACK_BACKUP_DIR")"
  local archive
  archive="${CPA_STACK_RESTORE_ARCHIVE:-}"
  if [[ -n "$archive" ]]; then
    [[ "$archive" == "$CPA_STACK_BACKUP_DIR"/cpa-stack-*.tar.gz && -f "$archive" ]] \
      || error "$(t backup.restore.invalid_archive "$archive")"
  else
    archive="$(backup_latest_archive "$CPA_STACK_BACKUP_DIR" 'cpa-stack-*.tar.gz' || true)"
    [[ -n "$archive" ]] || error "$(t backup.restore.no_backups "$CPA_STACK_BACKUP_DIR")"
  fi
  local member_list member found=false
  if ! member_list="$(tar -tzf "$archive" 2>/dev/null)"; then
    error "$(t backup.restore.invalid_archive "$archive")"
  fi
  while IFS= read -r member; do
    case "$member" in
      ""|/*|*'/../'*|../*|*'/..'|..|*"\\"*)
        error "$(t backup.restore.invalid_archive "$(basename "$archive")")"
        ;;
      etc/cpa-stack|etc/cpa-stack/*|etc/cli-proxy-api|etc/cli-proxy-api/* \
      |opt/cpa-manager-plus/config.json|var/lib/cpa-manager-plus|var/lib/cpa-manager-plus/* \
      |var/lib/cli-proxy-api|var/lib/cli-proxy-api/*) found=true ;;
    esac
  done <<< "$member_list"
  [[ "$found" == "true" ]] || error "$(t backup.restore.invalid_archive "$(basename "$archive")")"
  info "$(t backup.restore.using "$archive")"

  systemctl stop "$CPAMP_SERVICE_NAME" \
    || error "$(t backup.restore.stop_failed "$CPAMP_SERVICE_NAME")"
  local aside_dir stamp target extract_ok=true had_aside=false
  stamp="$(date +%Y%m%d%H%M%S)"
  if ! aside_dir=$(mktemp -d "${CPA_STACK_BACKUP_DIR}/.restore-aside.XXXXXX"); then
    systemctl start "$CPAMP_SERVICE_NAME" || true
    error "$(t backup.restore.invalid_archive "$archive")"
  fi
  for target in etc/cpa-stack etc/cli-proxy-api opt/cpa-manager-plus/config.json \
      var/lib/cpa-manager-plus var/lib/cli-proxy-api; do
    if [[ -e "/${target}" ]]; then
      mkdir -p "${aside_dir}/$(dirname "$target")"
      mv "/${target}" "${aside_dir}/${target}.restore.${stamp}" && had_aside=true
    fi
  done
  tar -xzf "$archive" -C / >&2 || extract_ok=false
  if [[ "$extract_ok" != "true" ]]; then
    for target in etc/cpa-stack etc/cli-proxy-api opt/cpa-manager-plus/config.json \
        var/lib/cpa-manager-plus var/lib/cli-proxy-api; do
      if [[ -e "${aside_dir}/${target}.restore.${stamp}" ]]; then
        rm -rf "/${target:?}"
        mv "${aside_dir}/${target}.restore.${stamp}" "/${target}" 2>/dev/null || true
      fi
    done
    rm -rf "$aside_dir"
    systemctl start "$CPAMP_SERVICE_NAME" || true
    error "$(t backup.restore.invalid_archive "$archive")"
  fi
  rm -rf "$aside_dir"
  systemctl start "$CPAMP_SERVICE_NAME" \
    || error "$(t binary_app.error.install_start_failed "$CPAMP_SERVICE_NAME" "$CPAMP_SERVICE_NAME")"
  success "$(t backup.restore.restored "$(basename "$archive")")"
}
__DEPLOY_APP_IMPL_SCRIPT_END__

__DEPLOY_APP_IMPL_SCRIPT__ install_ntfy_impl.sh
#!/usr/bin/env bash
set -euo pipefail
umask 077

# ntfy (https://github.com/binwiederhier/ntfy) ships a tarball with a single
# binary named ntfy_<version>_linux_<arch>.tar.gz (version without the
# leading v).  The shared binary-app library (lib/binary_app.sh) provides the
# lifecycle; this file only configures it and adds ntfy-specific hooks.
# See PLAN.md section 2 for the verified release asset mapping.

DOMAIN="${DOMAIN:-}"
PORT="${PORT:-2586}"
INSTALL_DIR="${INSTALL_DIR:-/opt/ntfy}"
DATA_DIR="${DATA_DIR:-/var/lib/ntfy}"
LOG_DIR="${LOG_DIR:-/var/log/ntfy}"
SERVICE_NAME="${SERVICE_NAME:-ntfy}"
SERVICE_USER="${SERVICE_USER:-ntfy}"
GITHUB_REPO="${GITHUB_REPO:-binwiederhier/ntfy}"
BACKUP_DIR="${BACKUP_DIR:-/opt/ntfy-backups}"
BACKUP_KEEP_DAYS="${BACKUP_KEEP_DAYS:-30}"
BA_BIN_NAME="ntfy"
BA_ARCHIVE_TYPE="tar.gz"
BA_USE_ENV_FILE=0
BA_FIREWALL=0
BA_BIND_ADDR="${BA_BIND_ADDR:-127.0.0.1}"
BA_SERVICE_DESCRIPTION="ntfy push notification server"
BA_SERVICE_ARGS="serve /etc/ntfy/server.yml"
BA_HEALTH_URL="http://127.0.0.1:${PORT}/"
BA_HEALTH_CODES="^(200|301|302)$"
CONFIG_KEYS=(
  DOMAIN PORT INSTALL_DIR DATA_DIR LOG_DIR SERVICE_NAME SERVICE_USER
  GITHUB_REPO BACKUP_DIR BACKUP_KEEP_DAYS BA_BIND_ADDR BA_VERSION BA_ENABLE_HTTPS CERTBOT_EMAIL INSTALLED_VERSION
)

# Release asset names embed the version without the leading v.
ba_asset_name() {
  local version="$1"
  printf 'ntfy_%s_linux_%s.tar.gz\n' "${version#v}" "$BA_ARCH"
}

# Write the managed ntfy server configuration under /etc/ntfy.
ba_write_config() {
  local config_dir="/etc/ntfy"
  local config_file="${config_dir}/server.yml"
  if ! atomic_write_file "$config_file" 644 root:root <<EOF
# Managed by the ntfy deploy script.
listen-http: ${BA_BIND_ADDR}:${PORT}
cache-file: ${DATA_DIR}/cache.db
attachment-cache-dir: ${DATA_DIR}/attachments
EOF
  then
    error "$(t app.ntfy.error.config_write "$config_file")"
  fi
  success "$(t app.ntfy.success.config_written "$config_file")"
}

# Remove the managed server configuration during uninstall.
ba_uninstall_extra() {
  local config_dir="/etc/ntfy"
  local config_file="${config_dir}/server.yml"
  ba_remove_file_or_error "$config_file" "NTFY_CONFIG_FILE"
  if [[ -d "$config_dir" ]] && [[ -z "$(ls -A "$config_dir" 2>/dev/null)" ]]; then
    if ! safe_rm_dir "$config_dir" "NTFY_CONFIG_DIR"; then
      warn "$(t app.ntfy.warn.config_dir_remove "$config_dir")"
    fi
  fi
  success "$(t app.ntfy.success.removed_config)"
}

# Show a quick publish hint after install.
ba_summary_extra() {
  echo -e "  ${BOLD}$(t app.ntfy.hint.publish "$PORT")${NC}"
}

# Thin lifecycle delegates over the shared binary-app library.
preflight_check() {
  bapp_preflight "$@"
}

_validate_config_values() {
  bapp_validate_cfg
}

do_install() {
  acquire_lock
  bapp_install
}

do_update() {
  acquire_lock
  bapp_update
}

do_backup() {
  acquire_lock
  bapp_backup
}

do_verify() {
  bapp_verify
}

do_restore() {
  bapp_restore
}

do_status() {
  bapp_status
}

do_uninstall() {
  acquire_lock
  bapp_uninstall
}

binary_app_bootstrap
__DEPLOY_APP_IMPL_SCRIPT_END__

